extends CanvasLayer
const ORDERS := [["heal","Curar aliados"],["gate","Proteger o portão"],["defend","Defender a base"],["patrol","Patrulhar"],["watch","Vigiar a base"],["follow","Me seguir"],["attack","Atacar meu alvo"],["retreat","Recuar para a base"],["stay","Ficar aqui"],["repair","Reparar a base"],["siege","Atacar o portão inimigo"]]
var game
var root: Control
var action_buttons := {}
var subject_buttons := {}
var action := ""
var subject := "todos"
var explicit_subject := false
var opened := false
var recording := false
var waiting := {}
var discard_result := false
var waiting_until := 0
var previous_mouse := Input.MOUSE_MODE_CAPTURED
func setup(world: Node) -> void:game=world;layer=45
func _ready() -> void:
	game.voice.utterance_done.connect(_voice_done)
	set_process_input(true)
func _input(event: InputEvent) -> void:
	if event is InputEventKey and event.physical_keycode==KEY_Q and not event.echo:
		if event.pressed:
			if not opened:open_menu()
		elif opened:close_menu(true)
		if opened or not event.pressed:get_viewport().set_input_as_handled()
	elif opened and event is InputEventKey and event.physical_keycode==KEY_ESCAPE and event.pressed:
		close_menu(false);get_viewport().set_input_as_handled()
	elif opened and event is InputEventKey and event.physical_keycode in [KEY_B,KEY_V,KEY_T]:get_viewport().set_input_as_handled()
func _process(_delta: float) -> void:
	if opened and (not game.gameplay_available() or not game.player.can_act() or get_tree().paused):close_menu(false)
	if not waiting.is_empty() and (Time.get_ticks_msec()>waiting_until or not game.creations_available()):waiting.clear();discard_result=true
func panel_style(color: Color) -> StyleBoxFlat:
	var style:=StyleBoxFlat.new();style.bg_color=color;style.border_color=Color("5d7184")
	style.set_border_width_all(1);style.set_corner_radius_all(8);style.content_margin_left=12;style.content_margin_right=12;style.content_margin_top=8;style.content_margin_bottom=8
	return style
func button(text: String, callback: Callable, list: Container) -> Button:
	var out:=Button.new();out.text=text;out.custom_minimum_size.y=40;out.alignment=HORIZONTAL_ALIGNMENT_LEFT
	out.add_theme_font_size_override("font_size",18);out.add_theme_stylebox_override("normal",panel_style(Color("202c3a")));out.pressed.connect(callback);list.add_child(out);return out
func open_menu() -> void:
	if not waiting.is_empty() or not game.gameplay_available() or not game.player.can_act() or get_tree().paused or game.get_node("HUD").console.is_open:return
	opened=true;action="";subject="todos";explicit_subject=false
	previous_mouse=Input.mouse_mode;Input.mouse_mode=Input.MOUSE_MODE_VISIBLE
	game.player.set_meta("quick_orders_open",true)
	root=Control.new();root.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT);add_child(root)
	var shade:=ColorRect.new();shade.color=Color(0,0,0,.65);shade.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT);root.add_child(shade)
	var panel:=PanelContainer.new();root.add_child(panel);panel.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT);panel.anchor_left=.12;panel.anchor_right=.88;panel.anchor_top=.10;panel.anchor_bottom=.90;panel.add_theme_stylebox_override("panel",panel_style(Color("111a25")))
	var column:=VBoxContainer.new();column.add_theme_constant_override("separation",10);panel.add_child(column)
	var title:=Label.new();title.text="ORDENS RÁPIDAS";title.add_theme_font_size_override("font_size",25);column.add_child(title)
	var help:=Label.new();help.text="Escolha a ordem e quem executa. Solte Q para enviar. Esc cancela.";help.autowrap_mode=TextServer.AUTOWRAP_WORD_SMART;column.add_child(help)
	var row:=HBoxContainer.new();row.add_theme_constant_override("separation",16);row.size_flags_vertical=Control.SIZE_EXPAND_FILL;column.add_child(row)
	var actions:=VBoxContainer.new();actions.size_flags_horizontal=Control.SIZE_EXPAND_FILL;row.add_child(actions)
	var subjects:=VBoxContainer.new();subjects.size_flags_horizontal=Control.SIZE_EXPAND_FILL;row.add_child(subjects)
	for pair in [[actions,"1 · ORDEM"],[subjects,"2 · QUEM EXECUTA"]]:
		var label:=Label.new();label.text=pair[1];pair[0].add_child(label)
	var left:=ScrollContainer.new();left.size_flags_vertical=Control.SIZE_EXPAND_FILL;actions.add_child(left)
	var left_list:=VBoxContainer.new();left_list.size_flags_horizontal=Control.SIZE_EXPAND_FILL;left.add_child(left_list)
	var right:=ScrollContainer.new();right.size_flags_vertical=Control.SIZE_EXPAND_FILL;subjects.add_child(right)
	var right_list:=VBoxContainer.new();right_list.size_flags_horizontal=Control.SIZE_EXPAND_FILL;right.add_child(right_list)
	action_buttons.clear();subject_buttons.clear()
	for entry in ORDERS:action_buttons[entry[0]]=button(entry[1],select_action.bind(entry[0]),left_list)
	subject_buttons["todos"]=button("Todos os meus animais",select_subject.bind("todos"),right_list)
	var counts:Dictionary={}
	for orders in get_tree().get_nodes_in_group("ordered_animals"):
		if orders.thing.owner_id==game.player.player_id and orders.available():counts[orders.thing.thing_id]=int(counts.get(orders.thing.thing_id,0))+1
	var names:=counts.keys();names.sort_custom(func(a,b):return Lexicon.data.thing_name(a)<Lexicon.data.thing_name(b))
	for id:String in names:
		var name:=Lexicon.data.thing_name(id)
		subject_buttons[name]=button(name+" ×"+str(counts[id]),select_subject.bind(name),right_list)
	var aim_id:=aimed_subject()
	if aim_id>0:subject_buttons["id "+str(aim_id)]=button("Só a criatura em que você mirou",select_subject.bind("id "+str(aim_id)),right_list)
	var footer:=Label.new();footer.text="Ou fale só o nome: Pikachu, Gojo, cachorros, todos…\nB continua aceitando frases completas. Clique no nome para enviar sem esperar a voz.";footer.autowrap_mode=TextServer.AUTOWRAP_WORD_SMART;column.add_child(footer)
	recording=game.voice.begin_talk(false,true) if game.voice.is_on() else false
func aimed_subject() -> int:
	var ray:Dictionary=game.player.look_ray();var best:=INF;var result:=0
	for orders in get_tree().get_nodes_in_group("ordered_animals"):
		if orders.thing.owner_id!=game.player.player_id or not orders.available():continue
		var delta:Vector3=orders.thing.center()-ray.origin;var along:float=delta.dot(ray.direction)
		var miss:float=(delta-ray.direction*along).length()
		if along<0 or along>60 or miss>maxf(.6,orders.thing.bounds.size.length()*.35):continue
		var query:=PhysicsRayQueryParameters3D.create(ray.origin,orders.thing.center(),PhysicsLayers.WORLD)
		if not game.player.get_world_3d().direct_space_state.intersect_ray(query).is_empty():continue
		var score:float=miss*10+along
		if score<best:best=score;result=load("res://scripts/things/base_duty.gd").recipient_id(orders.thing)
	return result
func select_action(value: String) -> void:
	action=value
	for id in action_buttons:action_buttons[id].add_theme_stylebox_override("normal",panel_style(Color("345c61") if id==value else Color("202c3a")))
func select_subject(value: String) -> void:
	subject=value;explicit_subject=true
	for id in subject_buttons:subject_buttons[id].add_theme_stylebox_override("normal",panel_style(Color("345c61") if id==value else Color("202c3a")))
func close_menu(send: bool) -> void:
	if not opened:return
	opened=false;game.player.set_meta("quick_orders_open",false);game.player.set_meta("quick_orders_release_mouse",true)
	Input.mouse_mode=previous_mouse
	if is_instance_valid(root):root.queue_free()
	if not send or action.is_empty():
		if recording and not game.voice.cancel_talk():discard_result=true
		recording=false;return
	if explicit_subject:
		if recording and not game.voice.cancel_talk():discard_result=true
		submit(action,subject)
	elif recording:
		waiting={"action":action};waiting_until=Time.get_ticks_msec()+20000;game.voice.end_talk()
	else:game.get_node("HUD").show_voice_prompt("Escolha uma criatura ou Todos no menu Q.")
	recording=false
func submit(order: String, actor: String) -> Dictionary:
	return Forge.request(game.player.player_id,"ordem base "+order+" "+actor,false,true)
func consume_voice(text: String) -> bool:
	if discard_result:return true
	if waiting.is_empty():return false
	var order:=String(waiting.action);waiting.clear();submit(order,text);return true
func _voice_done(info: Dictionary) -> void:
	discard_result=false
	if not waiting.is_empty() and not String(info.get("ignored","")).is_empty():waiting.clear()
func _exit_tree() -> void:
	if is_instance_valid(game) and is_instance_valid(game.player):game.player.set_meta("quick_orders_open",false)
	if opened:Input.mouse_mode=previous_mouse

