var stats: = {"spawned": 0, "explosions": 0, "explosions_blocked": 0, "evicted": 0, "too_deep": 0, "production_paused": 0}
var production := preload("res://scripts/things/production_budget.gd").new()
var _last_anomaly_ms := -1000

func request(player_id: int, text: String, record_unknowns: bool = true, lang: Variant = "", commands_only: bool = false) -> Dictionary:
	# Preserve H-4 language argument and compatibility with the Lab command-only call.
	if lang is bool:
		commands_only = lang
		lang = ""
	if not lang is String: return _blocked_request(player_id, text, tr("Idioma do pedido desconhecido."))
	var invention:Dictionary=load("res://scripts/things/invention_library.gd").local_request(player_id,text)
	if invention.has("expanded"):text=String(invention.expanded)
	elif not invention.is_empty():
		invention.merge({"ok":true,"unknown_words":[],"ignored_words":[],"corrections":[],"cost":0.0,"build_s":0.0})
		request_processed.emit(player_id,text,invention);return invention

