var started := Time.get_ticks_usec()
var creature := String(Lexicon.data.thing_def(String(node.get("thing", ""))).get("category", "")) in ["creature", "vehicle"]
var child_role := "spawned" if role == "projectile" and creature else role

if child_role=="spawned" and creature and launch_speed==0.0 and not child.move.hovers():
	var floor_at:=ground_point(child.global_position,child.up())
	if absf((floor_at-child.global_position).dot(child.up()))<2.0:
		child.global_position=ground_spawn_point(child,floor_at,direction)

var mount := spawner.mount_host
while is_instance_valid(mount):
	if child.is_solid_projectile(): child.ignore_collision_until_clear(mount)
	else: child.add_collision_exception_with(mount)
	mount = mount.mount_host

func ground_spawn_point(child: Thing, at: Vector3, direction: Vector3) -> Vector3:
	var up:=child.up();var forward:=Gravity.flat(direction,up).normalized()
	if forward.length_squared()<.01:forward=-child.global_basis.z
	var side:Vector3=forward.cross(up).normalized()
	var spacing:float=maxf(.55,minf(3.0,maxf(child.bounds.size.x,child.bounds.size.z)*.6))
	var shape:=BoxShape3D.new();shape.size=child.bounds.size.max(Vector3.ONE*.05)
	var query:=PhysicsShapeQueryParameters3D.new();query.shape=shape;query.collision_mask=PhysicsLayers.WORLD|PhysicsLayers.THINGS
	query.exclude=[child.get_rid()]
	if is_instance_valid(child.spawner):query.exclude.append(child.spawner.get_rid())
	if child.owner_player is PhysicsBody3D:query.exclude.append(child.owner_player.get_rid())
	for offset in [Vector3.ZERO,forward*spacing,side*spacing,-side*spacing,-forward*spacing,(forward+side)*spacing,(forward-side)*spacing]:
		var floor_at:=ground_point(at+offset,up)
		if absf((floor_at-at).dot(up))>1.0:continue
		var position:Vector3=floor_at+up*maxf(.06,-child.bounds.position.y+.06)
		query.transform=Transform3D(child.global_basis,position+child.global_basis*child.bounds.get_center())
		if child.get_world_3d().direct_space_state.intersect_shape(query,1).is_empty():return position
	return at+up*maxf(.06,-child.bounds.position.y+.06)

if not CreatureLimit.allows(spawner.owner_id, node): return null
if not production.reserve(spawner.owner_id, live_things(spawner.owner_id).size()):
	stats.production_paused += 1
	return null
if not InnovationRules.authorize_spawn(spawner, node):
	return null
var started := Time.get_ticks_usec()

func production_available(source: Thing) -> bool:
	for component in source.get_children():
		if component is ThingAction and component.production_pending: return false
		if component is ThingAction and component.spec.get("type", "") in ["shoot", "drop", "spawn", "summon"]:
			var node: Dictionary = source.ammo_override if not source.ammo_override.is_empty() else component.arg()
			if not node.is_empty() and ProductionBudget.complex(node, Lexicon.data) and not production.available(source.owner_id, live_things(source.owner_id).size()): return false
	return true


func reserve_anomaly_effect() -> bool:
	var now := Time.get_ticks_msec()
	if now - _last_anomaly_ms < 170: return false
	_last_anomaly_ms = now
	return true



func explosion_ready(player_id: int) -> bool:
	if not has_effect_authority(): return false
	var count := 0
	var now := Engine.get_physics_frames()
	for time in _explosion_times.get(player_id, []):
		if now - int(time) < Engine.physics_ticks_per_second: count += 1
	return count < int(Lexicon.balf("caps.explosions_per_s"))

func transfer_neutral(thing: Thing, team: int) -> void:
	if not is_instance_valid(thing) or not Session.has_authority(): return
	var previous := thing.owner_id
	var family := [thing]
	for item in family: family.append_array(item.grafts)
	for item in family:
		for list in _live.values(): list.erase(item)
	thing.set_owner_info(0,team,null,null)
	_register(thing)
	live_things_changed.emit(previous)

func transfer_owner(thing: Thing, player: Player, source: Thing = null) -> bool:
	if not is_instance_valid(thing) or not is_instance_valid(player) or not Session.has_authority(): return false
	if not CreatureLimit.can_transfer(thing, player.player_id): return false
	var previous := thing.owner_id
	var family := CreatureLimit.family(thing)
	for item in family:
		for list in _live.values(): list.erase(item)
	thing.set_owner_info(player.player_id, player.team, player, source)
	for item in family:
		item.set_owner_info(player.player_id, player.team, player, source)
		_register(item)
	live_things_changed.emit(previous)
	live_things_changed.emit(player.player_id)
	return true

