		"heal":"(?:cur(?:e|em)|ajud(?:e|em)) (?:os |meus )?aliados",
		"gate":"prote(?:ja|jam|ge|ger) (?:o )?portao", "defend":"defend(?:a|am|er) (?:a |minha )?(?:base|castelo)",
		"patrol":"patrulh(?:e|em|ar) (?:a |o |minha |meu )?(?:base|castelo)", "watch":"vigi(?:e|em|ar) (?:a |o |as |os )?(?:base|castelo|torre|torres)",
		"retreat":"(?:recu(?:e|em)|volt(?:e|em)) (?:para|pra|ate) (?:a |o )?(?:base|castelo)",
		"repair":"(?:repar(?:e|em)|consert(?:e|em)) (?:a |o |as )?(?:base|castelo|muralha|muralhas)",
		"siege":"ataqu(?:e|em) (?:o |a )?(?:portao|base|castelo) (?:inimigo|inimiga)"}
