static func disposal(text: String, lex: LexiconData) -> Dictionary:
	var mode := ""
	var target := ""
	var found = match_text("^(?:(?:eu )?quero que )?(?:mate|mata|matem|elimine|elimina|eliminem|remova|removam) (.+)$", text)
