extends ThingAction

static var executed: Dictionary = {}
var _waiting_for_effect := false


func run(ctx: ActionContext) -> void:
	if not thing.has_simulation_authority() or thing.is_dead or not thing.is_inside_tree():
		return
	var mode := String(spec.get("mode", "gravity"))
	if mode == "rift":
		_note(mode)
		_cut_space(ctx)
		return
	if thing.is_held and bool(spec.get("weapon_pulse", false)):
		_note("weapon_" + mode)
		var holder := thing.owner_player as Player
		var point := holder.head.global_position - holder.camera.global_basis.z * 2.0 if holder != null else ctx.point
		var radius := float(spec.get("radius", 4.0))
		ExpansionFx.burst(Forge.fx_root(thing), point, radius, Color.from_string(String(spec.get("color", "#a855f7")), Color.WHITE), mode)
		match mode:
			"repulsion": Combat.impulse(thing, point, radius, 20.0, 0.5)
			"frost": Combat.area_status(thing, point, radius, "frozen")
			"inferno": Combat.area_status(thing, point, radius, "burning")
			_: _damage_area(point, radius, float(spec.get("damage", 25.0)), "electric")
		return
	if thing.is_held or thing.explosion_spent:
		return
	if _waiting_for_effect: return
	_waiting_for_effect = true
	while not Forge.reserve_anomaly_effect():
		await get_tree().create_timer(0.05).timeout
		if not is_instance_valid(thing) or thing.is_dead or not thing.is_inside_tree(): return
	thing.explosion_spent = true
	_note(mode)
	var at := thing.center()
	var radius := clampf(float(spec.get("radius", 8.0)) * thing.scale_factor, 0.5, 18.0)
	var damage := clampf(float(spec.get("damage", 50.0)) * thing.scale_factor, 0.0, 240.0)
	var color := Color.from_string(String(spec.get("color", "#a855f7")), Color.MEDIUM_PURPLE)
	var parent := Forge.fx_root(thing)
	if mode != "nuclear": ExpansionFx.burst(parent, at, minf(radius, 5.0), color, mode)
	match mode:
		"nuclear":
			ExpansionFx.burst(parent, at, radius, Color("ffca52"), "nuclear")
			Combat.explode(thing, at, radius, damage)
		"neutron":
			ExpansionFx.burst(parent, at, radius * 0.9, Color("bce8ef"), "neutron")
			Fx.explosion(parent, at, radius * 0.65, Color("86c3d1"))
			Combat.explode(thing, at, minf(radius * 0.32, 3.2), damage * 0.30)
			_damage_area(at, radius, damage, "neutron", true)
		"gravity", "hypothetical", "singularity", "repulsion":
			await _gravity_field(at, radius, damage, mode, color)
		"frost":
			Combat.area_status(thing, at, radius, "frozen")
			_damage_area(at, radius, damage, "cold")
		"inferno":
			Combat.area_status(thing, at, radius, "burning")
			Combat.explode(thing, at, radius, damage)
		"storm":
			var bolts := 0
			for target in Combat.in_radius(thing, at, radius):
				if Combat.affects(thing, target) and bolts < 12:
					var direction := Combat.center_of(target) - at
					ExpansionFx.rift(parent, at, direction.normalized(), maxf(direction.length(), 0.1), color)
					bolts += 1
			_damage_area(at, radius, damage, "electric")
		"emp":
			Combat.area_status(thing, at, radius, "frozen")
			Combat.impulse(thing, at, radius, 8.0, 0.0)
		"meteor", "cluster":
			var up := thing.up()
			var frame := Gravity.frame_for(up)
			for i in 6:
				var angle := TAU * float(i) / 6.0
				var spread := frame * Vector3(cos(angle), 0.0, sin(angle))
				var child_id := "meteor_fragment" if mode == "meteor" else "cluster_fragment"
				var position := at + spread * (radius * 0.45 if mode == "meteor" else 0.35) + up * (9.0 if mode == "meteor" else 0.7)
				Forge.spawn_child({"thing": child_id}, "projectile", position, - up if mode == "meteor" else (spread + up).normalized(), thing, 16.0 if mode == "meteor" else 6.0)
		_:
			Combat.explode(thing, at, radius, damage)
	if is_instance_valid(thing) and not thing.is_dead:
		thing.die()


func _note(mode: String) -> void:
	executed[mode] = int(executed.get(mode, 0)) + 1


func _damage_area(at: Vector3, radius: float, damage: float, kind: String, living_only: bool = false) -> void:
	var rows := []
	for target in Combat.in_radius(thing, at, radius):
		if not Combat.affects(thing, target): continue
		if living_only and not (target is Player or target.is_in_group(Combat.COMBATANTS_GROUP) or target.get("category") == "creature" or target.has_node("ProtectionEmitter")): continue
		rows.append({"target": weakref(target), "damage": damage, "push": Vector3.ZERO, "type": kind})
	if rows.is_empty(): return
	# Keep the bomb alive until the bounded damage work finishes, as with native blasts.
	var work = load("res://scripts/things/blast_work.gd").new()
	work.setup(thing, rows)
	get_tree().root.add_child(work)


func _gravity_field(at: Vector3, radius: float, damage: float, mode: String, color: Color) -> void:
	thing.velocity = Vector3.ZERO
	thing.set_physics_process(false)
	thing.collision_layer = 0
	thing.collision_mask = 0
	thing.model.hide()
	var pulses := 1 if mode == "repulsion" else (16 if mode == "singularity" else 12)
	for pulse in pulses:
		if not is_instance_valid(thing) or thing.is_dead or not thing.has_simulation_authority():
			return
		if pulse % 3 == 0:
			ExpansionFx.burst(Forge.fx_root(thing), at, radius * 0.5, color, mode)
		for target in Combat.in_radius(thing, at, radius):
			if not Combat.affects(thing, target):
				continue
			var offset := Combat.center_of(target) - at
			var weight := 1.0 - clampf(offset.length() / radius, 0.0, 0.9)
			var up := Gravity.up_at(Combat.center_of(target), thing.up())
			var impulse := - offset.normalized() * 4.5 * weight
			if mode == "singularity":
				impulse *= 1.5
			elif mode == "hypothetical":
				impulse = (up * 4.0 if pulse < 8 else offset.normalized() * 7.0) * weight
			elif mode == "repulsion":
				impulse = (offset.normalized() + up * 0.5) * 32.0 * weight
			impulse *= InnovationRules.force_multiplier(target, thing)
			if target.has_method("apply_knockback"):
				target.call("apply_knockback", impulse)
			elif target is Thing:
				(target as Thing).nudge(impulse)
		if pulses > 1:
			await get_tree().create_timer(0.25, false).timeout
	if is_instance_valid(thing) and not thing.is_dead:
		_damage_area(at, radius, damage, "gravity")
		ExpansionFx.burst(Forge.fx_root(thing), at, radius, color, mode)


func _cut_space(ctx: ActionContext) -> void:
	var was_held := thing.is_held
	await get_tree().create_timer(.10, false).timeout
	if not is_instance_valid(thing) or not thing.can_act() or thing.is_captured or thing.is_held != was_held: return
	var holder := thing.owner_player as Player
	var origin := holder.head.global_position if thing.is_held and holder != null else thing.center()
	var direction := - holder.camera.global_basis.z if thing.is_held and holder != null else ctx.direction
	if direction.length_squared() < 0.001:
		direction = - thing.global_basis.z
	direction = direction.normalized()
	var reach := clampf(float(spec.get("reach", 4.2)) * thing.scale_factor, 2.0, 7.0)
	var damage := float(spec.get("damage", 48.0)) * thing.power * lerpf(1.0, 1.5, clampf(ctx.charge, 0.0, 1.0))
	var effect = load("res://scripts/fx/space_sword.gd")
	var curve: PackedVector3Array = effect.points(origin, direction, thing.up(), reach)
	effect.play(Forge.fx_root(thing), origin, direction, thing.up(), reach)
	var rows := []
	for target in JujutsuRules.candidates(get_tree()):
		if not is_instance_valid(target) or target == thing or target == thing.owner_player or not target.has_method("take_damage") or not Combat.affects(thing, target): continue
		if target is Thing and (target.is_dead or target.is_captured or target.is_held): continue
		var at := Combat.center_of(target)
		if (at - origin).dot(direction) < 0: continue
		var radius: float = minf(1.5, target.bounds.size.length() * .25) if target is Thing else .6
		var touched := false
		for i in 8:
			if Geometry3D.get_closest_point_to_segment(at, curve[i], curve[i+1]).distance_to(at) <= radius + .3: touched = true; break
		if not touched: continue
		rows.append({"target": weakref(target), "damage": damage, "push": Vector3.ZERO, "type": "world_cut"})
		if rows.size() >= 8: break
	if not rows.is_empty():
		var work = load("res://scripts/things/blast_work.gd").new()
		work.setup(thing, rows)
		get_tree().root.add_child(work)
	var terrain = load("res://scripts/things/spatial_cut_work.gd").new()
	terrain.setup(thing)
	get_tree().root.add_child(terrain)
	for i in 8: terrain.add_segment(curve[i], curve[i+1], .28)

extends ThingAction

var cooldown := 0.0
func _physics_process(delta: float) -> void:
	if thing.has_simulation_authority(): cooldown = maxf(0.0,cooldown-delta)
func run(ctx: ActionContext) -> void:
	if not thing.has_simulation_authority() or not thing.can_act() or cooldown > 0.0: return
	var mode := String(spec.get("mode","age"))
	var origin := ctx.point
	var direction := ctx.direction
	if thing.is_held and thing.owner_player is Player:
		origin = thing.owner_player.head.global_position
		direction = -thing.owner_player.camera.global_basis.z
	var candidates := []
	for target in Combat.in_radius(thing,origin,24.0 if mode != "charm" else 5.0):
		if not target is Thing or target.category != "creature" or not Combat.affects(thing,target): continue
		var effects := target.get_node_or_null("CreativeEffects")
		if effects == null or not effects.available(): continue
		var offset: Vector3 = target.center()-origin
		if mode != "charm" and offset.normalized().dot(direction) < .92: continue
		var ray := PhysicsRayQueryParameters3D.create(origin,target.center(),PhysicsLayers.WORLD)
		if not thing.get_world_3d().direct_space_state.intersect_ray(ray).is_empty(): continue
		candidates.append(effects)
	candidates.sort_custom(func(a,b): return a.thing.center().distance_squared_to(origin) < b.thing.center().distance_squared_to(origin))
	var success := false
	if mode == "swap" and candidates.size() >= 2:
		success = load("res://scripts/things/creative_effects.gd").swap(candidates[0],candidates[1],thing)
	elif mode == "age" and not candidates.is_empty(): success = candidates[0].age(thing)
	elif mode == "charm":
		for effect in candidates.slice(0,8): success = effect.charm(thing) or success
	if not success and mode != "charm": return
	cooldown = 12.0 if mode == "swap" else 5.0 if mode == "age" else 18.0
	if mode != "charm":
		var at: Vector3 = candidates[0].thing.center()
		load("res://scripts/fx/pokemon_fx.gd").play(Forge.fx_root(thing),origin,at,"vine" if mode == "age" else "electric","Envelhecimento · 6 s" if mode == "age" else "Troca de cabeças · 8 s")
	else:
		ExpansionFx.burst(Forge.fx_root(thing),origin,5.0,Color("ec94df"),"team_charm")
		thing.die()

extends ThingAction
func run(ctx:ActionContext) -> void:
 var kit=thing.get_node_or_null("Crossover")
 if kit!=null:kit.use(ctx,String(spec.get("mode","")))

extends ThingAction

func run(ctx: ActionContext) -> void:
	var user = thing.get_node_or_null("Jujutsu")
	if user != null and thing.has_simulation_authority(): user.cast(ctx)

extends ThingAction

var started := false

func run(_ctx: ActionContext) -> void:
	if started or not thing.has_simulation_authority() or thing.is_dead or thing.is_held: return
	var species := String(thing.node_data.get("mods", {}).get("target_species", ""))
	if species.is_empty(): return
	started = true
	thing.explosion_spent = true
	var victims := []
	for candidate in Forge.world.get_node("Things").get_children():
		var animal := candidate as Thing
		if animal != null and not animal.is_dead and animal.category == "creature" and animal.thing_id == species:
			victims.append(weakref(animal))
	ExpansionFx.burst(Forge.fx_root(thing), thing.center(), 5.0, Color("b7e87e"), "species")
	# One global pulse, with bounded cleanup instead of hundreds of death explosions/rubble piles.
	for i in victims.size():
		var animal = victims[i].get_ref()
		if is_instance_valid(animal) and not animal.is_dead:
			animal.hp = 0.0
			animal.remove()
		if i % 3 == 2: await get_tree().process_frame
	if is_instance_valid(thing) and not thing.is_dead: thing.remove()

extends Node

var thing: Thing
var mode := "free"
var point := Vector3.ZERO
var goal := Vector3.ZERO
var target_ref: WeakRef
var house_ref: WeakRef
var tick_left := 0.0
var bite_left := 0.0
var last_label := ""
var automatic_ref: WeakRef
var automatic_active := false
var navigation_left := 0.0
var navigation_goal := Vector3.ZERO
static var bomb_cache := []
static var bomb_cache_until := 0
static var bomb_world := 0

func setup(owner_thing: Thing) -> void: thing = owner_thing
func _ready() -> void:
	add_to_group("ordered_animals")
	process_physics_priority = -35
	tick_left = float(thing.get_instance_id() % 11) * .018
	if thing._def.get("default_order", "") == "follow":
		mode = "follow"
		tick_left = 0.0
	if bool(thing.node_data.get("mods", {}).get("aggressive", false)):
		mode = "aggressive"
		tick_left = 0.0
	if InnovationRules.target_diet(thing).begins_with("player:"):
		mode = "attack"
		tick_left = 0.0

static func of(source: Thing) -> Node:
	var cursor := source
	var seen := {}
	for step in 8:
		if not is_instance_valid(cursor) or seen.has(cursor.get_instance_id()): return null
		seen[cursor.get_instance_id()] = true
		if cursor.category == "structure": return null
		var orders := cursor.get_node_or_null("AnimalOrders")
		if orders != null: return orders
		cursor = cursor.mount_host if is_instance_valid(cursor.mount_host) else cursor.spawner as Thing
	return null

func active() -> bool:
	var rig=thing.get_node_or_null("CreatureTactics")
	return mode!="free" or automatic_active or (rig!=null and rig.being_carried())
func available() -> bool:
	return is_instance_valid(thing) and thing.can_act() and not thing.is_captured and not thing.is_held
func combat_target() -> Node3D:
	var rival := JujutsuRules.rival_target(thing)
	if rival != null: return rival
	var filter := InnovationRules.target_diet(thing)
	if filter.begins_with("player:"):
		var chosen = Forge.world.get_player(int(filter.trim_prefix("player:"))) if Forge.world != null else null
		return chosen if _enemy(chosen) else null
	var target = target_ref.get_ref() if target_ref != null else null
	if target == null and automatic_ref != null: target = automatic_ref.get_ref()
	var rig=thing.get_node_or_null("CreatureTactics")
	if target==null and rig!=null and rig.being_carried():target=rig.carried_target()
	return target if _enemy(target) else null
func _enemy(target: Object) -> bool:
	if not is_instance_valid(target) or target == thing or target == thing.owner_player or not target.has_method("take_damage"): return false
	if target.has_method("is_alive") and not target.is_alive(): return false
	if target is Thing and (target.is_dead or target.is_captured or target.is_held): return false
	if target.get("team") != null and load("res://scripts/things/coop_encounter.gd").allied(thing.team,int(target.get("team"))): return false
	return (mode == "aggressive" or target.get("team") != thing.team) and InnovationRules.allows_target(thing, target)
func allows(target: Object) -> bool:
	if automatic_active: return target == combat_target()
	return mode == "free" or ((mode.begins_with("base_") or mode in ["attack", "guard", "guard_pack", "retaliate", "aggressive", "tactical"]) and target == combat_target())

static func request(player: Node3D, settings: Dictionary) -> Dictionary:
	if not player.can_act(): return {"blocked": true, "warnings": ["Você não pode dar ordens agora."]}
	var ray: Dictionary = player.look_ray()
	var selected: Node
	var recipients: Array[Node] = []
	var group := bool(settings.get("all", false))
	var best := INF
	var species := String(settings.get("species", ""))
	for orders in player.get_tree().get_nodes_in_group("ordered_animals"):
		if not orders.available() or orders.thing.owner_id != player.player_id or orders.thing.team != player.team: continue
		if not species.is_empty() and orders.thing.thing_id != species: continue
		var at: Vector3 = orders.thing.center()
		var distance := player.global_position.distance_to(at)
		if distance > Lexicon.balf("animal_orders.range_m"): continue
		var offset: Vector3 = at - ray.origin
		var along: float = offset.dot(ray.direction)
		var miss: float = (offset - ray.direction * along).length()
		if not group and species.is_empty() and (along < 0 or miss > maxf(1.2, orders.thing.bounds.size.length() * .5)): continue
		var query := PhysicsRayQueryParameters3D.create(ray.origin, at, PhysicsLayers.WORLD)
		if not player.get_world_3d().direct_space_state.intersect_ray(query).is_empty(): continue
		recipients.append(orders)
		var score := miss * 8.0 + distance
		if score < best:
			best = score
			selected = orders
	if selected == null: return {"blocked": true, "warnings": ["Aponte para um animal seu ou diga o nome dele. Ele precisa estar visível e a até 60 m."]}
	if group:
		var changed := 0
		var ids := []
		var warning := ""
		for orders in recipients:
			var reply := _apply_order(player, settings, orders, ray)
			if not reply.get("blocked", false):
				changed += 1
				ids.append(orders.thing.network_id)
			elif not reply.get("warnings", []).is_empty(): warning = reply.warnings[0]
		if changed == 0: return {"blocked": true, "warnings": [warning]}
		return {"animal_order": settings.animal_order, "animal_count": changed, "animal_network_ids": ids, "warnings": ["Ordem recebida por %d criaturas suas." % changed]}
	return _apply_order(player, settings, selected, ray)

static func _apply_order(player: Node3D, settings: Dictionary, selected: Node, ray: Dictionary) -> Dictionary:
	var action := String(settings.animal_order)
	var bond = selected.thing.get_node_or_null("CreatureBond")
	if action in ["attack","aggressive"] and bond != null and bond.refuses_danger():
		return {"blocked":true,"warnings":["Muito ferido e assustado para atacar. Cuide da criatura ou mande recuar."]}
	var target: Node3D
	if action == "target_player":
		var id := int(settings.get("target_player",0))
		if id < 1 or id > 4 or id == player.player_id: return {"blocked":true,"warnings":["Escolha outro jogador, de 1 a 4."]}
		selected.thing.node_data.get_or_add("mods",{}).target_player = id
		selected.thing.target_filter = "player:%d" % id
		selected.set_order("attack",selected.thing.global_position)
		selected.last_label = "Só ataca o jogador %d." % id
		return {"animal_order":action,"target_player":id,"warnings":[selected.last_label]}
	if action == "attack":
		var alignment := .45
		var candidates := player.get_tree().get_nodes_in_group(Combat.COMBATANTS_GROUP)
		if Forge.world != null: candidates.append_array(Forge.world.get_node("Things").get_children())
		for candidate in candidates:
			if not selected._enemy(candidate) or candidate.get("team") == selected.thing.team: continue
			if candidate is Thing and candidate.category not in ["creature", "vehicle"]: continue
			var direction: Vector3 = Combat.center_of(candidate) - ray.origin
			if direction.length() > 60.0: continue
			var value: float = direction.normalized().dot(ray.direction)
			if value > alignment:
				var query := PhysicsRayQueryParameters3D.create(ray.origin, Combat.center_of(candidate), PhysicsLayers.WORLD)
				if not player.get_world_3d().direct_space_state.intersect_ray(query).is_empty(): continue
				alignment = value
				target = candidate
		if target == null: return {"blocked": true, "warnings": ["Mire num jogador ou criatura inimiga que esse animal possa atacar. A dieta continua valendo."]}
	var aim: Dictionary = player.aim()
	var at: Vector3 = aim.point if aim.get("collider") != null else player.global_position + ray.direction * 5.0
	if action in ["follow", "stay", "retaliate", "evade", "free", "aggressive"]: at = selected.thing.global_position
	if action == "guard": at = selected._house_point(player, at)
	if action == "build":
		var builder = selected.thing.get_node_or_null("CreatureBuilder")
		if builder == null: return {"blocked": true, "warnings": ["Esse animal não constrói. Use formiga, castor ou aranha."]}
		if selected.thing.global_position.distance_to(at) > 20.0: return {"blocked": true, "warnings": ["Escolha um local de trabalho a até 20 m do animal."]}
		var reply: Dictionary = builder.begin(at, ray.direction)
		if reply.get("blocked", false): return reply
		at = builder.work_point
	selected.set_order(action, at, target)
	var names := {"follow": "me siga", "stay": "fique aqui", "guard": "proteja a casa", "attack": "ataque o alvo", "evade": "fuja das bombas", "retaliate": "ataque só quem me atacar", "free": "volte ao normal", "build": "construa aqui", "aggressive": "agressivo · poupa você"}
	selected.last_label = Lexicon.data.thing_name(selected.thing.thing_id) + ": " + String(names.get(action, action))
	if action == "build": selected.last_label += " · " + selected.thing.get_node("CreatureBuilder").requirements()
	ExpansionFx.burst(Forge.fx_root(player), selected.thing.center(), .5, Color("9dcdb4"), "animal_order")
	return {"animal_order": action, "animal_network_id": selected.thing.network_id, "warnings": [selected.last_label]}

func set_order(action: String, at: Vector3, target: Node3D = null) -> void:
	automatic_ref = null
	automatic_active = false
	var tactics := thing.get_node_or_null("CreatureTactics")
	if tactics != null and action != "tactical": tactics.cancel_rule()
	if action != "guard": house_ref = null
	if action != "build":
		var builder := thing.get_node_or_null("CreatureBuilder")
		if builder != null: builder.cancel()
	mode = String(thing._def.get("default_order", "free")) if action == "free" else action
	navigation_left=0.0
	point = at
	goal = at
	target_ref = weakref(target) if target != null else null
	tick_left = 0.0
	thing.move.steering = active()

func _house_point(player: Node3D, aim: Vector3) -> Vector3:
	house_ref = null
	var best := 25.0
	var result := thing.global_position
	for candidate in Forge.world.get_node("Things").get_children():
		if not candidate is Thing or candidate.is_dead or candidate.owner_id != thing.owner_id or not ("house" in candidate.thing_id or candidate._def.get("castle_base",false)): continue
		var distance: float = candidate.global_position.distance_to(aim)
		if distance < best:
			best = distance
			result = candidate.global_position
			house_ref = weakref(candidate)
	for structure in get_tree().get_nodes_in_group(Structure.STRUCTURES):
		if "house" not in structure.blueprint_id or structure.global_position.distance_to(player.global_position) > 25.0: continue
		var distance: float = structure.global_position.distance_to(aim)
		if distance < best:
			best = distance
			result = structure.global_position
			house_ref = weakref(structure)
	return result

func _physics_process(delta: float) -> void:
	if thing.get_meta("ridden",false):return
	if not available(): return
	bite_left = maxf(0.0, bite_left - delta)
	tick_left -= delta
	if tick_left > 0: return
	tick_left = Lexicon.balf("animal_orders.tick_s")
	var carried=thing.get_node_or_null("CreatureTactics")
	if carried!=null and carried.being_carried():
		var target=carried.carried_target()
		if target!=null:_attack(target)
		return
	if mode.begins_with("base_"):
		var base_target:=combat_target()
		if base_target!=null:_attack(base_target)
		return
	var owner := thing.owner_player
	if not is_instance_valid(owner) or not owner.is_alive():
		automatic_ref = null
		automatic_active = false
		goal = thing.global_position
		return
	_automatic_reaction(owner)
	if not active(): return
	match mode:
		"follow":
			goal = owner.global_position
			if bool(thing._def.get("verity_companion", false)):
				goal += owner.global_basis.x * 1.7 + thing.up() * 1.6
		"stay", "guard": goal = point
		"retaliate":
			goal = owner.global_position
			var recent: Dictionary = owner.get_meta("animal_last_attacker", {})
			var attacker = recent.source.get_ref() if recent.has("source") and Time.get_ticks_msec() - int(recent.get("at", 0)) < int(Lexicon.balf("animal_orders.retaliation_s") * 1000) else null
			target_ref = weakref(attacker) if _enemy(attacker) and thing.global_position.distance_to(Combat.center_of(attacker)) < 30.0 else null
		"evade": goal = _escape_point()
		"guard_pack":
			goal = owner.global_position
			target_ref = null
			var nearest := 18.0
			for ally in Combat.in_radius(thing,thing.center(),18.0):
				if not ally is Thing or ally.owner_id != thing.owner_id or ally.category != "creature": continue
				var recent: Dictionary = ally.get_meta("animal_last_attacker",{})
				var attacker = recent.source.get_ref() if recent.has("source") and Time.get_ticks_msec()-int(recent.get("at",0)) < 6000 else null
				if not _enemy(attacker): continue
				var distance: float = thing.center().distance_to(Combat.center_of(attacker))
				if distance < nearest: nearest = distance; target_ref = weakref(attacker)
		"aggressive":
			# Keep searching ahead instead of freezing when the front cone is empty.
			goal = thing.global_position - thing.global_basis.z * maxf(3.0, thing.speed)
			target_ref = null
			var best := 18.0
			for candidate in Combat.in_radius(thing, thing.center(), best):
				if not _enemy(candidate) or (candidate is Thing and candidate.category not in ["creature", "vehicle", "structure"]): continue
				var offset := Combat.center_of(candidate) - thing.center()
				if offset.normalized().dot(-thing.global_basis.z) < .2: continue
				if offset.length() < best:
					best = offset.length()
					target_ref = weakref(candidate)
	if mode == "guard":
		var house = house_ref.get_ref() if house_ref != null else null
		if is_instance_valid(house): point = house.global_position; goal = point
		target_ref = null
		var best := Lexicon.balf("animal_orders.guard_radius_m")
		for candidate in Combat.in_radius(thing, point, best):
			if not _enemy(candidate): continue
			var distance := point.distance_to(Combat.center_of(candidate))
			if distance < best:
				best = distance
				target_ref = weakref(candidate)
	var target := combat_target()
	if target != null:
		goal = Combat.center_of(target)
		_attack(target)
	elif mode == "attack" and not InnovationRules.target_diet(thing).begins_with("player:"):
		mode = "stay"
		point = thing.global_position
		goal = point

func _automatic_reaction(owner: Node3D) -> void:
	automatic_ref = null
	automatic_active = false
	if JujutsuRules.rival_target(thing) != null: return
	if mode not in ["free","follow"] or thing.get_node_or_null("CoopBoss") != null: return
	if mode == "free":
		var titan := Combat.nearest_enemy_kaiju(thing,thing.center(),get_tree())
		if titan != null:
			automatic_ref = weakref(titan)
			automatic_active = true
			last_label = "Enfrentando kaiju inimigo"
			return
	var victims: Array = [thing]
	if thing.center().distance_to(Combat.center_of(owner)) <= 10.0: victims.append(owner)
	for victim in victims:
		var record: Dictionary = victim.get_meta("animal_last_attacker",{})
		if not record.has("source") or Time.get_ticks_msec()-int(record.get("at",0)) > 6000: continue
		var attacker = record.source.get_ref()
		if not _enemy(attacker) or thing.center().distance_to(Combat.center_of(attacker)) > 18.0: continue
		var ray := PhysicsRayQueryParameters3D.create(thing.center(),Combat.center_of(attacker),PhysicsLayers.WORLD)
		if not thing.get_world_3d().direct_space_state.intersect_ray(ray).is_empty(): continue
		automatic_ref = weakref(attacker)
		automatic_active = true
		last_label = "Reagindo ao agressor" if victim == thing else "Protegendo o treinador"
		return

func _escape_point() -> Vector3:
	var now := Time.get_ticks_msec()
	var world_id := Forge.world.get_instance_id()
	if now >= bomb_cache_until or bomb_world != world_id:
		bomb_cache_until = now + 300
		bomb_world = world_id
		bomb_cache.clear()
		for candidate in Forge.world.get_node("Things").get_children():
			if not candidate is Thing or candidate.is_dead or candidate.is_captured or candidate.is_held: continue
			if not candidate.explosion_spent and (candidate.get_node_or_null("Do_explode") != null or "bomb" in candidate.thing_id or "grenade" in candidate.thing_id):
				bomb_cache.append({"point": candidate.center(), "radius": maxf(7.0, candidate.explosion_radius + 3.0)})
			if bomb_cache.size() >= 64: break
	var away := Vector3.ZERO
	for bomb in bomb_cache:
		var offset: Vector3 = thing.global_position - bomb.point
		var distance := offset.length()
		if distance < minf(float(bomb.radius), 22.0): away += offset.normalized() * (1.0 - distance / float(bomb.radius)) if distance > .01 else thing.global_basis.x
	return thing.global_position + Gravity.flat(away, thing.up()).normalized() * 8.0 if away.length_squared() > .001 else thing.owner_player.global_position

func drive(delta: float) -> void:
	var airborne := thing.move.hovers()
	navigation_left-=delta
	if navigation_left<=0:
		navigation_left=.2
		var craft=thing.get_node_or_null("CreatureCraft")
		var destination:Vector3=craft.navigate(goal) if craft!=null else goal
		navigation_goal=destination if airborne else load("res://scripts/things/castle_base.gd").route_for(thing,destination)
	var rig=thing.get_node_or_null("CreatureTactics")
	var rider=rig.passenger() if rig!=null else null
	var carrying_attack:bool=airborne and is_instance_valid(rider) and combat_target()!=null
	var destination:Vector3=navigation_goal-(rider.center()-thing.global_position) if carrying_attack else navigation_goal
	var offset := destination - thing.global_position
	if not airborne: offset = Gravity.flat(offset, thing.up())
	var distance := offset.length()
	var stopping := 2.5 if mode in ["follow", "retaliate", "evade", "tactical"] and combat_target() == null else .4
	if mode == "follow" and bool(thing._def.get("verity_companion", false)): stopping = .45
	if combat_target() != null: stopping = maxf(1.1, thing.bounds.size.length() * .3)
	if carrying_attack:stopping=.65
	if navigation_goal.distance_squared_to(goal)>.01:stopping=.2
	if distance <= stopping:
		thing.velocity = Vector3.ZERO if airborne else thing.up() * thing.velocity.dot(thing.up())
		if not airborne:
			thing.move.steering = true
			thing.move.step(delta)
		return
	var direction := offset.normalized()
	if not airborne:
		var motion:Vector3=direction*maxf(thing.speed,0.0)*delta
		if thing.test_move(thing.global_transform,motion):
			var raised:Transform3D=thing.global_transform
			raised.origin+=thing.up()*.85
			if not thing.test_move(thing.global_transform,thing.up()*.85) and not thing.test_move(raised,motion):thing.move_and_collide(thing.up()*.85)
	# A short feeler steers around walls without teleporting or adding speed.
	var query := PhysicsRayQueryParameters3D.create(thing.center(), thing.center() + direction * 1.2, PhysicsLayers.WORLD)
	var hit := thing.get_world_3d().direct_space_state.intersect_ray(query)
	if not hit.is_empty(): direction = Gravity.flat(direction.rotated(thing.up(), .85), thing.up()).normalized()
	thing.velocity = direction * maxf(thing.speed, 0.0) * load("res://scripts/things/creature_tactics.gd").speed_factor(thing) + (thing.up() * thing.velocity.dot(thing.up()) if not airborne else Vector3.ZERO)
	thing.move.steering = true
	thing.move.step(delta)
	if direction.length_squared() > .001: thing.face(direction, thing.upright or not airborne)

func _attack(target: Node3D) -> void:
	if not available(): return
	if target is Thing and target.category == "structure" and mode == "base_siege":
		if thing.center().distance_to(goal)<maxf(3.5,thing.bounds.size.length()*.4) and bite_left<=0:
			bite_left=.8
			Combat.apply_damage(target,maxf(4,thing.impact_damage),"bite",thing)
			if target.voxel_damage!=null:target.voxel_damage.chip(thing.center())
		return
	var query := PhysicsRayQueryParameters3D.create(thing.center(), Combat.center_of(target), PhysicsLayers.WORLD|PhysicsLayers.THINGS if mode.begins_with("base_") else PhysicsLayers.WORLD,[thing.get_rid()])
	var barrier:=thing.get_world_3d().direct_space_state.intersect_ray(query)
	if not barrier.is_empty() and barrier.collider!=target:return
	var pokemon := thing.get_node_or_null("PokemonCompanion")
	var fusion := thing.get_node_or_null("FusionPowers")
	if fusion != null: fusion.auto_attack()
	if pokemon != null and pokemon.remaining <= 0.0: pokemon.cast(String(pokemon.moves.keys()[0]))
	var reach := maxf(1.2, thing.bounds.size.length() * .45)
