extends Node
var thing: Thing
var base_ref: WeakRef
var role:=""
var route_index:=0
var tick:=0.0
var heal_after:=0
var base_id:=0
static var scan_frame:=-1
static var scans:=0
func setup(body: Thing) -> void:thing=body
func _ready() -> void:process_physics_priority=-40;tick=float(thing.get_instance_id()%11)*.025
func base():return base_ref.get_ref() if base_ref!=null else null
func assign(home: Node, duty: String) -> void:
	base_ref=weakref(home);base_id=home.thing.network_id;role=duty;route_index=int(thing.get_instance_id()%4)
	thing.get_node("AnimalOrders").set_order("base_"+duty,thing.global_position)
func _physics_process(delta: float) -> void:
	if thing.get_meta("ridden",false):return
	if not thing.has_simulation_authority() or not thing.can_act() or thing.is_held or thing.is_captured:return
	var transport=thing.get_node_or_null("CreatureTactics")
	if transport!=null and transport.being_carried():return
	tick-=delta
	if tick>0:return
	tick=.25
	var orders:=thing.get_node("AnimalOrders")
	if orders.mode=="free" and thing._def.get("jj_character","")=="" and InnovationRules.target_diet(thing).is_empty():
		var home=load("res://scripts/things/castle_base.gd").own(thing.owner_id,get_tree())
		if home!=null and thing.global_position.distance_to(home.thing.global_position)<24:assign(home,"patrol")
	if not String(orders.mode).begins_with("base_"):return
	var home=base()
	if not is_instance_valid(home) or not home.usable():orders.set_order("free",thing.global_position);base_ref=null;return
	var spot:Vector3=home.point(Vector3(0,.3,-5.5))
	if role=="defend":spot=home.point(home.POINTS[[0,1,3,2][route_index%4]])
	if role=="gate":spot=home.point(Vector3(float(thing.get_instance_id()%5-2)*.9,.3,-5.5 if thing.bounds.size.x<3 else -10))
	if role in ["patrol","watch"]:
		var point_index:int=[0,1,3,2][route_index%4] if home.inside(thing.global_position) and thing.bounds.size.x<3 else [6,7,9,8][route_index%4]
		spot=home.point(home.POINTS[point_index])
		if thing.move.hovers():spot+=thing.up()*6.0
		if role=="watch" and thing.move.hovers():spot=home.point(Vector3(-8 if route_index%2==0 else 8,8,-6 if route_index<2 else 6))
		if Gravity.flat(spot-thing.global_position,thing.up()).length()<1.4:route_index=(route_index+1)%4
	elif role=="heal":spot=_heal(home)
	elif role=="retreat":spot=home.point(Vector3(-4,.3,0))
	elif role=="repair":spot=home.point(Vector3(0,.3,-5));home.repair(thing)
	elif role=="siege":
		var door=home.gate();var blocked:bool=is_instance_valid(door) and not door.is_dead and home.gate_lift<.7
		var target:Thing=door if blocked else home.thing
		orders.target_ref=weakref(target)
		orders.goal=home.point(Vector3(0,.3,-10) if blocked else Vector3(0,.3,-3))
		orders.last_label="Atacar a entrada inimiga";return
	var target:Node3D=null
	if role not in ["retreat","repair","heal"]:
		var best:=28.0
		var sight_checks:=0
		if scan_frame!=Engine.get_physics_frames():scan_frame=Engine.get_physics_frames();scans=0
		for candidate in Combat.in_radius(thing,home.thing.global_position,best):
			if scans>=8 or sight_checks>=4:break
			if not orders._enemy(candidate) or (candidate.has_method("is_alive") and not candidate.is_alive()):continue
			var distance:float=thing.center().distance_to(Combat.center_of(candidate))
			if distance>20 or distance>=best:continue
			sight_checks+=1;scans+=1
			var ray:=PhysicsRayQueryParameters3D.create(thing.center(),Combat.center_of(candidate),PhysicsLayers.WORLD|PhysicsLayers.THINGS,[thing.get_rid()])
			var hit:=thing.get_world_3d().direct_space_state.intersect_ray(ray)
			if not hit.is_empty() and hit.collider!=candidate:continue
			best=distance;target=candidate
		var alarm=home.alerted()
		if target==null and orders._enemy(alarm) and alarm.global_position.distance_to(home.thing.global_position)<28 and alarm.global_position.distance_to(thing.global_position)<20:target=alarm
	if target!=null:
		home.warn(target)
		spot=Combat.center_of(target)
		if role=="gate" and Gravity.flat(spot-home.point(Vector3(0,.3,-5.5)),thing.up()).length()>8:spot=home.point(Vector3(0,.3,-5.5))
	orders.target_ref=weakref(target) if target!=null else null
	orders.goal=spot
	orders.last_label={"gate":"Proteger o portão","defend":"Defender a base","patrol":"Patrulhar","watch":"Vigiar a base","repair":"Reparar a base","heal":"Curar aliados","retreat":"Recuar para a base"}.get(role,role)
static func recipient_id(body: Thing) -> int:return body.network_id if body.network_id>0 else body.get_instance_id()
static func request(player: Player, settings: Dictionary) -> Dictionary:
	if not player.can_act() or settings.get("invalid",false):return {"blocked":true,"warnings":["Escolha um nome de criatura sua ou Todos."]}
	var action:=String(settings.get("action",""))
	if action not in ["heal","follow","stay","attack","gate","defend","patrol","watch","retreat","repair","siege"]:return {"blocked":true}
	var aimed_base:Node=null
	if action=="attack":
		var collider=player.aim().get("collider")
		if collider is Thing:
			aimed_base=collider.get_node_or_null("CastleBase")
			if aimed_base==null and collider._def.get("castle_gate",false) and is_instance_valid(collider.spawner):aimed_base=collider.spawner.get_node_or_null("CastleBase")
			if aimed_base!=null and aimed_base.thing.team!=player.team:action="siege"
	var recipients:=[]
	for orders in player.get_tree().get_nodes_in_group("ordered_animals"):
		if not orders.available() or orders.thing.owner_id!=player.player_id:continue
		if int(settings.get("target_id",0))>0 and recipient_id(orders.thing)!=int(settings.target_id):continue
		if not String(settings.get("species","")).is_empty() and orders.thing.thing_id!=settings.species:continue
		recipients.append(orders)
	if recipients.is_empty():return {"blocked":true,"warnings":["Nenhuma criatura sua disponível para essa ordem."]}
	if action in ["follow","stay","attack"]:
		var changed:=0
		for orders in recipients:
			var reply:Dictionary=load("res://scripts/things/animal_orders.gd")._apply_order(player,{"animal_order":action},orders,player.look_ray())
			if not reply.get("blocked",false):changed+=1
		return {"blocked":changed==0,"base_order_count":changed,"warnings":["Ordem recebida por %d criaturas."%changed]}
	var home=load("res://scripts/things/castle_base.gd").own(player.player_id,player.get_tree())
	if action=="siege":
		home=aimed_base;var distance:=0.0 if aimed_base!=null else INF
		for candidate in player.get_tree().get_nodes_in_group("castle_bases"):
			if not candidate.usable() or candidate.thing.team==player.team or load("res://scripts/things/coop_encounter.gd").allied(player.team,candidate.thing.team):continue
			var current:float=player.global_position.distance_to(candidate.thing.global_position)
			if current<distance:home=candidate;distance=current
	if home==null:return {"blocked":true,"warnings":["Crie e termine sua base primeiro." if action!="siege" else "Nenhum castelo inimigo disponível."]}
	var changed:=0
	for orders in recipients:
		if action=="heal" and not healer(orders.thing):continue
		if action=="repair" and orders.thing.thing_id!="ant":continue
		orders.thing.get_node("BaseDuty").assign(home,action);changed+=1
	return {"blocked":changed==0,"base_order_count":changed,"warnings":["%d criaturas receberam a ordem."%changed if changed>0 else "Use Squirtle ou criaturas curandeiras para curar; formigas para reparar."]}
static func healer(actor:Thing) -> bool:
	return actor.thing_id in ["squirtle","wartortle","blastoise"] or bool(actor.node_data.get("mods",{}).get("healer",false))
func _heal(home:Node) -> Vector3:
	var fallback:Vector3=home.point(Vector3(-3,.3,1))
	if not healer(thing):return fallback
	var patient:Node3D;var lowest:=1.0
	for candidate in Combat.in_radius(thing,thing.center(),10):
		if candidate.get("team")!=thing.team or not candidate.has_method("take_damage"):continue
		if candidate is Thing and (candidate.is_dead or candidate.is_captured or candidate.is_held or candidate.category!="creature"):continue
		if candidate is Player and not candidate.is_alive():continue
		var hp:float=candidate.health if candidate is Player else candidate.hp
		var maximum:float=Lexicon.balf("player.max_health") if candidate is Player else candidate.max_hp
		if maximum<=0:continue
		var ratio:=hp/maximum
		if ratio<lowest:
			var ray:=PhysicsRayQueryParameters3D.create(thing.center(),Combat.center_of(candidate),PhysicsLayers.WORLD|PhysicsLayers.THINGS,[thing.get_rid()])
			var hit:=thing.get_world_3d().direct_space_state.intersect_ray(ray)
			if not hit.is_empty() and hit.collider!=candidate:continue
			patient=candidate;lowest=ratio
	if patient==null:return fallback
	if thing.center().distance_to(Combat.center_of(patient))<=6 and Time.get_ticks_msec()>=heal_after and is_instance_valid(thing.owner_player):
		heal_after=Time.get_ticks_msec()+1000
		if thing.owner_player.try_spend(2):
			Combat.heal(patient,4)
			Fx.ring(Forge.fx_root(thing),Combat.center_of(patient),.7,Color("79d8bd"),false)
	return Combat.center_of(patient)
func snapshot() -> Dictionary:return {"base_id":base_id,"role":role,"route":route_index}
func apply_snapshot(state: Dictionary) -> void:base_id=int(state.get("base_id",0));role=String(state.get("role",""));route_index=int(state.get("route",0))

extends Node

static var frame := -1
static var processed := 0

var needs_source := false
var source: Thing
var rows: Array = []
var cursor := 0

func setup(bomb: Thing, hits: Array) -> void:
	source = bomb
	rows = hits
	needs_source = is_instance_valid(source)
	if needs_source: source.hold_effect_job()

func _process(_delta: float) -> void:
	if frame != Engine.get_process_frames():
		frame = Engine.get_process_frames()
		processed = 0
	if needs_source and not is_instance_valid(source):
		queue_free()
		return
	var until := Time.get_ticks_usec() + 2000
	var count := 0
	while cursor < rows.size() and count < 4 and processed < 4:
		var row: Dictionary = rows[cursor]
		cursor += 1
		count += 1
		processed += 1
		var target = row.target.get_ref()
		if is_instance_valid(target) and not (target is Thing and target.is_dead):
			Combat.apply_damage(target, row.damage, String(row.get("type", "explosive")), source)
			if is_instance_valid(target) and target.has_method("apply_knockback"):
				target.call("apply_knockback", row.push)
		if Time.get_ticks_usec() >= until: break
	if cursor >= rows.size():
		if needs_source: source.release_effect_job()
		queue_free()

extends Node

var thing: Thing
var kind := ""
var tick_left := 0.0

func setup(owner_thing: Thing, product_kind: String) -> void:
	thing = owner_thing
	kind = product_kind
func _ready() -> void: add_to_group("creature_builder_products")
func _physics_process(delta: float) -> void:
	if kind != "web" or not thing.can_act() or not thing.has_simulation_authority(): return
	tick_left -= delta
	if tick_left > 0: return
	tick_left = .3
	for target in Combat.in_radius(thing, thing.center(), 1.8):
		if target == thing or not (target is Thing or target is Player) or not Combat.affects(thing, target): continue
		if target is Thing and (target.is_dead or target.is_captured or target.is_held): continue
		if JujutsuRules.field(target, "infinity") != null: continue
		var web_box := AABB(Vector3(-1.4, -.3, -.85), Vector3(2.8, 2.3, 1.7))
		var target_box: AABB = target.global_transform * target.bounds if target is Thing else AABB(target.global_position - Vector3(.4, 0, .4), Vector3(.8, 1.8, .8))
		if web_box.intersects(thing.global_transform.affine_inverse() * target_box): Status.apply(target, "webbed", thing)

extends Node

var thing: Thing
var advanced = false
var energy = 20.0
var converted = 0
var visual: Node3D
var visual_left = 0.0
