	if raid.phase in ["spawning","fighting","interval"] or raid.cooldown>0:return {"blocked":true,"warnings":[raid.describe()]}
	if not player.try_spend(200):return {"blocked":true,"warnings":["Iniciar cinco ondas custa 200 de matéria."]}
