var rival := JujutsuRules.rival_target(source)
if rival != null: return target == rival
if target.get("team") != null and load("res://scripts/things/coop_encounter.gd").allied(source.team,int(target.get("team"))): return false
var orders = load("res://scripts/things/animal_orders.gd").of(source)
if orders != null and orders.active() and not orders.allows(target): return false
if orders != null and orders.mode == "aggressive": return InnovationRules.allows_target(source, target)
if not InnovationRules.target_diet(source).is_empty():
	return InnovationRules.allows_target(source, target)

var hits := source.get_world_3d().direct_space_state.intersect_shape(query, 128)
var seen := {}
for hit: Dictionary in hits:
	var node := hit["collider"] as Node3D
	if node != null and not seen.has(node):
		seen[node] = true

# Match native blast coverage, including newly spawned bodies before physics sync.
if Forge.world != null:
	for candidate in Forge.world.get_node("Things").get_children():
		var target := candidate as Thing
		if target == null or target == source or target.is_dead or target.is_captured or seen.has(target): continue
