		if at.distance_to(at.clamp(box.position, box.end)) <= radius: found.append(target)

	var push: = (target_center - at).normalized() + Gravity.up_at(target_center, source.up() if is_instance_valid(source) else Gravity.up_at(at)) * 0.3
	hits.append({"target": weakref(target), "damage": damage * falloff, "push": push.normalized() * knockback * falloff})
# Physics queries have a result cap; include every creation touched by a crowded blast.
if Forge.world != null:
	for candidate in Forge.world.get_node("Things").get_children():
		var target := candidate as Thing
		if target == null or target == source or target.is_dead or seen.has(target): continue
		var box: AABB = target.global_transform * target.bounds
		if at.distance_to(at.clamp(box.position, box.end)) > radius: continue
		var center := target.center()
		var falloff := lerpf(1.0, min_falloff, clampf(center.distance_to(at) / radius, 0.0, 1.0))
		hits.append({"target": weakref(target), "damage": damage * falloff, "push": Vector3.ZERO})
for row: Dictionary in hits: row["type"] = damage_type
if hits.size() > 12:
	var work = load("res://scripts/things/blast_work.gd").new()
	work.setup(source, hits)
	origin.get_tree().root.add_child(work)
else:
	for row: Dictionary in hits:
		var target = row.target.get_ref()
		if not is_instance_valid(target): continue
		apply_damage(target, row.damage, damage_type, source)
		if is_instance_valid(target) and target.has_method("apply_knockback"): target.call("apply_knockback", row.push)

static func nearest_target(source: Thing, from: Vector3, tree: SceneTree) -> Node3D:
	var rival := JujutsuRules.rival_target(source)
	if rival != null: return rival
	var orders = load("res://scripts/things/animal_orders.gd").of(source)
	if orders != null and orders.active(): return orders.combat_target()
	var diet := InnovationRules.target_diet(source)
	if diet.is_empty():
		var kaiju := nearest_enemy_kaiju(source, from, tree)
		return kaiju if kaiju != null else nearest_enemy(from, source.team, tree)
	if diet.begins_with("player:"):
		var chosen = Forge.world.get_player(int(diet.trim_prefix("player:"))) if Forge.world != null else null
		return chosen if is_instance_valid(chosen) and chosen.is_alive() and InnovationRules.allows_target(source, chosen) else null
	if Forge.world == null: return null
	var best: Thing
	var distance := INF
	for candidate in Forge.world.get_node("Things").get_children():
		var other := candidate as Thing
		if other == null or other == source or other.is_dead or other.is_held or not InnovationRules.matches_diet(other, diet): continue
		var current := center_of(other).distance_squared_to(from)
		if current < distance:
			best = other
			distance = current
	return best


static func nearest_enemy_kaiju(source: Thing, from: Vector3, tree: SceneTree) -> Thing:
	# Native kaijus seek rival titans; inherited powers do not change a creature's priorities.
	if tree == null or not is_instance_valid(source) or not source._def.has("kaiju"): return null
	var best: Thing
	var best_dist := INF
	var reach := maxf(120.0, float(source._def.kaiju.get("range", 0))) * source.scale_factor
	var detect := Lexicon.balf("abilities.cloak.detect_m")
	if Forge.world == null: return null
	for node in Forge.world.get_node("Things").get_children():
		var other := node as Thing
		if other == null or other == source or not other._def.has("kaiju"): continue
		if not other.is_active or other.is_dead or other.is_building or other.is_captured or other.is_held: continue
		if load("res://scripts/things/coop_encounter.gd").allied(source.team,other.team): continue
		if not affects(source, other): continue
		var box: AABB = other.global_transform * other.bounds
		var dist := from.distance_squared_to(from.clamp(box.position, box.end))
		if dist > reach * reach: continue
		if dist > detect * detect and other.has_method("is_cloaked") and other.call("is_cloaked"): continue
		if dist < best_dist:
			best = other
			best_dist = dist
	return best

