	if allowing or not thing.node_data.get("mods",{}).get("enemy_proximity",false):return false
	armed=true;return true
func _physics_process(delta: float) -> void:
	if not thing.has_simulation_authority() or not thing.is_active or thing.is_dead or thing.is_captured or thing.is_held:return
	age+=delta;tick-=delta
	if age>=20.0:thing.explosion_spent=true;thing.remove();return
	if not armed or tick>0:return
	tick=.2
	for target in Combat.in_radius(thing,thing.center(),3.0):
		if target==thing.owner_player or (target is Thing and target.category not in ["creature","vehicle"]) or not Combat.affects(thing,target):continue
		var ray:=PhysicsRayQueryParameters3D.create(thing.center(),Combat.center_of(target),PhysicsLayers.WORLD,[thing.get_rid()])
		if not thing.get_world_3d().direct_space_state.intersect_ray(ray).is_empty():continue
		allowing=true
		var action=thing.get_node_or_null("Do_explode")
		if action!=null:action.run(ActionContext.make(thing.center(),thing.travel_direction()))
		else:thing.explosion_spent=true;Combat.explode(thing,thing.center(),thing.explosion_radius,thing.explosion_damage);thing.die()
