static func landed(source: Thing, target: Object) -> void:
	var cursor:=source;var seen:Dictionary={};var species:=""
	for step in 8:
		if not is_instance_valid(cursor) or seen.has(cursor.get_instance_id()):break
		seen[cursor.get_instance_id()]=true
		species=String(cursor.node_data.get("mods",{}).get("conditional_species",""))
		if not species.is_empty():break
		cursor=cursor.mount_host if is_instance_valid(cursor.mount_host) else cursor.spawner as Thing
	if species.is_empty() or not target is Thing or target.category!="creature" or target.is_dead or target.team==source.team:return
	var key:="conditional_hit_"+str(source.owner_id)
	if int(target.get_meta(key,0))>Time.get_ticks_msec():return
	target.set_meta(key,Time.get_ticks_msec()+3500)
	if target.thing_id==species:Status.apply(target,"frozen",source,.6)
	else:
		var direction:=source.travel_direction()
		if direction.length_squared()<.01:direction=(target.center()-source.center()).normalized()
		target.nudge(direction*3.0)
