extends Node

var phase = "idle"
var accepted: Array[int] = []
var members: Array[int] = []
var boss_ref: WeakRef
var elapsed = 0.0
var cooldown = 0.0
var network_tick = 0.0
var message = ""
var paid = false
var caption: Label

static func of(world: Node) -> Node:
	return world.get_node_or_null("CoopEncounter") if is_instance_valid(world) else null
static func ensure(world: Node) -> Node:
	var found = of(world)
	if found != null: return found
	var encounter = load("res://scripts/things/coop_encounter.gd").new()
	encounter.name = "CoopEncounter"
	world.add_child(encounter)
	return encounter
static func allied(a: int, b: int) -> bool:
	var encounter = of(Forge.world)
	return encounter != null and encounter.phase == "battle" and encounter.members.has(a) and encounter.members.has(b)
static func request(player: Player, action: String) -> Dictionary:
	var encounter = ensure(Forge.world)
	if action == "status": return {"warnings":[encounter.message if not encounter.message.is_empty() else "Diga desafio cooperativo para convidar. Cada jogador deve aceitar desafio. Custo total: 300 de matéria do iniciador."]}
	if action == "cancel":
		if encounter.phase == "waiting" and encounter.accepted.has(player.player_id): encounter.finish("cancelled","Convite cancelado.")
		return {"warnings":[encounter.message]}
	if encounter.phase == "battle" or encounter.cooldown > 0: return {"blocked":true,"warnings":["Desafio em andamento ou recarregando por %.0f s." % encounter.cooldown]}
	if action == "invite":
		if encounter.phase != "waiting":
			encounter.accepted.clear()
			encounter.phase = "waiting"
			encounter.elapsed = 0.0
			encounter.message = "Desafio: T-Rex alado adaptativo. Cada jogador diga aceitar desafio; o iniciador paga 300 de matéria."
			encounter.accepted.append(player.player_id)
	elif encounter.phase == "waiting" and not encounter.accepted.has(player.player_id): encounter.accepted.append(player.player_id)
	if encounter.phase != "waiting": return {"blocked":true,"warnings":["Primeiro diga desafio cooperativo."]}
	var players = encounter.connected_players()
	var ready = not players.is_empty()
	for fighter in players:
		if not encounter.accepted.has(fighter.player_id) or not fighter.is_alive(): ready = false
	if ready:
		var reply: Dictionary = encounter.begin(players)
		if reply.get("blocked",false): return reply
	return {"warnings":[encounter.message]}
func connected_players() -> Array:
	var players = []
	for player in get_parent().get_players():
		if Session.is_online():
			if Session.peer_for_player(player.player_id) <= 0: continue
		elif player != get_parent().player: continue
		players.append(player)
	return players
func begin(players: Array) -> Dictionary:
	var initiator = get_parent().get_player(accepted[0])
	if not is_instance_valid(initiator) or initiator.matter_spendable() < 300.0: return {"blocked":true,"warnings":["O iniciador precisa de 300 de matéria para o chefe."]}
	var forge = get_node("/root/Forge")
	var source = initiator.hands.current_item()
	var temporary = false
	if source == null:
		source = Assembler.build(Recipe.new_node("pistol"),"head",Lexicon.data)
		get_parent().add_thing(source)
		source.set_owner_info(initiator.player_id,initiator.team,initiator,null)
		temporary = true
	var ray: Dictionary = initiator.look_ray()
	var at: Vector3 = forge.ground_point(initiator.global_position+Gravity.flat(ray.direction,initiator.up_direction).normalized()*12.0)
	var boss = forge.spawn_child(Recipe.new_node("coop_chimera"),"spawned",at+Vector3.UP*2.0,Vector3.FORWARD,source,0.0)
	if temporary: source.remove()
	if boss == null: return {"blocked":true,"warnings":["Aguarde espaço para invocar o chefe."]}
	if not initiator.try_spend(300.0): boss.remove(); return {"blocked":true,"warnings":["Matéria insuficiente."]}
	members.clear()
	for player in players: members.append(player.player_id)
	forge.transfer_neutral(boss,99)
	boss.matter = 0.0
	boss.matter_returns = false
	boss.max_hp = 600.0+350.0*(players.size()-1)
	boss.hp = boss.max_hp
	boss.get_node("CoopBoss").damage_scale = 1.0+.15*(players.size()-1)
	boss_ref = weakref(boss)
	phase = "battle"
	paid = false
	elapsed = 0.0
	message = "COOP · derrotem a Quimera Adaptativa · aliados protegidos · 180 s"
	return {"coop_started":true}
func finish(result: String, text: String) -> void:
	if phase == "battle" and result == "victory" and not paid:
		paid = true
		for id in members:
			var player = get_parent().get_player(id)
			if is_instance_valid(player): player.store_or_spill(120.0)
	phase = result
	message = text
	cooldown = 60.0 if result != "cancelled" else 0.0
	var boss = boss_ref.get_ref() if boss_ref != null else null
	if is_instance_valid(boss) and not boss.is_dead: boss.remove()
	boss_ref = null
	if Session.is_online() and get_parent().has_method("_resolve_elimination"): get_parent().call_deferred("_resolve_elimination",get_parent().get("_epoch"))
	send_state()
func _physics_process(delta: float) -> void:
	if not Session.has_authority(): return
	cooldown = maxf(0.0,cooldown-delta)
	elapsed += delta
	if phase == "waiting" and elapsed > 30.0: finish("cancelled","O convite expirou.")
	if phase == "battle":
		var players = connected_players()
		var connected = []
		var alive = 0
		for player in players:
			connected.append(player.player_id)
			if members.has(player.player_id) and player.is_alive(): alive += 1
		for id in members:
			if not connected.has(id): finish("cancelled","Desafio cancelado: jogador desconectado."); return
		var boss = boss_ref.get_ref() if boss_ref != null else null
		if alive == 0: finish("defeat","Derrota · ninguém sobreviveu ao chefe.")
		elif not is_instance_valid(boss) or boss.is_dead: finish("victory","Vitória cooperativa · +120 de matéria por jogador!")
		elif elapsed >= 180.0: finish("defeat","Tempo esgotado no desafio.")
	network_tick -= delta
	if network_tick <= 0.0: network_tick = .5; send_state()
func snapshot() -> Dictionary: return {"phase":phase,"members":members,"message":message,"cooldown":cooldown}
func apply_snapshot(data: Dictionary) -> void:
	phase = String(data.get("phase","idle"))
	members.assign(data.get("members",[]))
	message = String(data.get("message",""))
	cooldown = float(data.get("cooldown",0.0))
func send_state() -> void:
	if Session.is_online() and Session.has_authority(): Session.creations.notify_fx("coop_state",[snapshot()])
func _process(_delta: float) -> void:
	if caption == null:
		var canvas = CanvasLayer.new()
		add_child(canvas)
		caption = Label.new()
		caption.position = Vector2(20,105)
		caption.add_theme_color_override("font_color",Color("eed3ab"))
		canvas.add_child(caption)
	caption.text = message
	caption.visible = phase in ["waiting","battle"] or cooldown > 50.0

extends Node

var thing: Thing
var head_time = 0.0
var old_head = ""
var team_time = 0.0
var old_owner = 0
var old_team = 0
var old_source: WeakRef
var old_order = {}
var old_target: WeakRef
var old_house: WeakRef
var immunity = 0.0

func setup(owner_thing: Thing) -> void: thing = owner_thing
func available() -> bool:
	return not thing.is_dead and not thing.is_captured and not thing.is_held and not thing.is_building and thing.is_active and thing.get_node_or_null("CoopBoss") == null
func age(source: Thing) -> bool:
	if not available() or not _vulnerable(source): return false
	var state = Status.of(thing)
	if state != null and (state.remaining.has("aged") or state.remaining.has("age_immunity")): return false
	Status.apply(thing,"aged",source)
	Status.apply(thing,"age_immunity",source)
	return true
func _vulnerable(source: Thing) -> bool:
	return Combat.affects(source,thing) and JujutsuRules.field(thing,"infinity") == null and JujutsuRules.field(thing,"adaptation") == null
static func swap(a: Node, b: Node, source: Thing) -> bool:
	if a == null or b == null or a == b or not a.available() or not b.available() or a.head_time > 0 or b.head_time > 0 or a.immunity > 0 or b.immunity > 0 or not a._vulnerable(source) or not b._vulnerable(source): return false
	a.old_head = String(a.thing.node_data.get("mods",{}).get("anatomy",{}).get("head",""))
	b.old_head = String(b.thing.node_data.get("mods",{}).get("anatomy",{}).get("head",""))
	var head_a: String = a.old_head if not a.old_head.is_empty() else a.thing.thing_id
	var head_b: String = b.old_head if not b.old_head.is_empty() else b.thing.thing_id
	a._head(head_b)
	b._head(head_a)
	a.head_time = 8.0
	b.head_time = 8.0
	a.immunity = 16.0
	b.immunity = 16.0
	return true
func _head(id: String) -> void:
	var mods: Dictionary = thing.node_data.get_or_add("mods",{})
	var anatomy: Dictionary = mods.get_or_add("anatomy",{})
	if id.is_empty(): anatomy.erase("head")
	else: anatomy.head = id
	# Only appearance changes: identity, skills, HP, equipment and contents remain intact.
	thing.rebuild_equipment_model()
	var motion = thing.get_node_or_null("VoxelCreatureMotion")
	if motion != null:
		motion.parts.clear()
		motion.setup(thing,bool(thing._def.get("aerial",false)) or thing.node_data.get("mods",{}).get("anatomy",{}).has("wings"))
func charm(source: Thing) -> bool:
	if not available() or team_time > 0.0 or immunity > 0.0 or not _vulnerable(source) or not is_instance_valid(source.owner_player): return false
	old_owner = thing.owner_id
	old_team = thing.team
	old_source = weakref(thing.spawner) if is_instance_valid(thing.spawner) else null
	var orders = thing.get_node_or_null("AnimalOrders")
	old_order = orders.snapshot() if orders != null else {}
	old_target = orders.target_ref if orders != null else null
	old_house = orders.house_ref if orders != null else null
	if not Forge.transfer_owner(thing,source.owner_player,source): return false
	if orders != null: orders.set_order("retaliate",thing.global_position)
	team_time = 6.0
	immunity = 18.0
	return true
func restore(clear_age: bool = true) -> void:
	if head_time > 0.0:
		head_time = 0.0
		_head(old_head)
	if team_time > 0.0:
		team_time = 0.0
		var owner = Forge.world.get_player(old_owner) if Forge.world != null else null
		var source = old_source.get_ref() if old_source != null else null
		if is_instance_valid(owner):
			if not Forge.transfer_owner(thing,owner,source as Thing): Forge.transfer_neutral(thing,old_team)
		else: thing.set_owner_info(old_owner,old_team,null,source)
		thing.team = old_team
		var orders = thing.get_node_or_null("AnimalOrders")
		if orders != null:
			orders.apply_snapshot(old_order)
			orders.target_ref = old_target
			orders.house_ref = old_house
			if orders.mode == "attack" and (old_target == null or not is_instance_valid(old_target.get_ref())): orders.set_order("stay",thing.global_position)
	if clear_age: Status.remove_effect(thing,"aged")
func _physics_process(delta: float) -> void:
	if not thing.has_simulation_authority(): return
	immunity = maxf(0.0,immunity-delta)
	if thing.is_dead: return
	if head_time > 0.0:
		head_time -= delta
		if head_time <= 0.0: head_time = .001; restore_head()
	if team_time > 0.0:
		team_time -= delta
		if team_time <= 0.0: team_time = .001; restore_team()
func restore_head() -> void:
	head_time = 0.0
	_head(old_head)
func restore_team() -> void:
	var keep = head_time
	head_time = 0.0
	restore(false)
	head_time = keep
func snapshot() -> Dictionary: return {"head_time":head_time,"team_time":team_time,"immunity":immunity}
func apply_snapshot(data: Dictionary) -> void:
	head_time = float(data.get("head_time",0.0))
	team_time = float(data.get("team_time",0.0))
	immunity = float(data.get("immunity",0.0))

extends RefCounted
static func cast_power(actor:Thing,key:String,ctx:ActionContext) -> void:
	var cursed=actor.get_node_or_null("Jujutsu")
	if cursed==null:return
	var saved:Dictionary=cursed.powers
	var definition:Dictionary=actor._def
	actor._def=definition.duplicate();actor._def.erase("jj_character");cursed.powers={key:true}
	if key=="reverse":cursed._heal()
	else:cursed.cast(ctx)
	cursed.powers=saved;actor._def=definition
static func request(player: Player, settings: Dictionary) -> Dictionary:
	if not player.can_act():return {"blocked":true}
	var action:=String(settings.get("action",""))
	if action in ["raid_start","raid_stop","raid_status"]:return load("res://scripts/things/castle_raid.gd").request(player,action)
	if action=="duo":return load("res://scripts/things/duo_combo.gd").request(player,String(settings.actor),String(settings.other))
	if action=="mount":return load("res://scripts/things/control/control_mount.gd").request(player,String(settings.actor))
	if action=="dismount":player.stop_piloting();return {"warnings":["Você desceu da montaria."]}
	if action=="mount_cycle":
		if player.piloting!=null and player.piloting.control.has_method("cycle_skill"):player.piloting.control.cycle_skill();return {"warnings":[player.piloting.control.skill_label()]}
		return {"blocked":true,"warnings":["Monte numa criatura primeiro."]}
	if action in ["echo_copy","echo_use"]:
		var item=player.hands.current_item();var echo=item.get_node_or_null("SkillEcho") if item!=null else null
		if echo==null:return {"blocked":true,"warnings":["Equipe o mimetizador de habilidades."]}
		return echo.copy_skill() if action=="echo_copy" else echo.use(ActionContext.make(player.head.global_position,player.look_ray().direction))
	var actor=load("res://scripts/things/creature_tactics.gd").choose(player,String(settings.get("actor","")))
	if actor==null:return {"blocked":true,"warnings":["Invoque e mire numa criatura sua próxima."]}
	var craft=actor.get_node_or_null("CreatureCraft")
	if craft==null:return {"blocked":true}
	if action=="feat_status":return {"warnings":[craft.describe()]}
	if action=="guardian":return craft.evolve(player)
	if action=="colony":return craft.specialize(player,String(settings.get("colony","")))
	return {"blocked":true}

