extends Node

var thing: Thing
var trust = 35.0
var fear = 0.0
var care_cooldown = 0.0
var tick = 0.0
var previous_hp = 0.0
var mood = "tranquilo"
var label: Label3D

func setup(owner_thing: Thing) -> void:
	thing = owner_thing
	previous_hp = thing.hp
func _ready() -> void: add_to_group("creature_bonds")
func _physics_process(delta: float) -> void:
	if not thing.has_simulation_authority() or not thing.is_active or thing.is_held or thing.is_building: return
	care_cooldown = maxf(0.0,care_cooldown-delta)
	tick -= delta
	if tick > 0: return
	tick = .5
	var lost = maxf(0.0,previous_hp-thing.hp)
	previous_hp = thing.hp
	fear = clampf(fear+lost/maxf(thing.max_hp,1.0)*160.0-1.0,0.0,100.0)
	mood = "assustado" if fear >= 60.0 else "confiante" if trust >= 60.0 else "tranquilo"
func care(player: Player) -> Dictionary:
	if care_cooldown > 0.0: return {"blocked":true,"warnings":["Aguarde %.0f s antes de cuidar novamente." % care_cooldown]}
	if not player.try_spend(8.0): return {"blocked":true,"warnings":["Cuidar custa 8 de matéria."]}
	care_cooldown = 4.0
	trust = minf(100.0,trust+10.0)
	fear = maxf(0.0,fear-25.0)
	thing.hp = minf(thing.max_hp,thing.hp+5.0)
	previous_hp = thing.hp
	ExpansionFx.burst(Forge.fx_root(thing),thing.center(),.7,Color("e5bdcf"),"care")
	return {"creature_cared":thing.network_id,"warnings":[description()]}
func description() -> String:
	return "%s · %s · vínculo %.0f/100 · medo %.0f/100" % [Lexicon.data.thing_name(thing.thing_id),mood,trust,fear]
func refuses_danger() -> bool: return trust < 50.0 and fear >= 70.0 and thing.hp < thing.max_hp*.15
static func select(player: Player, species: String = "") -> Node:
	var best = INF
	var result: Node
	var ray = player.look_ray()
	for bond in player.get_tree().get_nodes_in_group("creature_bonds"):
		var animal: Thing = bond.thing
		if animal.owner_id != player.player_id or animal.team != player.team or animal.is_dead or animal.is_captured or animal.is_building or animal.is_held: continue
		if not species.is_empty() and animal.thing_id != species: continue
		var offset: Vector3 = animal.center()-ray.origin
		if offset.length() > 15.0 or offset.normalized().dot(ray.direction) < .5: continue
		var query = PhysicsRayQueryParameters3D.create(ray.origin,animal.center(),PhysicsLayers.WORLD)
		if not player.get_world_3d().direct_space_state.intersect_ray(query).is_empty(): continue
		var rank: float = offset.length()+(1.0-offset.normalized().dot(ray.direction))*15.0
		if rank < best: best = rank; result = bond
	return result
static func request(player: Player, settings: Dictionary) -> Dictionary:
	if not player.can_act(): return {"blocked":true,"warnings":["Você não pode cuidar agora."]}
	var bond = select(player,String(settings.get("species","")))
	if bond == null: return {"blocked":true,"warnings":["Mire numa criatura sua a até 15 m."]}
	if settings.bond == "care": return bond.care(player)
	if settings.bond == "pack":
		if bond.trust < 60.0: return {"blocked":true,"warnings":["Ganhe vínculo 60 para proteger companheiros. Diga: cuidar da criatura."]}
		bond.thing.get_node("AnimalOrders").set_order("guard_pack",bond.thing.global_position)
		return {"warnings":["Protegendo companheiros; dieta e outras ordens continuam valendo."]}
	return {"warnings":[bond.description()]}
func snapshot() -> Dictionary: return {"trust":trust,"fear":fear,"cooldown":care_cooldown,"mood":mood}
func apply_snapshot(data: Dictionary) -> void:
	trust = float(data.get("trust",35.0))
	fear = float(data.get("fear",0.0))
	care_cooldown = float(data.get("cooldown",0.0))
	mood = String(data.get("mood","tranquilo"))

extends Node

var thing: Thing
var kind := ""
var running := false
var progress := 0.0
var completed := 0
var dug_total := 0
var state := "parado"
var work_point := Vector3.ZERO
var heading := Vector3.FORWARD
var cooldown_until := 0
var tick_left := 0.0
var volume_ref: WeakRef
var cells := []
var cell_cursor := 0
var caption: Label3D
static var work_frame := -1
static var work_count := 0
static var team_digs := {}
static var dig_world := 0

func setup(owner_thing: Thing, builder_kind: String) -> void:
	thing = owner_thing
	kind = builder_kind
	tick_left = float(thing.get_instance_id() % 13) * .017

func begin(at: Vector3, direction: Vector3) -> Dictionary:
	if running: return {"blocked": true, "warnings": ["Esse animal já está trabalhando."]}
	if Time.get_ticks_msec() < cooldown_until: return {"blocked": true, "warnings": ["Aguarde a recarga de construção desse animal."]}
	if not _within_cap(): return {"blocked": true, "warnings": ["Limite de construções desse animal ou da equipe atingido."]}
	var up := thing.up()
	var query := PhysicsRayQueryParameters3D.create(at + up * 3.0, at - up * 6.0, PhysicsLayers.WORLD)
	var hit := thing.get_world_3d().direct_space_state.intersect_ray(query)
	if hit.is_empty(): return {"blocked": true, "warnings": ["Escolha um chão próximo para construir."]}
	work_point = hit.position
	heading = Gravity.flat(direction, up).normalized()
	if heading.length_squared() < .01: heading = Gravity.flat(-thing.global_basis.z, up).normalized()
	if kind == "tunnel":
		var volume := hit.collider as BlockVolume
		if volume == null or not volume.is_in_group("terrain"): return {"blocked": true, "warnings": ["Formigas escavam terra do terreno; não casas nem blocos protegidos."]}
		volume_ref = weakref(volume)
		cells = _dig_plan(volume, work_point, heading, up)
		if cells.is_empty(): return {"blocked": true, "warnings": ["Não há terra escavável aqui, ou o limite de escavação foi atingido."]}
	else:
		if not _site_clear(): return {"blocked": true, "warnings": ["Esse local está ocupado. Escolha um espaço livre."]}
	running = true
	progress = 0.0
	cell_cursor = 0
	state = "indo ao local"
	return {"builder_started": kind}

func cancel() -> void:
	running = false
	progress = 0.0
	state = "parado"
	cells.clear()
	volume_ref = null

func requirements() -> String:
	if kind == "tunnel": return "0,3 de matéria por bloco de terra, até 96 por túnel"
	return "32 de matéria · 4 s de trabalho" if kind == "dam" else "16 de matéria · 2,5 s de trabalho"

func _process(_delta: float) -> void:
	if not running or thing.is_dead or thing.is_captured:
		if caption != null: caption.hide()
		return
	if caption == null:
		caption = Label3D.new()
		caption.name = "BuilderProgress"
		caption.font_size = 22
		caption.pixel_size = .004
		caption.outline_size = 5
		caption.billboard = BaseMaterial3D.BILLBOARD_ENABLED
		thing.add_child(caption)
	caption.show()
	caption.position = thing.bounds.get_center() + Vector3.UP * (thing.bounds.size.y * .5 + .35)
	caption.text = "%s · %d%%" % [state.capitalize(), roundi(progress * 100)]

func _within_cap() -> bool:
	if kind == "tunnel": return dug_total < 192 and _team_dug() < int(Lexicon.balf("creature_builders.dig_team_cell_cap"))
	var owned := 0
	var team_count := 0
	for item in get_tree().get_nodes_in_group("creature_builder_products"):
		if item.thing.is_dead or item.kind != kind: continue
		if item.thing.spawner == thing: owned += 1
		if item.thing.team == thing.team: team_count += 1
	return owned < (2 if kind == "dam" else 3) and team_count < (6 if kind == "dam" else 8)

func _team_dug() -> int:
	var id := Forge.world.get_instance_id()
	if dig_world != id:
		dig_world = id
		team_digs.clear()
	return int(team_digs.get(thing.team, 0))

func _dig_plan(volume: BlockVolume, at: Vector3, forward: Vector3, up: Vector3) -> Array:
	var plan := []
	var seen := {}
	var limit := mini(int(Lexicon.balf("creature_builders.dig_cells_per_job")), mini(192 - dug_total, int(Lexicon.balf("creature_builders.dig_team_cell_cap")) - _team_dug()))
	for step in 16:
		var center := volume.cell_of(volume.to_local(at + forward * step * .25 - up * (.25 + minf(step * .04, .45))))
		for x in range(-2, 3):
			for y in range(-2, 3):
				for z in range(-2, 3):
					var cell := center + Vector3i(x, y, z)
					if Vector3(x, y, z).length() > 2.1 or not volume.inside(cell): continue
					var index := volume.index_of(cell)
					if seen.has(index) or not _diggable(volume, index): continue
					seen[index] = true
					plan.append(index)
					if plan.size() >= limit: return plan
	return plan

func _diggable(volume: BlockVolume, index: int) -> bool:
	if index < 0 or index >= volume.blocks.size(): return false
	var type := int(volume.blocks[index])
	return type != BlockVolume.AIR and volume.type_material(type) in ["soil", "sand"] and (volume._pal_flags[type] & BlockVolume.FLAG_FOREVER) == 0

func _site_clear() -> bool:
	var shape := BoxShape3D.new()
	shape.size = Vector3(3.0, 1.3, .36) if kind == "dam" else Vector3(2.2, 1.2, .10)
	var frame := Gravity.frame_for(thing.up())
	var query := PhysicsShapeQueryParameters3D.new()
	query.shape = shape
	query.transform = Transform3D(frame, work_point + thing.up() * .78)
	query.collision_mask = PhysicsLayers.WORLD | PhysicsLayers.THINGS | PhysicsLayers.TRAPS
	query.exclude = [thing.get_rid()]
	if thing.owner_player is PhysicsBody3D: query.exclude.append(thing.owner_player.get_rid())
	return thing.get_world_3d().direct_space_state.intersect_shape(query, 1).is_empty()

func _physics_process(delta: float) -> void:
	if not running or not thing.has_simulation_authority() or not thing.can_act() or thing.is_captured: return
	var orders := thing.get_node_or_null("AnimalOrders")
	var personal := thing.get_node_or_null("PersonalPowers")
	if not (personal != null and personal.equipped()) and (orders == null or orders.mode != "build"): cancel(); return
	if not is_instance_valid(thing.owner_player) or not thing.owner_player.is_alive(): cancel(); return
	tick_left -= delta
	if tick_left > 0: return
	tick_left = Lexicon.balf("creature_builders.work_tick_s")
	if thing.global_position.distance_to(work_point) > 3.5:
		state = "indo ao local"
		return
	var frame := Engine.get_process_frames()
	if frame != work_frame: work_frame = frame; work_count = 0
	if work_count >= 4: return
	work_count += 1
	state = "construindo"
	if kind == "tunnel":
		_dig_step()
		return
	var seconds := Lexicon.balf("creature_builders.dam_seconds" if kind == "dam" else "creature_builders.web_seconds")
	progress = minf(1.0, progress + tick_left / seconds)
	if progress < 1.0: return
	if not _within_cap() or not _site_clear(): state = "local ocupado ou limite atingido"; return
	var id := "beaver_dam" if kind == "dam" else "spider_web"
	var cost := Lexicon.data.thing_statf(id, "cost")
	var player := thing.owner_player as Player
	if not player.try_spend(cost): state = "sem matéria"; return
	var product := Forge.spawn_child(Recipe.new_node(id), "spawned", work_point + thing.up() * .03, heading, thing, 0.0, Vector3.ZERO, true)
	if product == null:
		player.add_matter(cost)
		state = "aguardando criação"
		return
	product.matter = cost
	_finish()

func _dig_step() -> void:
	var volume = volume_ref.get_ref() if volume_ref != null else null
	if not is_instance_valid(volume): cancel(); return
	var price := Lexicon.balf("creature_builders.dig_cell_cost")
	for step in 4:
		if cell_cursor >= cells.size() or dug_total >= 192 or _team_dug() >= int(Lexicon.balf("creature_builders.dig_team_cell_cap")): _finish(); return
		var index: int = cells[cell_cursor]
		if not _diggable(volume, index): cell_cursor += 1; continue
		if not thing.owner_player.try_spend(price): state = "sem matéria"; return
		volume.remove_cells([index], false)
		dug_total += 1
		team_digs[thing.team] = _team_dug() + 1
		cell_cursor += 1
	progress = float(cell_cursor) / maxf(1.0, cells.size())
	if cell_cursor >= cells.size(): _finish()

func _finish() -> void:
	running = false
	completed += 1
	progress = 1.0
	state = "concluído"
	cooldown_until = Time.get_ticks_msec() + int(Lexicon.balf("creature_builders.cooldown_s") * 1000)
	var orders := thing.get_node_or_null("AnimalOrders")
	if orders != null:
		orders.mode = "stay"
		orders.point = thing.global_position
		orders.goal = thing.global_position
	ExpansionFx.burst(Forge.fx_root(thing), thing.center(), .6, Color("c0be8b"), "builder_done")

func snapshot() -> Dictionary:
	return {"kind": kind, "running": running, "progress": progress, "completed": completed, "dug": dug_total, "state": state}
func apply_snapshot(values: Dictionary) -> void:
	running = bool(values.get("running", false))
	progress = float(values.get("progress", 0.0))
	completed = int(values.get("completed", 0))
	dug_total = int(values.get("dug", 0))
	state = String(values.get("state", "parado"))

extends RefCounted

static var count := 0
static var last_reaction := ""

static func _carrier(source: Thing) -> Thing:
	var cursor := source
	var seen := {}
	for step in 8:
		if not is_instance_valid(cursor) or seen.has(cursor.get_instance_id()): return null
		seen[cursor.get_instance_id()] = true
		if cursor.category == "creature": return cursor
		cursor = cursor.mount_host if is_instance_valid(cursor.mount_host) else cursor.spawner as Thing
	return null

static func prepare(target: Object, source: Thing, kind: String, delivery: String, amount: float) -> Dictionary:
	if not (target is Player or target is Thing):return {}
	if target is Player and not target.is_alive():return {}
	if target is Thing and (target.category != "creature" or target.is_dead or target.is_captured or target.is_held):return {}
	var carrier := _carrier(source)
	if carrier == null or carrier.is_captured or carrier.is_dead or carrier.team == target.team or (target.player_id if target is Player else target.owner_id) == carrier.owner_id: return {}
	if not InnovationRules.allows_target(source, target): return {}
	var status := Status.of(target)
	var active: Dictionary = status.remaining if status != null else {}
	var plan := {"reaction": "", "bonus": 0.0, "seed": "", "consume": "", "lock": ""}
	if kind == "water": plan.seed = "wet"
	if delivery == "vine" and kind == "grass" and float(active.get("combo_vine_lock", 0.0)) <= 0.0: plan.seed = "entangled"
	if kind == "electric" and float(active.get("wet", 0.0)) > 0.0 and float(active.get("combo_shock_lock", 0.0)) <= 0.0:
		plan.merge({"reaction": "conductive", "consume": "wet", "lock": "combo_shock_lock", "bonus": minf(amount * Lexicon.balf("creature_combos.shock_mult"), Lexicon.balf("creature_combos.shock_bonus_cap"))}, true)
	elif kind == "fire" and float(active.get("entangled", 0.0)) > 0.0 and float(active.get("combo_fire_lock", 0.0)) <= 0.0:
		plan.merge({"reaction": "vine_fire", "consume": "entangled", "lock": "combo_fire_lock", "bonus": minf(amount * Lexicon.balf("creature_combos.fire_mult"), Lexicon.balf("creature_combos.fire_bonus_cap"))}, true)
	if plan.reaction=="" and float(active.get("blue_grasp",0))>0 and float(active.get("combo_blue_lock",0))<=0:
		var blue:Variant=target.get_meta("blue_combo_actor",null)
		if blue is WeakRef and is_instance_valid(blue.get_ref()) and blue.get_ref()!=carrier and blue.get_ref().owner_id==carrier.owner_id:
			plan.merge({"reaction":"blue_followup","consume":"blue_grasp","lock":"combo_blue_lock","bonus":minf(amount*.25,20)},true)
	return plan

static func landed(target: Node3D, source: Thing, plan: Dictionary) -> void:
	if plan.is_empty() or not is_instance_valid(target):return
	if target is Thing and target.is_captured:return
	if (target.is_alive() if target is Player else not target.is_dead) and not String(plan.seed).is_empty():
		Status.apply(target, String(plan.seed), source)
		if plan.seed == "entangled":
			Status.apply(target, "combo_vine_lock", source)
			target.velocity = Vector3.ZERO
	if String(plan.reaction).is_empty(): return
	Status.remove_effect(target, String(plan.consume))
	Status.apply(target, String(plan.lock), source)
	count += 1
	last_reaction = String(plan.reaction)
	load("res://scripts/fx/pokemon_fx.gd").play(Forge.fx_root(target), Combat.center_of(target), Combat.center_of(target), last_reaction, "Água + eletricidade" if last_reaction == "conductive" else "Azul + aliado" if last_reaction=="blue_followup" else "Cipós + fogo")

extends Node
var thing: Thing
var clock:=0.0
var hits:=0
var attack_key:=""
var last_hit:=-100.0
var last_defense:=-100.0
var protections:=0
var births:=0
var colony:=""
var defensive_until:=0.0
var defensive_point:=Vector3.ZERO
var threat_ref: WeakRef
var learned:=0
func setup(body: Thing) -> void:thing=body
func _physics_process(delta: float) -> void:
	if thing.has_simulation_authority() and thing.is_active and not thing.is_captured:clock+=delta
func incoming(source: Thing, kind: String) -> void:
	if source.team==thing.team:return
	var attacker:Node3D=source.owner_player if is_instance_valid(source.owner_player) else source
	var key:=str(attacker.get_instance_id())+":"+source.thing_id+":"+kind
	hits=hits+1 if key==attack_key and clock-last_hit<8.0 else 1
	attack_key=key;last_hit=clock;threat_ref=weakref(attacker)
	if hits<3 or clock<defensive_until:return
	learned+=1;defensive_until=clock+2.0
	var up:=thing.up();var away:=Gravity.flat(thing.center()-Combat.center_of(attacker),up).normalized()
	var side:=away.cross(up).normalized()*(1.8 if learned%2==0 else -1.8)
	defensive_point=thing.global_position+side
	for offset in [side*2.0,-side*2.0]:
		var point:=Forge.ground_point(thing.global_position+offset,up)+up*.2
		var ray:=PhysicsRayQueryParameters3D.create(Combat.center_of(attacker),point+up,PhysicsLayers.WORLD,[thing.get_rid()])
		if not thing.get_world_3d().direct_space_state.intersect_ray(ray).is_empty():defensive_point=point;break
func navigate(destination: Vector3) -> Vector3:
	if clock>=defensive_until or not thing.can_act() or thing.get_meta("ridden",false):return destination
	var orders=thing.get_node("AnimalOrders")
	if orders.mode in ["stay","build","base_repair","base_retreat"]:return destination
	return defensive_point
static func record_damage(source: Thing, target: Object, damage: float, kind: String) -> void:
	if damage<=0 or not is_instance_valid(source):return
	if target is Thing:
		var learner=target.get_node_or_null("CreatureCraft")
		if learner!=null:learner.incoming(source,kind)
	var actor=load("res://scripts/things/creature_combos.gd")._carrier(source)
	if actor==null or not is_instance_valid(actor.owner_player) or actor.team==target.get("team"):return
	var craft=actor.get_node_or_null("CreatureCraft");var owner=actor.owner_player
	if craft==null or actor.global_position.distance_to(owner.global_position)>12:return
	var recent:Dictionary=owner.get_meta("animal_last_attacker",{})
	if recent.has("source") and recent.source.get_ref()==target and Time.get_ticks_msec()-int(recent.get("at",0))<6000 and craft.clock-craft.last_defense>=8.0:
		craft.protections+=1;craft.last_defense=craft.clock
static func record_birth(source: Thing, child: Thing) -> void:
	if child.thing_id!="ant":return
	var cursor:=source
	for step in 4:
		if not is_instance_valid(cursor):return
		if cursor.thing_id=="queen_ant":
			var craft=cursor.get_node_or_null("CreatureCraft")
			if craft!=null:craft.births+=1
			return
		cursor=cursor.spawner as Thing
func describe() -> String:return "%s · proteções %d/5 · formigas produzidas %d/6 · desvios aprendidos %d · colônia %s"%[Lexicon.data.thing_name(thing.thing_id),protections,births,learned,colony if not colony.is_empty() else "comum"]
func evolve(player: Player) -> Dictionary:
	if protections<5 or thing.node_data.get("mods",{}).get("guardian",false):return {"blocked":true,"warnings":[describe()]}
	if not player.try_spend(80):return {"blocked":true,"warnings":["Evolução de guardião custa 80 de matéria e cinco proteções reais."]}
	var ratio:=thing.hp/maxf(thing.max_hp,.01)
	thing.node_data.get_or_add("mods",{}).merge({"guardian":true,"armored":true},true)
	thing.rebuild_equipment_model();thing.hp=thing.max_hp*ratio;thing.matter+=80
	return {"warnings":["Evolução de guardião: mais vida, armadura e força. Equipamento e proporção de vida preservados."]}
func specialize(player: Player, kind: String) -> Dictionary:
	if thing.thing_id!="queen_ant" or births<6:return {"blocked":true,"warnings":["A rainha precisa produzir seis formigas antes de especializar a colônia."]}
	if kind not in ["soldados","operarias"] or colony==kind:return {"blocked":true}
	if not player.try_spend(80):return {"blocked":true,"warnings":["Especializar a colônia custa 80 de matéria."]}
	colony=kind;return {"warnings":["Novas formigas serão "+kind+". Produção paga e limite de 30 mantidos."]}
func snapshot() -> Dictionary:return {"protections":protections,"births":births,"colony":colony,"learned":learned,"guardian":bool(thing.node_data.get("mods",{}).get("guardian",false))}
func apply_snapshot(data: Dictionary) -> void:
	protections=int(data.get("protections",0));births=int(data.get("births",0));colony=String(data.get("colony",""));learned=int(data.get("learned",0))
	if bool(data.get("guardian",false)) and not thing.node_data.get("mods",{}).get("guardian",false):
		thing.node_data.get_or_add("mods",{}).merge({"guardian":true,"armored":true},true);thing.rebuild_equipment_model()

extends Node

const GROUP := "creature_disposal_jobs"
var owner_id := 0
var world_ref: WeakRef
var rows: Array = []
var cursor := 0
var explosive := false
var holders: Dictionary = {}
var done := 0
static var totals := {"killed":0,"exploded":0}
static var frame := -1
static var processed := 0

static func blast_size(body: Thing) -> Dictionary:
 var size := body.bounds.size * body.global_basis.get_scale().abs()
 var radius := clampf(size.length() * .9, .75, 8.0)
 return {"radius":radius,"damage":clampf(12.0 * pow(radius,1.15),8.0,130.0)}

static func request(player: Player, settings: Dictionary) -> Dictionary:
 if not Forge.has_gameplay_authority() or not player.can_act(): return {"blocked":true,"warnings":["Você não pode dar ordens agora."]}
 for job in player.get_tree().get_nodes_in_group(GROUP):
  if job.owner_id == player.player_id: return {"blocked":true,"warnings":["Aguarde o comando anterior terminar."]}
 var species := String(settings.get("actor",""))
 var selected: Dictionary = {}
 var places: Dictionary = {}
 var candidates: Array = Forge.live_things(player.player_id).duplicate()
 candidates.append_array(Forge.world.get_node("Things").get_children())
 for candidate in candidates:
  if not candidate is Thing: continue
  var ball = candidate.get_node_or_null("CaptureBall")
  if ball != null and ball.occupant() != null: places[ball.occupant()] = candidate.center()
  for body in CreatureLimit.family(candidate):
   if body.owner_id != player.player_id or body.category != "creature" or body.is_dead or body._def.get("coop_boss",false): continue
   if not species.is_empty() and body.thing_id != species: continue
   selected[body] = true
 if selected.is_empty(): return {"blocked":true,"warnings":["Você não tem animais vivos desse tipo."]}
 var job = load("res://scripts/things/creature_disposal.gd").new()
 job.owner_id = player.player_id
 job.world_ref = weakref(Forge.world)
 job.explosive = settings.action == "detonate"
 # Snapshot and retain every source before a parent death or blast can remove another.
 for body: Thing in selected:
  var size := blast_size(body)
  body.hold_effect_job()
  body.set_meta("disposal_pending",true)
  var parent = body.get_parent()
  while parent is Thing:
   if not job.holders.has(parent):parent.hold_effect_job();job.holders[parent]=true
   parent=parent.get_parent()
  job.rows.append({"body":body,"at":places.get(body,body.center()),"radius":size.radius,"damage":size.damage,"killed":false})
 player.get_tree().root.add_child(job)
 job.add_to_group(GROUP)
 return {"animal_order":settings.action,"animal_count":selected.size(),"warnings":["%d animais seus vão %s." % [selected.size(),"explodir" if job.explosive else "ser eliminados"]]}

func _process(_delta: float) -> void:
 if not is_instance_valid(world_ref.get_ref()) or Forge.world != world_ref.get_ref() or not Forge.has_effect_authority():
  queue_free(); return
 if frame != Engine.get_process_frames():frame = Engine.get_process_frames();processed = 0
 var until := Time.get_ticks_usec()+2000
 while cursor < rows.size() and processed < 2:
  var row: Dictionary = rows[cursor]
  var body = row.body
  if not is_instance_valid(body) or body.owner_id != owner_id:
   _release(row);cursor+=1;continue
  # Deaths and terrain scans are bounded; native H-4 limits pace the detonations.
  if not row.killed:
   row.killed = true
   if explosive:body.explosion_spent = true
   body.die()
   totals.killed += 1
   processed += 1
   if Time.get_ticks_usec() >= until: return
  if explosive:
   if not Forge.explosion_ready(owner_id): return
   Combat.explode(body,row.at,row.radius,row.damage)
   totals.exploded += 1
   processed += 1
  _release(row)
  done += 1
  cursor += 1
  if Time.get_ticks_usec() >= until:break
 if cursor >= rows.size():queue_free()

func _release(row: Dictionary) -> void:
 var body = row.get("body")
 if is_instance_valid(body):
  body.remove_meta("disposal_pending")
  body.release_effect_job()
 row.body = null

func _exit_tree() -> void:
 for row in rows:_release(row)
 for holder in holders:
  if is_instance_valid(holder):holder.release_effect_job()

class_name CreatureLimit
extends RefCounted

static func cap() -> int:
 return maxi(1,int(Lexicon.bal("caps.live_creatures_per_player",30)))

static func family(body: Thing) -> Array:
 var result: Array=[]
 var pending: Array=[body]
 var seen: Dictionary={}
 while not pending.is_empty():
  var item=pending.pop_back()
  if not is_instance_valid(item) or item.is_dead or seen.has(item):continue
  seen[item]=true;result.append(item)
  pending.append_array(item.grafts)
  var ball=item.get_node_or_null("CaptureBall")
  if ball!=null and ball.occupant()!=null:pending.append(ball.occupant())
 return result

static func count(owner_id: int) -> int:
 var found: Dictionary={}
 var candidates: Array=Forge.live_things(owner_id).duplicate()
 if Forge.world!=null:
  candidates.append_array(Forge.world.get_node("Things").get_children())
 for body in candidates:
  if not body is Thing:continue
  for item in family(body):
   if item.category!="creature":continue
   var temporary=item.get_node_or_null("CreativeEffects")
   if item.owner_id==owner_id or (temporary!=null and temporary.team_time>0.0 and temporary.old_owner==owner_id):found[item]=true
 return found.size()

static func slots(node: Dictionary, grouped: bool=false, depth: int=0, budget: Dictionary={}) -> int:
 if budget.is_empty():budget={"left":int(Lexicon.bal("caps.grafts_per_recipe",16))}
 var total=1 if Lexicon.data.category_of(String(node.get("thing","")))=="creature" else 0
 if depth<int(Lexicon.bal("caps.graft_depth",4)):
  for graft in node.get("mods",{}).get("grafts",[]):
   if budget.left<=0:break
   budget.left-=1
   total+=slots(graft.get("node",{}),false,depth+1,budget)
 if grouped and Lexicon.data.placement_for(String(node.get("thing",""))) in ["front","aim_ground","flyover"]:
  total*=maxi(1,int(node.get("mods",{}).get("count",1)))
 return total

static func allows(owner_id: int, node: Dictionary, grouped: bool=false) -> bool:
 var needed=slots(node,grouped)
 return needed==0 or count(owner_id)+needed<=cap()

static func can_transfer(body: Thing, owner_id: int) -> bool:
 var extra=0
 for item in family(body):
  if item.category=="creature" and item.owner_id!=owner_id:extra+=1
 return extra==0 or count(owner_id)+extra<=cap()

static func warning() -> String:
 return "Limite de %d animais por jogador atingido. Remova um animal para criar outro." % cap()

extends Node

var thing: Thing
var rule = ""
var friend_ref: WeakRef
var passenger_ref: WeakRef
var carrier_ref: WeakRef
var passenger_id = 0
var carrier_id = 0
var friend_id = 0
var tick = 0.0
var carried_mask = 0
var label = ""
var rescued = false
var armored_model = 0

func setup(owner_thing: Thing) -> void: thing = owner_thing
func _ready() -> void: process_physics_priority = 50
func passenger(): return passenger_ref.get_ref() if passenger_ref != null else null
func carrier(): return carrier_ref.get_ref() if carrier_ref != null else null
func friend(): return friend_ref.get_ref() if friend_ref != null else null
func being_carried() -> bool: return is_instance_valid(carrier()) or (thing.network_replica and carrier_id > 0)
func carried_target() -> Node3D:
	var host=carrier()
	if not is_instance_valid(host) or not thing.can_act():return null
	var orders=thing.get_node("AnimalOrders")
	if orders.mode in ["stay","build","evade","base_retreat","base_repair"]:return null
	var filter:=InnovationRules.target_diet(thing)
	if filter.begins_with("player:"):
		var player=Forge.world.get_player(int(filter.trim_prefix("player:"))) if Forge.world!=null else null
		return player if orders._enemy(player) else null
	var chosen=orders.target_ref.get_ref() if orders.target_ref!=null else null
	var host_orders=host.get_node_or_null("AnimalOrders")
	if not orders._enemy(chosen) and host_orders!=null:chosen=host_orders.combat_target()
	if not orders._enemy(chosen):chosen=Combat.nearest_enemy(thing.center(),thing.team,get_tree())
	return chosen if orders._enemy(chosen) and thing.center().distance_to(Combat.center_of(chosen))<40.0 else null
static func speed_factor(source: Thing) -> float:
	var rig = source.get_node_or_null("CreatureTactics")
	return .75 if rig != null and is_instance_valid(rig.passenger()) else 1.0
func usable(target: Thing) -> bool:
	return is_instance_valid(target) and target != thing and not target.is_dead and not target.is_captured and not target.is_held and not target.is_building and target.owner_id == thing.owner_id and target.team == thing.team and target.mount_host == null and target.get_node_or_null("CoopBoss") == null
func can_carry(target: Thing) -> bool:
	if not usable(target) or being_carried() or is_instance_valid(passenger()): return false
	var other = target.get_node_or_null("CreatureTactics")
	if other == null or other.being_carried() or is_instance_valid(other.passenger()): return false
	var changing = target.get_node_or_null("CreatureTransform")
	if changing != null and changing.active: return false
	var flying = thing.move.hovers()
	var capacity = maxf(35.0,thing.weight*1.5) if flying else minf(2500.0,maxf(12.0,thing.weight*.65))
	return (flying and thing.weight >= 2.0 or not flying and thing.weight >= 12.0) and target.weight <= capacity and target.bounds.size.length() <= 8.0
func load_passenger(target: Thing) -> bool:
	if not can_carry(target) or thing.center().distance_to(target.center()) > 4.5: return false
	var other = target.get_node("CreatureTactics")
	passenger_ref = weakref(target)
	passenger_id = target.network_id
	other.carrier_ref = weakref(thing)
	other.carrier_id = thing.network_id
	other.carried_mask = target.collision_mask
	target.collision_mask = 0
	_exceptions(target,true)
	label = "Transportando "+Lexicon.data.thing_name(target.thing_id)
	return true
func _exceptions(target: Thing, add: bool) -> void:
	for a in [thing]+thing.grafts:
		for b in [target]+target.grafts:
			if not is_instance_valid(a) or not is_instance_valid(b): continue
			if add: a.add_collision_exception_with(b); b.add_collision_exception_with(a)
			else: a.remove_collision_exception_with(b); b.remove_collision_exception_with(a)
func unload() -> void:
	var target = passenger()
	passenger_ref = null
	passenger_id = 0
	if not is_instance_valid(target): return
	var other = target.get_node("CreatureTactics")
	other.carrier_ref = null
	other.carrier_id = 0
	_exceptions(target,false)
	if target.is_dead: return
	target.collision_mask = other.carried_mask
	target.velocity = Vector3.ZERO
	# A low, nearby clear point avoids teleporting through walls or dropping from flight altitude.
	var origin: Vector3 = thing.center()+thing.global_basis.x*(thing.bounds.size.x*.5+target.bounds.size.x*.5+.6)
	var spot = Forge.ground_point(origin,thing.up())
	var destination: Vector3 = spot+thing.up()*maxf(.15,-target.bounds.position.y+.1)
	var ray = PhysicsRayQueryParameters3D.create(thing.center(),destination,PhysicsLayers.WORLD)
	if origin.distance_to(destination) < 4.0 and thing.get_world_3d().direct_space_state.intersect_ray(ray).is_empty(): target.global_position = destination
	else: target.global_position = origin
	if target.move != null: target.move.landed = false
func detach() -> void:
	if thing.network_replica: return
	var parent = carrier()
	if is_instance_valid(parent): parent.get_node("CreatureTactics").unload()
	unload()
func cancel_rule() -> void:
	if rule == "rescue" and not thing.network_replica: unload()
	rule = ""
	friend_ref = null
	friend_id = 0
	rescued = false
func assign(action: String, target: Thing = null) -> void:
	if not thing.network_replica and is_instance_valid(passenger()): unload()
	thing.get_node("AnimalOrders").set_order("tactical",thing.global_position)
	rule = action
	friend_ref = weakref(target) if target != null else null
	friend_id = target.network_id if target != null else 0
	label = action
	rescued = false
static func choose(player: Player, species_id: String, exclude: Thing = null) -> Thing:
	var selected: Thing
	var best = INF
	for candidate in Forge.world.get_node("Things").get_children():
		if not candidate is Thing or candidate == exclude or candidate.thing_id != species_id or candidate.owner_id != player.player_id or candidate.team != player.team or candidate.is_dead or candidate.is_captured or candidate.is_held or candidate.is_building: continue
		var contact: Vector3 = candidate.center()
		if candidate._def.has("kaiju"):
			var box: AABB = candidate.global_transform*candidate.bounds
			contact=player.center().clamp(box.position,box.end)
		var distance: float = contact.distance_to(player.center())
		if distance > 60.0 or distance >= best: continue
		var ray = PhysicsRayQueryParameters3D.create(player.head.global_position,candidate.center(),PhysicsLayers.WORLD)
		if not player.get_world_3d().direct_space_state.intersect_ray(ray).is_empty(): continue
		best = distance
		selected = candidate
	return selected
static func request(player: Player, settings: Dictionary) -> Dictionary:
	if settings.get("action", "") in ["dismiss","detonate"]:
		return load("res://scripts/things/creature_disposal.gd").request(player, settings)
	if settings.get("action", "") == "target_player":
		return load("res://scripts/things/animal_orders.gd").request(player, {"species":settings.get("actor",""),"all":settings.get("all",false),"animal_order":"target_player","target_player":settings.get("target_player",0)})
	if not player.can_act(): return {"blocked":true,"warnings":["Você não pode dar ordens agora."]}
	var actor = choose(player,String(settings.get("actor","")))
	if actor == null: return {"blocked":true,"warnings":["A criatura precisa ser sua, estar visível e a até 60 m."]}
	var rig = actor.get_node("CreatureTactics")
	var action = String(settings.get("action",""))
	if action in ["transform","revert"]:
		var power = actor.get_node_or_null("CreatureTransform")
		if power == null: return {"blocked":true,"warnings":["Crie a criatura com uma transformação primeiro."]}
		if action == "revert": power.revert(); return {"warnings":["Voltou à forma original."]}
		return power.trigger()
	if action in ["release","cancel"]:
		rig.detach()
		rig.cancel_rule()
		actor.get_node("AnimalOrders").set_order("follow",actor.global_position)
		return {"warnings":["Carga liberada e regra cancelada."]}
	var target = choose(player,String(settings.get("target","")),actor) if settings.has("target") else null
	if settings.has("target") and target == null: return {"blocked":true,"warnings":["Invoque o companheiro ou a torre perto do animal primeiro."]}
	if action == "carry" and not rig.can_carry(target): return {"blocked":true,"warnings":["Carga grande demais, criatura sem capacidade ou transporte já ocupado."]}
	if action == "repair" and (actor.thing_id != "ant" or not rig.repairable(target)): return {"blocked":true,"warnings":["Use formigas para reparar uma estrutura, veículo ou criatura com armadura."]}
	if action in ["guard_friend","rescue"] and target.category != "creature": return {"blocked":true,"warnings":["Escolha uma criatura companheira para proteger."]}
	if action == "rescue" and not rig.can_carry(target): return {"blocked":true,"warnings":["Esse animal não tem capacidade para resgatar o companheiro."]}
	rig.assign(action,target)
	var count = 1
	if settings.get("all",false) and action in ["repair","guard_friend","defend_owner","retreat"]:
		for candidate in Forge.world.get_node("Things").get_children():
			if count >= 8: break
			if not candidate is Thing or candidate == actor or candidate.thing_id != actor.thing_id or candidate.owner_id != actor.owner_id or candidate.team != actor.team or not candidate.can_act() or candidate.is_captured or candidate.is_held or candidate.center().distance_to(player.center()) > 60.0: continue
			var sight = PhysicsRayQueryParameters3D.create(player.head.global_position,candidate.center(),PhysicsLayers.WORLD)
			if not player.get_world_3d().direct_space_state.intersect_ray(sight).is_empty(): continue
			candidate.get_node("CreatureTactics").assign(action,target)
			count += 1
	return {"creature_rule":action,"creature_count":count,"warnings":["Ordem salva para %d criatura(s). Ordens comuns cancelam a regra; diga 'solte a carga' para desembarcar." % count]}
func repairable(target: Thing) -> bool:
	return usable(target) and (target.category in ["structure","vehicle"] or bool(target.node_data.get("mods",{}).get("armored",false)) or target.get_node_or_null("ProtectionEmitter") != null)
func recent(victim: Node) -> Node3D:
	var record: Dictionary = victim.get_meta("animal_last_attacker",{})
	if not record.has("source") or Time.get_ticks_msec()-int(record.get("at",0)) > 6000: return null
	var attacker = record.source.get_ref()
	return attacker if is_instance_valid(attacker) else null
func _physics_process(delta: float) -> void:
	if not thing.has_simulation_authority() or not thing.is_active or thing.is_dead: return
	var rider = passenger()
	if is_instance_valid(rider):
		if not usable(rider): unload()
		else:
			var offset = -thing.up()*(thing.bounds.size.y*.5+rider.bounds.size.y*.55+.3) if thing.move.hovers() else thing.up()*(thing.bounds.size.y*.5+rider.bounds.size.y*.5+.2)
			rider.global_position += thing.center()+offset-rider.center()
			rider.velocity = Vector3.ZERO
	elif passenger_ref != null: unload()
	if being_carried() or not thing.can_act() or thing.category != "creature": return
	tick -= delta
	if tick > 0.0: return
	tick = .2
	if rule.is_empty(): return
	var owner = thing.owner_player
	if not is_instance_valid(owner) or not owner.is_alive(): detach(); cancel_rule(); return
	var orders = thing.get_node("AnimalOrders")
	if orders.mode != "tactical": cancel_rule(); return
	orders.target_ref = null
	orders.goal = owner.global_position
	var target = friend()
	if rule in ["guard_friend","rescue","repair","carry"] and not usable(target): detach(); cancel_rule(); orders.set_order("follow",thing.global_position); return
	match rule:
		"defend_owner":
			var attacker = recent(owner)
			if orders._enemy(attacker) and thing.center().distance_to(Combat.center_of(attacker)) < 20.0: orders.target_ref = weakref(attacker)
		"retreat":
			if thing.hp <= thing.max_hp*.35: orders.goal = owner.global_position
			else: orders.goal = thing.global_position
		"guard_friend", "rescue":
			orders.goal = target.global_position if not is_instance_valid(passenger()) else owner.global_position
			if rule == "rescue" and target.hp <= target.max_hp*.4 and not rescued:
				if load_passenger(target): rescued = true
			if rescued and thing.center().distance_to(owner.center()) < 4.0:
				unload(); label = "Companheiro entregue ao treinador"; rule = "guard_friend"; rescued = false
			var attacker = recent(target)
			if not is_instance_valid(passenger()) and orders._enemy(attacker) and thing.center().distance_to(Combat.center_of(attacker)) < 18.0: orders.target_ref = weakref(attacker)
		"carry":
			if not is_instance_valid(passenger()):
				orders.goal = target.global_position
				load_passenger(target)
			else:orders.goal=owner.global_position
		"repair":
			orders.goal = target.global_position
			if thing.center().distance_to(target.center()) <= 3.5 and target.hp < target.max_hp and int(target.get_meta("repair_after",0)) <= Time.get_ticks_msec():
				var amount = minf(4.0,target.max_hp-target.hp)
				if owner.try_spend(amount*.6):
					target.hp += amount
					target.set_meta("repair_after",Time.get_ticks_msec()+800)
					ExpansionFx.burst(Forge.fx_root(thing),target.center(),.4,Color("afc8a5"),"repair")
				else: label = "Reparo pausado: falta matéria"
func snapshot() -> Dictionary: return {"rule":rule,"friend":friend_id,"passenger":passenger_id,"carrier":carrier_id,"label":label,"rescued":rescued}
func apply_snapshot(data: Dictionary) -> void:
	rule = String(data.get("rule",""))
	friend_id = int(data.get("friend",0))
	passenger_id = int(data.get("passenger",0))
	carrier_id = int(data.get("carrier",0))
	label = String(data.get("label",""))
	rescued = bool(data.get("rescued",false))
func _process(_delta: float) -> void:
	if not bool(thing.node_data.get("mods",{}).get("armored",false)) or not is_instance_valid(thing.model): return
	if armored_model == thing.model.get_instance_id(): return
	armored_model = thing.model.get_instance_id()
	var material = StandardMaterial3D.new()
	material.albedo_color = Color("747d85")
	for side in [-1,1]:
		var plate = MeshInstance3D.new()
		var mesh = BoxMesh.new()
		mesh.size = Vector3(.08,clampf(thing.bounds.size.y*.45,.2,1.4),clampf(thing.bounds.size.z*.55,.2,2.0))
		plate.mesh = mesh
		plate.material_override = material
		plate.position = thing.bounds.get_center()+Vector3(side*(thing.bounds.size.x*.5+.04),0,0)
		thing.model.add_child(plate)

extends Node

var thing: Thing
var form = ""
var active = false
var remaining = 0.0
var cooldown = 0.0
var shot_left = 0.0
var weapon: Node

func setup(owner_thing: Thing) -> void:
	thing = owner_thing
	form = String(thing.node_data.get("mods",{}).get("transform_to",""))
static func price(node: Dictionary, lex: LexiconData) -> float:
	var id = String(node.get("mods",{}).get("transform_to",""))
	if lex.category_of(String(node.get("thing",""))) != "creature" or not load("res://scripts/language/tactical_language.gd").valid_form(id,lex): return 0.0
	return maxf(65.0,lex.thing_statf(id,"cost")*.8)*maxf(1.0,float(node.get("mods",{}).get("count",1)))
func trigger() -> Dictionary:
	var rig = thing.get_node_or_null("CreatureTactics")
	if not thing.can_act() or thing.is_captured or thing.is_held or thing.get_meta("ridden",false) or active or cooldown > 0.0 or (rig != null and (rig.being_carried() or is_instance_valid(rig.passenger()))): return {"blocked":true,"warnings":["Transformação indisponível: recarga, transporte ou criatura paralisada."]}
	active = true
	remaining = 12.0
	cooldown = 30.0
	shot_left = 1.0
	change_model()
	ExpansionFx.burst(Forge.fx_root(thing),thing.center(),1.6,Color("acb8cd"),"transformation")
	return {"transformed":form,"warnings":["Forma de "+Lexicon.data.thing_name(form)+" por 12 s. Vida e equipamentos preservados."]}
func revert() -> void:
	if not active: return
	active = false
	remaining = 0.0
	change_model()
func model_id() -> String: return form if active else thing.thing_id
func apply_stats() -> void:
	if not active: return
	thing.speed = Lexicon.data.thing_statf(form,"speed")*float(thing.node_data.get("mods",{}).get("speed",1.0))
	thing.weight = Lexicon.data.thing_statf(form,"weight_kg")
	for graft in thing.grafts:
		if is_instance_valid(graft): thing.weight += graft.weight
	thing.impact_damage = minf(32.0,maxf(thing.impact_damage,Lexicon.data.thing_statf(form,"impact_damage")))
func damage_multiplier() -> float: return .65 if active and Lexicon.data.category_of(form) == "vehicle" else .9 if active else 1.0
func change_model() -> void:
	var hp = thing.hp
	thing.rebuild_equipment_model()
	thing.hp = minf(hp,thing.max_hp)
	var definition: Dictionary = Lexicon.data.thing_def(form if active else thing.thing_id)
	var move_id = String(definition.get("movement","chase_enemy"))
	if not Assembler.MOVES.has(move_id): move_id = "chase_enemy"
	var old = thing.move
	thing.remove_child(old)
	old.queue_free()
	var next_move = Assembler.MOVES[move_id].new()
	next_move.name = "Move"
	next_move.setup(thing,Lexicon.data)
	thing.attach_move(next_move)
	if thing.network_replica: next_move.set_physics_process(false)
	var orders = thing.get_node_or_null("AnimalOrders")
	if orders != null: next_move.steering = orders.active()
	var motion = thing.get_node_or_null("VoxelCreatureMotion")
	if motion != null:
		motion.parts.clear()
		motion.setup(thing,next_move.hovers())
func _physics_process(delta: float) -> void:
	if not thing.has_simulation_authority() or not thing.is_active or thing.is_dead or thing.is_building or thing.is_held: return
	cooldown = maxf(0.0,cooldown-delta)
	if active:
		remaining -= delta
		if remaining <= 0.0: revert(); return
		shot_left -= delta
		if not thing.can_act() or shot_left > 0.0: return
		var target = Combat.nearest_target(thing,thing.center(),get_tree())
		if target == null or thing.center().distance_to(Combat.center_of(target)) > 24.0: return
		var ray = PhysicsRayQueryParameters3D.create(thing.center(),Combat.center_of(target),PhysicsLayers.WORLD)
		if not thing.get_world_3d().direct_space_state.intersect_ray(ray).is_empty(): return
		if weapon == null:
			for behavior in Lexicon.data.thing_def(form).get("behaviors",[]):
				if behavior.get("do",{}).get("type","") == "shoot":
					weapon = load("res://scripts/things/action/action_shoot.gd").new()
					weapon.name = "TransformWeapon"
					weapon.setup(thing,behavior["do"].duplicate(true))
					add_child(weapon)
					break
		if weapon != null:
			shot_left = 2.5
			weapon.run(ActionContext.make(thing.center(),Combat.center_of(target)-thing.center(),target))
	elif cooldown <= 0.0 and thing.hp <= thing.max_hp*.35:
		var rig = thing.get_node_or_null("CreatureTactics")
		if thing.can_act() and (rig == null or not rig.being_carried() and not is_instance_valid(rig.passenger())): trigger()
func snapshot() -> Dictionary: return {"active":active,"remaining":remaining,"cooldown":cooldown}
func apply_snapshot(data: Dictionary) -> void:
	var changed = active != bool(data.get("active",false))
	active = bool(data.get("active",false))
	remaining = float(data.get("remaining",0.0))
	cooldown = float(data.get("cooldown",0.0))
	if changed: change_model()

extends Node3D

var thing: Thing
var config := {}
var clock := 0.0
var remaining := 0.0
var selected := 0
var energy := 3
var combo := 0
var combo_at := -10.0
var kill_at := -10.0
var critical_until := 0.0
var dodges := 12
var dodge_at := -10.0
var scan_left := 0.0
var casts := 0
var energy_materials:Array[ShaderMaterial]=[]
var visual_energy:=-1

func setup(body: Thing,settings: Dictionary) -> void:
	thing=body;config=settings

func actor() -> Node3D:
	if thing.is_held and is_instance_valid(thing.owner_player): return thing.owner_player
	var source := thing
	while is_instance_valid(source.mount_host):source=source.mount_host
	return source

func origin() -> Vector3:
	var owner=actor()
	return owner.head.global_position if owner is Player else thing.center()

func equipped() -> bool:
	var personal=thing.get_node_or_null("PersonalPowers")
	return personal==null or personal.equipped()

func allowed() -> bool:
	if not thing.has_simulation_authority() or not thing.can_act() or thing.is_captured or not equipped():return false
	var owner=actor()
	if owner is Player and not owner.can_act():return false
	var orders=load("res://scripts/things/animal_orders.gd").of(thing)
	return orders==null or not orders.active() or orders.combat_target()!=null

func _physics_process(delta: float) -> void:
	if not thing.has_simulation_authority() or thing.is_captured:return
	clock+=delta;remaining=maxf(0,remaining-delta);scan_left-=delta
	if thing.category!="creature" or thing.get_meta("ridden",false) or scan_left>0 or remaining>0 or not allowed():return
	scan_left=.2
	var target:=Combat.nearest_target(thing,thing.center(),get_tree())
	if target==null:return
	var ctx:=ActionContext.make(thing.center(),Combat.center_of(target)-thing.center(),target)
	if thing.center().distance_to(Combat.center_of(target))>40:return
	var mode: String=config.kind
	if mode=="sans":mode=["bones","blue_bones","blaster","gravity"][selected%4]
	elif mode=="slayer":mode="slayer_melee" if thing.center().distance_to(Combat.center_of(target))<3 else "slayer_shot"
	if use(ctx,mode):selected+=1

func _target_point(target: Node3D,from: Vector3) -> Vector3:
	if target is Thing:
		var box: AABB=target.global_transform*target.bounds
		return from.clamp(box.position,box.end)
	return Combat.center_of(target)

func targets(from: Vector3,direction: Vector3,reach: float,cosine: float=.65,both:bool=false) -> Array:
	var found := []
	for target in JujutsuRules.candidates(get_tree()):
		if not is_instance_valid(target) or target==thing or target==actor() or not target.has_method("take_damage") or not Combat.affects(thing,target):continue
		if target is Thing and (target.is_dead or target.is_captured or target.is_held):continue
		var point:=_target_point(target,from)
		var delta:=point-from
		var dot:=delta.normalized().dot(direction)
		if delta.length()>reach or (delta.length()>.4 and (absf(dot) if both else dot)<cosine):continue
		var ray:=PhysicsRayQueryParameters3D.create(from,point,PhysicsLayers.WORLD,[thing.get_rid()])
		if not thing.get_world_3d().direct_space_state.intersect_ray(ray).is_empty():continue
		found.append(target)
	found.sort_custom(func(a,b):return Combat.center_of(a).distance_squared_to(from)<Combat.center_of(b).distance_squared_to(from))
	return found.slice(0,16)

func use(ctx: ActionContext,mode: String="") -> bool:
	if not allowed() or remaining>0:return false
	if mode.is_empty():mode=String(config.kind)
	var from:=origin();var direction:=ctx.direction.normalized()
	if actor() is Player:direction=actor().look_ray().direction
	match mode:
		"rail":
			var owner=actor();var now:float=owner._clock if owner is Player else clock
			if now<float(owner.get_meta("railcannon_ready",-1.0)):return false
			var end:=from+direction*120
			var ray:=PhysicsRayQueryParameters3D.create(from,end,PhysicsLayers.WORLD,[thing.get_rid()])
			var wall:=thing.get_world_3d().direct_space_state.intersect_ray(ray)
			if not wall.is_empty():end=wall.position
			var hits:=[]
			for target in JujutsuRules.candidates(get_tree()):
				if not is_instance_valid(target) or target==thing or target==owner or not target.has_method("take_damage") or not Combat.affects(thing,target):continue
				if target is Thing and (target.is_dead or target.is_captured or target.is_held):continue
				var point:=Combat.center_of(target)
				if target is Thing:
					var box: AABB=(target.global_transform*target.bounds).grow(.18)
					if box.intersects_segment(from,end)==null:continue
				else:
					if Geometry3D.get_closest_point_to_segment(point,from,end).distance_to(point)>.7:continue
				hits.append({"target":weakref(target),"damage":100.0*clampf(thing.power,.5,2.0),"push":Vector3.ZERO,"type":"electric"})
				if hits.size()>=32:break
			var work=load("res://scripts/things/blast_work.gd").new();work.setup(thing,hits);get_tree().root.add_child(work)
			load("res://scripts/fx/pokemon_fx.gd").play(Forge.fx_root(thing),from,end,"rail","")
			owner.set_meta("railcannon_ready",now+16.0);remaining=16
		"crucible","lance","slayer_melee":
			if clock-combo_at>2:combo=0
			var phase:=combo%3
			var found:=targets(from,direction,3.0 if mode!="lance" else 3.6,.2 if mode=="lance" else .55,mode=="lance" and phase==1)
			var damage:float=([40.0,52.0,82.0][phase]*(1.5 if clock<critical_until else 1.0)) if mode=="lance" else 50.0 if mode=="slayer_melee" else 450.0 if energy>0 else 36.0
			var charged:=false
			for target in found.slice(0,8 if mode=="lance" else 1):
				var before:float=target.hp if target is Thing else target.health
				Combat.apply_damage(target,damage*clampf(thing.power,.5,2.0),"slash" if mode=="lance" else "crucible" if mode=="crucible" else "melee",thing)
				if not is_instance_valid(target):continue
				var after:float=target.hp if target is Thing else target.health
				if before>after:charged=true
				if mode=="lance" and before>0 and after<=0:
					if clock-kill_at<=1.5:critical_until=clock+6.0
					kill_at=clock
			if mode=="crucible" and energy>0 and charged:energy-=1;thing.charges=energy;thing.ammo_changed.emit()
			Fx.slash(Forge.fx_root(thing),from,direction,3.6 if mode=="lance" else 3.0,360 if mode=="lance" and phase==1 else 150,"slash",Color("ff674a") if mode=="crucible" else Color("d6e7ef"),thing.is_held)
			combo+=1;combo_at=clock;remaining=.65 if mode!="slayer_melee" else 2.2
		"football","slayer_shot","bones","blue_bones":
			var id: String="neymar_ball" if mode=="football" else "bullet" if mode=="slayer_shot" else "sans_blue_bone" if mode=="blue_bones" else "sans_bone"
			var amount:=5 if mode=="slayer_shot" else 3 if mode in ["bones","blue_bones"] else 1
			var side:=direction.cross(thing.up()).normalized()
			var made:=0
			for index in amount:
				var heading:Vector3=(direction+side*(index-(amount-1)*.5)*.045).normalized()
				var node:=Recipe.new_node(id)
				var shot:=Forge.spawn_child(node,"projectile",from+direction*1.1+side*(index-(amount-1)*.5)*.18,heading,thing,-1,Vector3.ZERO,true)
				if shot!=null:
					if mode=="slayer_shot":shot.impact_damage=8.0
					made+=1
			if made==0:return false
			remaining=2.4 if mode=="football" else 2.2 if mode=="slayer_shot" else 2.8
		"blaster":
			if get_tree().get_nodes_in_group("cursed_beams").size()>=24:return false
			if Forge.spawn_child(Recipe.new_node("sans_blaster"),"projectile",from+direction*2.0,direction,thing,0,Vector3.ZERO,true)==null:return false
			remaining=5
		"gravity":
			var found:=targets(from,direction,28,.94)
			if found.is_empty():return false
			var target:Node3D=found[0]
			if JujutsuRules.field(target,"infinity")!=null and not JujutsuRules.bypasses(thing,"gravity"):return false
			Status.apply(target,"blue_soul",thing)
			var force:float=JujutsuRules.force(target,thing)
			if target.has_method("apply_knockback"):target.apply_knockback(-thing.up()*12*force)
			elif target is Thing:target.nudge(-thing.up()*12*force)
			load("res://scripts/fx/pokemon_fx.gd").play(Forge.fx_root(thing),from,Combat.center_of(target),"water","")
			remaining=6
		_:return false
	casts+=1
	return true

func avoid_damage(kind: String,source:Thing) -> bool:
	if String(config.kind) not in ["sans","sans_power"] or not thing.can_act() or thing.is_captured or not equipped() or dodges<=0 or clock-dodge_at<.6:return false
	if kind not in ["kinetic","bullet","bone","melee","bite","slash"] or not is_instance_valid(source):return false
	var owner:=actor()
	var side:=thing.up().cross(Combat.center_of(source)-Combat.center_of(owner)).normalized()
	if side.length_squared()<.1:side=thing.global_basis.x
	var step:=side*1.2
	if owner is CharacterBody3D and owner.test_move(owner.global_transform,step):return false
	owner.global_position+=step;dodges-=1;dodge_at=clock
	return true

func snapshot() -> Dictionary:return {"remaining":remaining,"selected":selected,"energy":energy,"combo":combo,"critical_left":maxf(0,critical_until-clock),"dodges":dodges,"casts":casts}
func apply_snapshot(state:Dictionary) -> void:
	remaining=maxf(0,float(state.get("remaining",0)));selected=int(state.get("selected",0));energy=clampi(int(state.get("energy",3)),0,3);combo=maxi(0,int(state.get("combo",0)));critical_until=clock+maxf(0,float(state.get("critical_left",0)));dodges=clampi(int(state.get("dodges",12)),0,12);casts=maxi(0,int(state.get("casts",0)))

func label() -> String:
	if config.kind=="crucible":return "Energia %d/3"%energy
	if config.kind=="rail":return "Recarga %.1f s"%remaining if remaining>0 else "Railcannon pronta"
	if config.kind=="lance":return "Críticos %.1f s"%maxf(0,critical_until-clock) if critical_until>clock else "Combo de 3 golpes"
	return ""

func _ready() -> void:
	if config.kind!="crucible":return
	for piece in thing.model_pieces:
		if piece.get_meta("tag","") in ["blade","rune"] and piece.material_override is ShaderMaterial:
			piece.material_override=piece.material_override.duplicate()
			energy_materials.append(piece.material_override)
func _process(_delta:float) -> void:
	if visual_energy==energy or energy_materials.is_empty():return
	visual_energy=energy
	for material in energy_materials:material.set_shader_parameter("emission_energy",1.8 if energy>0 else 0.0)

extends Node

var thing: Thing
var config := {}
var previous := Vector3.ZERO
var resolved := false
func setup(body: Thing, settings: Dictionary) -> void:
	thing = body
	config = settings
func _ready() -> void:
	add_to_group("cursed_projectiles")
	if String(config.mode)=="fuga":thing.model.scale*=1.6
func activate() -> void:
	previous = thing.center()
	thing.collision_mask = 0
	thing.collision_layer = 0
	thing.set_collision_disabled(true)
func _process(_delta: float) -> void:
	if thing.is_dead or not thing.is_active: return
	if String(config.mode) == "dismantle": thing.model.rotation.z += .1
func _physics_process(_delta: float) -> void:
	if resolved or not thing.is_active or thing.is_dead or not thing.has_simulation_authority(): return
	var point := thing.center()
	var query := PhysicsRayQueryParameters3D.create(previous, point, PhysicsLayers.WORLD)
	var hit := thing.get_world_3d().direct_space_state.intersect_ray(query) if previous.distance_squared_to(point) > .00001 else {}
	if not hit.is_empty(): point = hit.position
	var selected: Node3D
	var best := INF
	for target in JujutsuRules.candidates(get_tree()):
		if not is_instance_valid(target) or target == thing or target == thing.spawner or target == thing.owner_player or not target.has_method("take_damage") or not Combat.affects(thing, target): continue
		if target is Thing and (target.is_dead or target.is_captured or target.is_held or target.category == "projectile"): continue
		var at := Combat.center_of(target)
		var radius: float = clampf(target.bounds.size.length() * .25, .3, 1.5) if target is Thing else .6
		var closest := Geometry3D.get_closest_point_to_segment(at, previous, point)
		if at.distance_to(closest) > radius + .25: continue
		var wall := PhysicsRayQueryParameters3D.create(previous, at, PhysicsLayers.WORLD)
		if not thing.get_world_3d().direct_space_state.intersect_ray(wall).is_empty(): continue
		var distance := previous.distance_squared_to(closest)
		if distance < best: best = distance; selected = target; point = closest
	previous = thing.center()
	if selected == null and hit.is_empty(): return
	resolved = true
	var fx = load("res://scripts/fx/jujutsu_impact.gd")
	if String(config.mode) == "fuga":
		# Impact is a fire detonation; it is not an instantaneous line of damage.
		Combat.explode(thing, point, 8.0, 140.0 * thing.power, "fire")
		Combat.area_status(thing, point, 8.0, "burning")
		fx.play(Forge.fx_root(thing),point,thing.travel_direction(),"fuga_burst")
	else:
		if selected != null: Combat.apply_damage(selected, 32.0 * thing.power, "slash", thing)
		var cut = load("res://scripts/things/spatial_cut_work.gd").new()
		cut.setup(thing)
		get_tree().root.add_child(cut)
		cut.add_segment(point, point, .6, 50.0)
		fx.play(Forge.fx_root(thing), point, thing.travel_direction(), "dismantle")
	thing.remove()

extends Node
var first:Thing
var second:Thing
var left:=.4
var blue_wait:=0.0
static func request(player: Player, a: String, b: String) -> Dictionary:
	var chooser=load("res://scripts/things/creature_tactics.gd")
	var one=chooser.choose(player,a);var two=chooser.choose(player,b)
	if one==null or two==null or one==two:return {"blocked":true,"warnings":["O combo precisa de duas criaturas suas disponíveis."]}
	if Time.get_ticks_msec()<int(player.get_meta("duo_after",0)):return {"blocked":true,"warnings":["Aguarde oito segundos entre combos."]}
	var p=one.get_node_or_null("PokemonCompanion");var q=two.get_node_or_null("PokemonCompanion")
	if p!=null and q!=null:
		if (q.element=="water" and p.element=="electric") or (q.element=="grass" and p.element=="fire"):var swap=one;one=two;two=swap
	elif two.get_node_or_null("Jujutsu")!=null and two.get_node("Jujutsu").powers.has("blue"):var swap=one;one=two;two=swap
	if not compatible(one,two):return {"blocked":true,"warnings":["Combine água com eletricidade, cipós com fogo ou Azul com outro atacante."]}
	if not ready(one) or not ready(two):return {"blocked":true,"warnings":["Aguarde as recargas e aproxime as criaturas do inimigo."]}
	var primary=one.get_node_or_null("PokemonCompanion")
	var target=primary._target(18) if primary!=null else Combat.nearest_target(one,one.center(),player.get_tree())
	if target==null or not Combat.affects(two,target) or two.center().distance_to(Combat.center_of(target))>18:return {"blocked":true,"warnings":["A dupla precisa alcançar o mesmo inimigo."]}
	if not player.try_spend(20):return {"blocked":true,"warnings":["Coordenar o combo custa 20 de matéria."]}
	for actor in [one,two]:actor.get_node("AnimalOrders").set_order("attack",actor.global_position,target)
	player.set_meta("duo_after",Time.get_ticks_msec()+8000)
	var combo=load("res://scripts/things/duo_combo.gd").new();combo.first=one;combo.second=two;one.add_child(combo)
	if one.get_node_or_null("Jujutsu")!=null and one.get_node("Jujutsu").powers.has("blue"):combo.blue_wait=1.8
	combo.fire(one)
	return {"warnings":["Ataque combinado iniciado; cada criatura respeita sua própria recarga e alcance."]}
static func compatible(a:Thing,b:Thing) -> bool:
	var p=a.get_node_or_null("PokemonCompanion");var q=b.get_node_or_null("PokemonCompanion")
	var j=a.get_node_or_null("Jujutsu")
	return (p!=null and q!=null and ((p.element=="water" and q.element=="electric") or (p.element=="grass" and q.element=="fire"))) or (j!=null and j.powers.has("blue"))
static func ready(actor:Thing) -> bool:
	if not actor.can_act() or actor.is_held or actor.is_captured:return false
	var p=actor.get_node_or_null("PokemonCompanion");var j=actor.get_node_or_null("Jujutsu")
	if p!=null:return p.remaining<=0 and p._target(18)!=null
	return Combat.nearest_target(actor,actor.center(),actor.get_tree())!=null and (j==null or j.clock>=j.next_cast)
func fire(actor:Thing) -> void:
	if not is_instance_valid(actor) or not ready(actor):return
	var p=actor.get_node_or_null("PokemonCompanion");var j=actor.get_node_or_null("Jujutsu")
	if p!=null:
		var key:String=p.moves.keys()[0]
		for candidate in p.moves:
			if p.moves[candidate].style=="vine":key=candidate;break
		p.cast(key)
	elif j!=null:
		var target=Combat.nearest_target(actor,actor.center(),get_tree())
		var key:="blue" if j.powers.has("blue") else ""
		if key.is_empty():
			for candidate in j.powers:
				if candidate in ["red","purple","cleave","contact_cleave","world_cut","fuga","black_flash","ryu_beam","yuta_beam"]:key=candidate;break
		if key.is_empty():actor.get_node("AnimalOrders")._attack(target)
		else:load("res://scripts/things/creative_expansion.gd").cast_power(actor,key,ActionContext.make(actor.center(),(Combat.center_of(target)-actor.center()).normalized()))
	else:
		var target=Combat.nearest_target(actor,actor.center(),get_tree());actor.get_node("AnimalOrders").set_order("attack",actor.global_position,target)
func _physics_process(delta:float) -> void:
	if blue_wait>0:
		blue_wait-=delta
		if not is_instance_valid(first) or not is_instance_valid(second):queue_free();return
		var target=Combat.nearest_target(second,second.center(),get_tree())
		var status=Status.of(target) if target!=null else null
		if status!=null and status.remaining.has("blue_grasp"):blue_wait=0;left=0
		else:return
	left-=delta
	if left<=0:fire(second);queue_free()

extends Node

var thing: Thing
var config: Dictionary = {}
var diet := ""
var clock := 0.0
var next_production := 2.0
var next_bite := 0.0
var queen_ref: WeakRef


func setup(owner_thing: Thing, settings: Dictionary, diet_id: String) -> void:
	thing = owner_thing
	config = settings
	diet = diet_id
	process_physics_priority = -20


func _physics_process(delta: float) -> void:
	if not is_instance_valid(thing) or not thing.can_act():
		return
	clock += delta
	if not diet.is_empty():
		_hunt()
	if not config.is_empty() and clock >= next_production:
		next_production = clock + maxf(float(config.get("interval", 5.0)), 2.5)
		_produce()


func _living_queen() -> bool:
	if not bool(config.get("needs_queen", false)):
		return true
	if queen_ref != null:
		var queen = queen_ref.get_ref()
		return is_instance_valid(queen) and not queen.is_dead and not queen.is_captured and queen.team == thing.team
	if is_instance_valid(thing.spawner) and thing.spawner is Thing and InnovationRules.tags(thing.spawner).has("queen"):
		queen_ref = weakref(thing.spawner)
		return not thing.spawner.is_dead and not thing.spawner.is_captured and thing.spawner.team == thing.team
	if Forge.world != null:
		for candidate in Forge.world.get_node("Things").get_children():
			var queen := candidate as Thing
			if queen != null and not queen.is_dead and not queen.is_captured and queen.team == thing.team and InnovationRules.tags(queen).has(String(config.get("queen_tag", "ant_queen"))) and queen.center().distance_to(thing.center()) < 12.0:
				queen_ref = weakref(queen)
				return true
	return false


func _produce() -> void:
	if not _living_queen():
		return
	var child_id := String(config.get("produces", ""))
	if child_id.is_empty():
		return
	var ahead := Gravity.flat(-thing.global_basis.z, thing.up()).normalized()
	var spot := Forge.ground_point(thing.global_position + ahead * (maxf(thing.bounds.size.x, thing.bounds.size.z) * 0.5 + 1.0), thing.up())
	var recipe:=Recipe.new_node(child_id)
	var queen:Thing=thing if thing.thing_id=="queen_ant" else thing.spawner as Thing
	var craft=queen.get_node_or_null("CreatureCraft") if is_instance_valid(queen) else null
	if child_id=="ant" and craft!=null:
		if craft.colony=="soldados":recipe.mods={"colony_guard":true,"armored":true}
		elif craft.colony=="operarias":recipe.mods={"colony_worker":true}
	var child := Forge.spawn_child(recipe, "spawned", spot, ahead, thing, 0.0)
	if child != null:
		child.lifetime = 0.0


func _hunt() -> void:
	var orders := thing.get_node_or_null("AnimalOrders")
	if orders != null and orders.active(): return
	if Forge.world == null or thing.move == null:
		return
	thing.move.steering = true
	var prey := Combat.nearest_target(thing, thing.center(), get_tree()) as Thing
	var up := thing.up()
	var airborne := thing.move.hovers()
	if prey == null:
		thing.velocity = Vector3.ZERO if airborne else up * thing.velocity.dot(up)
		return
	var direction := prey.center() - thing.center()
	var craft=thing.get_node_or_null("CreatureCraft")
	if craft!=null:direction=craft.navigate(prey.center())-thing.center()
	if airborne:
		thing.velocity = direction.normalized() * maxf(thing.speed, 0.6) if direction.length() > 0.65 else Vector3.ZERO
	else:
		direction = Gravity.flat(direction, up)
		thing.velocity = direction.normalized() * maxf(thing.speed, 0.6) + up * thing.velocity.dot(up) if direction.length() > 0.65 else up * thing.velocity.dot(up)
	if direction.length_squared() > 0.01: thing.face(direction, true)
	var own_box: AABB = thing.global_transform * thing.bounds
	var prey_box: AABB = prey.global_transform * prey.bounds
	var gap := (prey_box.position - own_box.end).max(own_box.position - prey_box.end).max(Vector3.ZERO).length()
	var reach := clampf(thing.scale_factor * 0.65, 0.4, 2.0)
	if gap <= reach and clock >= next_bite:
		var query := PhysicsRayQueryParameters3D.create(thing.center(), prey.center(), PhysicsLayers.WORLD)
		if not thing.get_world_3d().direct_space_state.intersect_ray(query).is_empty(): return
		next_bite = clock + 0.7
		# Diet is an explicit ecological relationship, including prey of the same team.
		Combat.apply_damage(prey, maxf(7.0, thing.impact_damage * 2.0), "bite", thing)
		ExpansionFx.burst(Forge.fx_root(thing), prey.center(), 0.25, Color("d6b982"), "bite")

extends RefCounted

# Keep the original elephant geometry and add an ankle for the sole and nails.
# Other creatures retain their native gait. Apply after anatomy rebuilding too.
static func build(original: Array, original_rig: Dictionary) -> Dictionary:
	var pieces:=original.duplicate(true)
	var rig:=original_rig.duplicate(true)
	var joints:Dictionary=rig.get("joints",{})
	for name:String in joints.keys():
		if not name.begins_with("knee_"):continue
		var spec:Dictionary=joints[name]
		if not spec.has("foot"):continue
		var attached:Array=[]
		for piece:Dictionary in pieces:
			if piece.get("bone","")==name and piece.get("tag","") in ["paw","foot","hoof","claw"]:attached.append(piece)
		if attached.is_empty():continue
		var ankle:="foot_"+name.trim_prefix("knee_")
		joints[ankle]={"pivot":spec.foot.duplicate(),"parent":name,"type":"foot","level_sole":true}
		for piece:Dictionary in attached:
			piece["collision_bone"]=name
			piece.bone=ankle
	return {"pieces":pieces,"rig":rig}

