var thing: Thing
var remaining = 0.0
var companions: Array[Node] = []
var cursor = 0

func setup(owner_thing: Thing, primary: String, lex: LexiconData) -> void:
	thing = owner_thing
	for donor in load("res://scripts/things/fusion_rules.gd").donors(thing.node_data, lex):
		var settings: Dictionary = lex.thing_def(donor).get("pokemon", {})
		if settings.is_empty() or donor == primary: continue
		var companion = load("res://scripts/things/pokemon_companion.gd").new()
		companion.name = "Fusion_" + donor
		companion.setup(thing,settings)
		# Inherited skills cannot evolve a part for free or earn duplicate combat XP.
		companion.evolution = {}
		add_child(companion)
		companions.append(companion)

func _physics_process(delta: float) -> void:
	if thing.has_simulation_authority() and thing.is_active: remaining = maxf(0.0,remaining-delta)

func auto_attack() -> void:
	if remaining > 0.0 or companions.is_empty(): return
	var choices: Array = companions.duplicate()
	var primary = thing.get_node_or_null("PokemonCompanion")
	if primary != null: choices.push_front(primary)
	for step in choices.size():
		var index: int = (cursor+step)%choices.size()
		var companion = choices[index]
		if companion.remaining <= 0.0:
			var reply: Dictionary = companion.cast(String(companion.moves.keys()[0]))
			if not reply.get("blocked",false): cursor = (index+1)%choices.size(); return

func snapshot() -> Dictionary:
	var values = {}
	for companion in companions: values[companion.name] = companion.snapshot()
	return {"remaining":remaining,"skills":values}

func apply_snapshot(values: Dictionary) -> void:
	remaining = float(values.get("remaining",0.0))
	for companion in companions:
		if values.get("skills",{}).has(companion.name): companion.apply_snapshot(values.skills[companion.name])

extends RefCounted

# At most three different donors can contribute skills; repeated parts never stack.
static func donors(node: Dictionary, lex: LexiconData) -> Array[String]:
	var result: Array[String] = []
	if lex.category_of(String(node.get("thing", ""))) != "creature": return result
	var mods: Dictionary = node.get("mods", {})
	var candidates: Array = []
	for part in ["head", "body", "wings", "tail", "legs"]:
		var donor = String(mods.get("anatomy", {}).get(part, ""))
		if not donor.is_empty(): candidates.append(donor)
	for key: String in mods:
		if key.begins_with("fusion_") and mods[key] == true: candidates.append(key.trim_prefix("fusion_"))
	for donor: String in candidates:
		var def: Dictionary = lex.thing_def(donor)
		if donor == node.thing or result.has(donor): continue
		if def.get("pokemon", {}).is_empty() and def.get("jujutsu", {}).is_empty() and not def.get("fusion_behaviors",false) and not def.has("kaiju") and not def.has("crossover"): continue
		result.append(donor)
		if result.size() == 3: break
	return result

static func price(node: Dictionary, lex: LexiconData) -> float:
	var total = 0.0
	for donor in donors(node, lex): total += maxf(35.0, lex.thing_statf(donor, "cost") * .6)
	return total * maxf(1.0, float(node.get("mods", {}).get("count", 1)))

static func describe(node: Dictionary, lex: LexiconData) -> String:
	var names = PackedStringArray()
	for donor in donors(node, lex): names.append(lex.thing_name(donor))
	return "" if names.is_empty() else "Poderes herdados: %s (+%.0f de matéria)." % [", ".join(names), price(node,lex)]

class_name GroundItems
extends RefCounted

static func target(player: Player) -> Thing:
	if player == null or not player.is_inside_tree(): return null
	var aim := player.aim()
	var query := PhysicsRayQueryParameters3D.create(aim.origin, aim.origin + aim.direction * 4.0, PhysicsLayers.SOLID | PhysicsLayers.PROJECTILES)
	var exclusions: Array[RID] = [player.get_rid()]
	for i in player.hands.slot_count():
		var held := player.hands.item_at(i)
		if held != null:
			exclusions.append(held.get_rid())
			for graft in held.grafts:
				if is_instance_valid(graft): exclusions.append(graft.get_rid())
	query.exclude = exclusions
	var hit := player.get_world_3d().direct_space_state.intersect_ray(query)
	if hit.is_empty(): return null
	var item: Variant = hit.collider
	while is_instance_valid(item) and item is Thing and is_instance_valid(item.mount_host): item = item.mount_host
	return item as Thing if is_instance_valid(item) and item is Thing and can_pickup(player, item) else null

static func can_pickup(player: Player, item: Thing) -> bool:
	if not is_instance_valid(item) or item.is_dead or item.is_held or item.is_captured or item.is_building or not item.ground_item: return false
	if not is_instance_valid(player) or not player.can_act() or player.piloting != null or player.extracting or player.shaper.active: return false
	if item.velocity.length() > 2.0 or Time.get_ticks_msec() < item.pickup_after_ms: return false
	var at := item.center()
	if player.center().distance_to(at) > 4.0: return false
	var query := PhysicsRayQueryParameters3D.create(player.head.global_position, at, PhysicsLayers.WORLD)
	return player.get_world_3d().direct_space_state.intersect_ray(query).is_empty()

static func drop(item: Thing, at: Vector3, velocity: Vector3) -> void:
	Forge.world.add_thing(item)
	item.set_held(false)
	item.ground_item = true
	item.pickup_after_ms = Time.get_ticks_msec() + 500
	item.lifetime = 0.0
	item.age = 0.0
	item.is_anchored = false
	item.visible = true
	item.global_position = at
	item.velocity = velocity
	if item.move != null: item.move.landed = false
	Hands._set_layers(item, 1)
	if item.owner_player is PhysicsBody3D: item.add_collision_exception_with(item.owner_player)
	if item.get_node_or_null("GroundMotion") == null:
		var motion = load("res://scripts/things/ground_motion.gd").new()
		motion.name = "GroundMotion"
		motion.thing = item
		item.add_child(motion)
	Forge._register(item)
	if Session.is_online(): Session.creations.publish_creation(item, 0.0, false, item.matter)

class_name InnovationRules
extends RefCounted


static func profile(node: Dictionary, lex: LexiconData) -> String:
	return String(node.get("mods", {}).get("shield_profile", lex.thing_def(String(node.get("thing", ""))).get("shield_profile", "")))


static func authorize_spawn(source: Thing, node: Dictionary) -> bool:
	if not is_instance_valid(source):
		return false
	var lex := Lexicon.data
	var id := String(node.get("thing", ""))
	var def := lex.thing_def(id)
	var owner_def := lex.thing_def(source.thing_id)
	var ecology: Dictionary = owner_def.get("ecology", {})
	var protected := not profile(node, lex).is_empty()
	var managed := protected or def.has("ecology") or not ecology.is_empty()
	if not managed:
		return true
	var count := 0
	if Forge.world != null:
		for candidate in Forge.world.get_node("Things").get_children():
			var item := candidate as Thing
			if item == null or item.is_dead or item.is_held:
				continue
			if protected and item.team == source.team and not profile(item.node_data, lex).is_empty():
				count += 1
			elif not protected and item.thing_id == id and item.spawner == source:
				count += 1
	var cap := 3 if protected else int(ecology.get("local_cap", 1 if id.ends_with("nest") else 8))
	if not protected and String(def.get("category", "")) == "creature":
		cap = 0
	if cap > 0 and count >= cap:
		return false
	var player := source.owner_player as Player
	if player == null or not player.is_alive():
		return false
	var cost := Cost.of(node, lex)
	if player.matter_spendable() + 0.0001 < cost:
		return false
	player.take_matter(cost)
	return true


static func tags(thing: Thing) -> Array:
	return Lexicon.data.thing_def(thing.thing_id).get("ecology_tags", [])

static func matches_diet(thing: Thing, diet: String) -> bool:
	if diet == "creature":
		return thing.category == "creature"
	if diet.begins_with("species:"):
		return thing.thing_id == diet.trim_prefix("species:")
	return tags(thing).has(diet)


static func target_diet(source: Thing) -> String:
	# Mounted weapons and their projectiles obey the carrier's species restriction.
	var cursor := source
	var seen := {}
	while is_instance_valid(cursor) and not seen.has(cursor.get_instance_id()):
		seen[cursor.get_instance_id()] = true
		if not cursor.target_filter.is_empty(): return cursor.target_filter
		var chosen := int(cursor.node_data.get("mods", {}).get("target_player", 0))
		if chosen >= 1 and chosen <= 4: return "player:%d" % chosen
		var diet := String(cursor.node_data.get("mods", {}).get("diet", Lexicon.data.thing_def(cursor.thing_id).get("diet", "")))
		if not diet.is_empty() or cursor.category == "creature": return diet
		# Release builds cannot safely cast a reference after the held item was freed.
		var parent: Variant = cursor.mount_host if is_instance_valid(cursor.mount_host) else cursor.spawner
		cursor = parent as Thing if is_instance_valid(parent) else null
	return ""


static func allows_target(source: Thing, target: Object) -> bool:
	if not is_instance_valid(target): return false
	var diet := target_diet(source)
	if diet.begins_with("player:"): return target is Player and target != source.owner_player and target.player_id == int(diet.trim_prefix("player:"))
	return diet.is_empty() or (target is Thing and target != source and matches_diet(target, diet))


static func threat(source: Thing, damage_type: String) -> String:
	if damage_type in ["neutron", "gravity", "spatial"]:
		return damage_type
	if is_instance_valid(source):
		# Preserve original H-4 definitions while recognizing them in Lab defenses.
		if source.thing_id in ["atomic_bomb", "little_boy", "fat_man", "tsar_bomba"] and damage_type == "explosive": return "nuclear"
		var specific := String(Lexicon.data.thing_def(source.thing_id).get("threat_type", ""))
		if not specific.is_empty():
			return specific
	return "blast" if damage_type == "explosive" else damage_type


static func multiplier(shield_profile: String, kind: String) -> float:
	var table: Dictionary = Lexicon.bal("innovation.resistance." + shield_profile, {})
	return clampf(float(table.get(kind, 1.0)), 0.10, 1.0)


static func _best(target: Node3D, kind: String):
	var best
	var value := 1.0
	var team: Variant = target.get("team")
	if team == null:
		return null
	for node in target.get_tree().get_nodes_in_group("protective_fields"):
		var shield := node.get_parent() as Thing
		if shield == null or shield.is_dead or shield.is_building or not shield.is_active or shield.team != int(team):
			continue
		var current := multiplier(String(node.profile_id), kind)
		if current < value and shield.center().distance_to(Combat.center_of(target)) <= float(node.radius):
			value = current
			best = node
	return best


static func protected_damage(target: Object, amount: float, kind: String, source: Thing) -> float:
	if not is_instance_valid(target) or not target is Node3D or kind == "shield_strain":
		return amount
	var field = _best(target as Node3D, threat(source, kind))
	if field == null:
		return amount
	var factor := multiplier(String(field.profile_id), threat(source, kind))
	var shield := field.get_parent() as Thing
	var saved := amount * (1.0 - factor)
	if shield != target:
		# Held shields have real durability too; normal held-item immunity must not bypass wear.
		shield.hp -= saved * float(Lexicon.bal("innovation.shield_wear", 0.70))
		if shield.hp <= 0.0:
			shield.die()
	field.feedback()
	return amount * factor


static func force_multiplier(target: Node3D, source: Thing) -> float:
	var adaptation := JujutsuRules.force(target, source)
	if adaptation == 0.0: return 0.0
	var kind := String(Lexicon.data.thing_def(source.thing_id).get("threat_type", "gravity")) if is_instance_valid(source) else "gravity"
	var field = _best(target, kind)
	return adaptation * (multiplier(String(field.profile_id), kind) if field != null else 1.0)

extends RefCounted

static var storage_path:="user://creative_inventions.json"
static func read() -> Dictionary:
	if not FileAccess.file_exists(storage_path):return {}
	var text:=FileAccess.get_file_as_string(storage_path)
	if text.length()>100000:return {}
	var data:Variant=JSON.parse_string(text)
	return data if data is Dictionary else {}
static func write(data: Dictionary) -> bool:
	var temp:=storage_path+"."+str(OS.get_process_id())+".tmp"
	var file:=FileAccess.open(temp,FileAccess.WRITE)
	if file==null:return false
	file.store_string(JSON.stringify(data));file.close()
	return DirAccess.rename_absolute(ProjectSettings.globalize_path(temp),ProjectSettings.globalize_path(storage_path))==OK
static func local_request(player_id: int, text: String) -> Dictionary:
	if Session.is_online() and player_id!=Session.local_player_id:return {}
	var clean:=Normalizer.fold(text).strip_edges();var data:=read()
	if clean in ["listar invencoes","minhas invencoes"]:return {"warnings":["Invenções: "+", ".join(data.keys()) if not data.is_empty() else "Mire numa criação sua e diga: salvar esta criacao como Vespa Suprema."]}
	var rx:=RegEx.new();rx.compile("^(?:salvar|salve) (?:esta |essa |a )?(?:criacao|invencao) como (.+)$")
	var hit:=rx.search(clean)
	if hit!=null:
		var title:=hit.get_string(1).strip_edges()
		if title.length()<2 or title.length()>40:return {"blocked":true,"warnings":["Use um nome entre 2 e 40 letras."]}
		if not data.has(title) and data.size()>=50:return {"blocked":true,"warnings":["Limite de 50 invenções. Exclua uma antes de salvar outra."]}
		if not load("res://scripts/language/tactical_language.gd").species(title,Lexicon.data).is_empty():return {"blocked":true,"warnings":["Escolha um nome próprio, como Vespa Suprema, para não substituir uma espécie."]}
		var player=Forge.world.get_player(player_id) if Forge.world!=null else null
		if player==null:return {"blocked":true}
		var selected=player.aim().get("collider")
		if not selected is Thing or selected.owner_id!=player_id:selected=player.hands.current_item()
		if not selected is Thing or selected.owner_id!=player_id or selected.is_captured or selected.is_building or selected.is_dead:return {"blocked":true,"warnings":["Mire numa criação sua pronta ou segure o equipamento."]}
		var phrase:String=selected.node_data.get("mods",{}).get("_creation_text","")
		if phrase.is_empty():return {"blocked":true,"warnings":["Recrie esta invenção por texto/voz uma vez para salvar seu pedido completo."]}
		data[title]={"phrase":phrase,"version":1}
		var saved:=write(data)
		return {"blocked":not saved,"warnings":["Invenção salva: "+title+". Use V/T: quero "+title+". A recriação cobra o custo normal." if saved else "Não foi possível gravar suas invenções neste PC."]}
	rx.compile("^(?:excluir|apagar) invencao (.+)$");hit=rx.search(clean)
	if hit!=null:
		data.erase(hit.get_string(1));return {"blocked":not write(data),"warnings":["Invenção removida da sua lista."]}
	rx.compile("^(?:(?:eu )?quero|recriar|recrie|invoque|crie) (?:um |uma |o |a )?(.+)$");hit=rx.search(clean)
	if hit!=null and data.has(hit.get_string(1)):
		var entry:Variant=data[hit.get_string(1)]
		if entry is Dictionary and entry.get("phrase") is String and entry.phrase.length()<=800:return {"expanded":entry.phrase}
	return {}

class_name JujutsuRules
extends RefCounted

const KEYS := ["adaptation", "infinity", "cleave", "contact_cleave", "world_cut", "fuga", "black_flash", "reverse", "shrine", "void", "simple_domain", "amplification", "blue", "red", "purple", "ryu_beam", "yuta_beam"]

static func powers(node: Dictionary, lex: LexiconData) -> Dictionary:
	var out: Dictionary = lex.thing_def(String(node.get("thing", ""))).get("jujutsu", {}).duplicate()
	for donor in load("res://scripts/things/fusion_rules.gd").donors(node,lex):
		out.merge(lex.thing_def(donor).get("jujutsu",{}))
	for key in KEYS:
		if node.get("mods", {}).get("jj_" + key, false): out[key] = true
	return out

static func of(source: Thing):
	var cursor := source
	var seen := {}
	while is_instance_valid(cursor) and not seen.has(cursor.get_instance_id()):
		seen[cursor.get_instance_id()] = true
		var component = cursor.get_node_or_null("Jujutsu")
		if component != null: return component
		var parent: Variant = cursor.mount_host if is_instance_valid(cursor.mount_host) else cursor.spawner
		cursor = parent as Thing if is_instance_valid(parent) else null
	return null

static func field(target: Object, key: String):
	if not is_instance_valid(target) or not target is Node or not target.is_inside_tree(): return null
	for component in target.get_tree().get_nodes_in_group("jujutsu_users"):
		if component.enabled(key) and component.protects(target): return component
	return null

static func character_rivals(source: Thing, target: Object) -> bool:
	if not is_instance_valid(source) or not is_instance_valid(target) or not target is Thing: return false
	var user = of(source)
	if user == null: return false
	var identity := String(user.thing._def.get("jj_character", ""))
	return (identity == "gojo" and target._def.get("jj_character", "") == "sukuna") or (identity == "sukuna" and target._def.get("jj_character", "") == "gojo")

static func rival_target(source: Thing) -> Thing:
	if not is_instance_valid(source): return null
	var user = of(source)
	return user.preferred_rival() if user != null else null

static func domain_opponents(a: Node, b: Node) -> bool:
	return a.thing.team != b.thing.team or character_rivals(a.thing, b.thing)

static func bypasses(source: Thing, kind: String) -> bool:
	if kind in ["world_cut", "domain_slash", "domain_void"]: return true
	var user = of(source)
	return user != null and (user.adapted("infinity") or user.enabled("amplification"))

static func damage(target: Object, amount: float, kind: String, source: Thing) -> float:
	var barrier = field(target, "infinity")
	var attacker = of(source)
	if barrier != null and not bypasses(source, kind):
		if attacker != null: attacker.observe("infinity")
		barrier.feedback("infinity", Color("a3eaff"))
		return 0.0
	if kind in ["domain_slash", "domain_void"]:
		var defense = field(target, "simple_domain")
		if defense != null:
			defense.feedback("simple_domain", Color("f5dda1"))
			return amount * 0.15
	var defender = field(target, "adaptation")
	if defender != null:
		var factor: float = defender.resistance(kind)
		defender.observe(kind)
		return amount * factor
	return amount

static func force(target: Node3D, source: Thing) -> float:
	if field(target, "infinity") != null and not bypasses(source, "gravity"): return 0.0
	var defender = field(target, "adaptation")
	if defender != null:
		var factor: float = defender.resistance("gravity")
		defender.observe("gravity")
		return factor
	return 1.0

static func candidates(tree: SceneTree) -> Array:
	var out := tree.get_nodes_in_group(Combat.COMBATANTS_GROUP)
	if Forge.world != null: out.append_array(Forge.world.get_node("Things").get_children())
	return out

extends Node3D

var thing: Thing
var powers := {}
var exposure := {}
var observed_at := {}
var analysis_due := {}
var clock := 0.0
var tick_left := 0.0
var next_attack := 0.0
var next_cast := 0.0
var last_cast_key := ""
var last_cast_cooldown := 0.0
var fx_left := 0.0
var domain_until := 0.0
var domain_mode := ""
var domain_origin := Vector3.ZERO
var domain_up := Vector3.UP
var domain_clashing := false
var domain_visual: Node3D
var domain_members: Array[WeakRef] = []
var domain_next_pulse := 0.0
var wheel_angle := 0.0
var void_scan_cursor := 0
var jobs: Node
var terrain_jobs: Node
var wheel: Node3D
var outline: Node3D
var pending_attack := {}
var zone_until := 0.0
var black_flashes := 0
var domain_peer: WeakRef
var domain_caster: WeakRef
var domain_start_health := 1.0
var clash_elapsed := 0.0
var clash_pressure := 0.0
var clash_last_clock := 0.0
var clash_point := Vector3.ZERO
var clash_axis := Vector3.RIGHT
var domain_outcome := ""
var rival_ref: WeakRef
var rival_scan_frame := -100
var character_domain_ready := .8
var character_cast_index := 0
var last_character_technique := ""

func preferred_rival() -> Thing:
	if not is_instance_valid(thing) or thing._def.get("jj_character", "") == "" or not thing.is_active or thing.is_dead or thing.is_captured or thing.is_held or thing.is_building: return null
	if not InnovationRules.target_diet(thing).is_empty(): return null
	var orders := thing.get_node_or_null("AnimalOrders")
	# Deliberate follow/stay/target orders take precedence over the natural rivalry.
	if orders != null and orders.mode not in ["free", "aggressive"]: return null
	var saved = rival_ref.get_ref() if rival_ref != null else null
	var frame := Engine.get_physics_frames()
	if frame - rival_scan_frame < 15 and (saved == null or _rival_available(saved)): return saved
	rival_scan_frame = frame
	var best: Thing
	var distance := INF
	for user in get_tree().get_nodes_in_group("jujutsu_users"):
		var candidate: Thing = user.thing
		if not _rival_available(candidate): continue
		var current := center().distance_squared_to(candidate.center())
		if current < distance: best = candidate; distance = current
	rival_ref = weakref(best) if best != null else null
	return best

func _rival_available(candidate: Object) -> bool:
	return is_instance_valid(candidate) and candidate is Thing and not candidate.is_queued_for_deletion() and candidate.is_active and not candidate.is_dead and not candidate.is_captured and not candidate.is_held and not candidate.is_building and JujutsuRules.character_rivals(thing, candidate)

func setup(owner_thing: Thing, settings: Dictionary) -> void:
	thing = owner_thing
	powers = settings
	process_physics_priority = -25

func _ready() -> void:
	add_to_group("jujutsu_users")
	if powers.has("infinity") or powers.has("simple_domain") or powers.has("amplification") or thing._def.get("jj_character", "") == "sukuna":
		outline = Node3D.new()
		add_child(outline)
		var cube := BoxMesh.new()
		cube.size = Vector3(.10, .10, .10)
		var mat := StandardMaterial3D.new()
		mat.albedo_color = Color("9ce9f1") if powers.has("infinity") else Color("f8d694")
		mat.emission_enabled = true
		mat.emission = mat.albedo_color
		for i in 24:
			var bit := MeshInstance3D.new()
			bit.mesh = cube
			bit.material_override = mat
			var angle := TAU * (i % 12) / 12.0
			bit.position = Vector3(cos(angle), .2 if i < 12 else -.6, sin(angle)) * 2.5
			outline.add_child(bit)
	if powers.has("adaptation"):
		wheel = Node3D.new()
		wheel.name = "AdaptationWheel"
		add_child(wheel)
		var radius := thing.scale_factor if thing.thing_id == "mahoraga" else clampf(thing.bounds.size.x * .55, .38, .85)
		var mesh := BoxMesh.new()
		var instances := MultiMesh.new()
		instances.transform_format = MultiMesh.TRANSFORM_3D
		instances.mesh = mesh
		instances.instance_count = 40
		var mat := StandardMaterial3D.new()
		mat.albedo_color = Color("f5d98d")
		mat.emission_enabled = true
		mat.emission = mat.albedo_color
		for i in 24:
			var angle := i * TAU / 24.0
			instances.set_instance_transform(i, _wheel_frame(angle, Vector3(.09, .10, radius * .29), radius))
		for i in 8:
			var angle := i * TAU / 8.0
			for tip in [false, true]:
				var size := Vector3(.19, .19, .19) if tip else Vector3(radius * 1.12, .08, .08)
				instances.set_instance_transform(24 + i * 2 + int(tip), _wheel_frame(angle, size, radius * (1.18 if tip else .58)))
		var drawing := MultiMeshInstance3D.new()
		drawing.name = "EightSpokedWheel"
		drawing.multimesh = instances
		drawing.material_override = mat
		drawing.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		wheel.add_child(drawing)
		wheel.position = thing.bounds.get_center() + Vector3.UP * (thing.bounds.size.y * .5 + .45)

func _wheel_frame(angle: float, size: Vector3, radius: float) -> Transform3D:
	var turn := Basis(Vector3.UP, -angle) * Basis.IDENTITY.scaled(size)
	return Transform3D(turn, Vector3(cos(angle), 0, sin(angle)) * radius)

func fighter_identity() -> String:
	var identity := String(thing._def.get("jj_character",thing._def.get("personal_power",{}).get("donor","")))
	if identity in ["gojo","sukuna"]:return identity
	for donor in load("res://scripts/things/fusion_rules.gd").donors(thing.node_data,Lexicon.data):
		if donor in ["gojo","sukuna"]:return donor
	return ""

func gojo_profile() -> bool:return fighter_identity()=="gojo"
func fighter_profile() -> bool:return fighter_identity() in ["gojo","sukuna"]
func fighter_damage() -> float:return .78 if gojo_profile() else 1.0
func domain_duration() -> float:return 5.0 if fighter_profile() else 6.0

func cooldown_for(key: String) -> float:
	if key in ["void","shrine"]: return 28.0 if fighter_profile() else 18.0
	if key in ["blue","red","purple"]: return (10.0 if key=="purple" else 5.0) if gojo_profile() else (7.0 if key=="purple" else 4.0)
	if key in ["ryu_beam","yuta_beam"]: return 7.0
	if fighter_identity()=="sukuna": return 8.0 if key=="world_cut" else 12.0 if key=="fuga" else 3.0
	return 4.5 if key=="world_cut" else 8.0 if key=="fuga" else 1.2 if key=="cleave" else .8

func remember_cooldown(key: String) -> void:
	last_cast_key=key
	last_cast_cooldown=maxf(0.0,next_cast-clock)


func enabled(key: String) -> bool:
	var personal := thing.get_node_or_null("PersonalPowers") if is_instance_valid(thing) else null
	if personal != null and not personal.equipped(): return false
	if not is_instance_valid(thing) or thing.is_dead or thing.is_building or not thing.is_active: return false
	if key=="amplification" and thing._def.get("jj_character", "")=="sukuna":
		# Drop amplification to answer an enemy domain instead of losing the native clash.
		var rival:=preferred_rival()
		var other=rival.get_node_or_null("Jujutsu") if rival!=null else null
		if domain_until>clock or (other!=null and other.domain_until>other.clock):return false
		return fmod(clock,24.0)<8.0
	if not powers.get(key, false): return false
	if key == "infinity" and powers.has("amplification") and fmod(clock, 24.0) < 16.0: return false
	# Protective techniques cycle, leaving a visible window to counterattack.
	if key == "infinity" and gojo_profile(): return fmod(clock, 24.0) < 8.0
	if key in ["infinity", "simple_domain", "amplification"]: return fmod(clock, 24.0) < 16.0
	return true

func protects(target: Object) -> bool:
	return target == thing or (thing.is_held and target == thing.owner_player)

func center() -> Vector3:
	return Combat.center_of(thing.owner_player) if thing.is_held and is_instance_valid(thing.owner_player) else thing.center()

func adapted(kind: String) -> bool:
	return enabled("adaptation") and int(exposure.get(adaptation_kind(kind), 0)) >= 4

func adaptation_kind(kind: String) -> String:
	return "fire" if kind == "burn" else kind

func resistance(kind: String) -> float:
	if not enabled("adaptation"): return 1.0
	var stage := clampi(int(exposure.get(adaptation_kind(kind), 0)), 0, 4)
	return [1.0, .65, .35, .12, .03][stage]

func observe(kind: String) -> void:
	kind = adaptation_kind(kind)
	if kind.is_empty() or not enabled("adaptation") or thing.is_captured or not thing.has_simulation_authority(): return
	if int(exposure.get(kind, 0)) >= 4 or clock - float(observed_at.get(kind, -100.0)) < 1.5: return
	observed_at[kind] = clock
	exposure[kind] = mini(int(exposure.get(kind, 0)) + 1, 4)
	analysis_due[kind] = clock + (4.0 if kind in ["infinity", "domain_void", "spatial", "world_cut"] else 2.5)
	feedback("adaptation", Color("f9d881"))

func _continue_adaptation() -> void:
	# Understanding continues after surviving first contact; captivity pauses its clock.
	if not enabled("adaptation") or thing.is_captured or thing.hp <= 0.0: return
	var advanced := 0
	for kind: String in analysis_due.keys():
		if int(exposure.get(kind, 0)) >= 4:
			analysis_due.erase(kind)
			continue
		if clock < float(analysis_due[kind]): continue
		observe(kind)
		advanced += 1
	# One bounded recovery per analysis tick; never heals before a lethal blow lands.
	if advanced > 0 and thing.thing_id == "mahoraga":
		thing.hp = minf(thing.max_hp, thing.hp + thing.max_hp * .05)

func feedback(kind: String, color: Color, radius: float = 1.5) -> void:
	if fx_left > 0.0: return
	fx_left = .35
	ExpansionFx.burst(Forge.fx_root(thing), center(), radius, color, kind)

func _process(delta: float) -> void:
	if not is_instance_valid(thing): return
	if powers.has("black_flash") and thing.is_held and thing.owner_player is Player:
		var hands = thing.owner_player.hands
		var level: float = hands.charge_level()
		var precise: bool = hands.is_charging() and level >= (.35 if zone_until > clock else .45) and level <= .65
		for piece in thing.model_pieces:
			if piece.get_meta("tag", "") != "knuckle": continue
			var material := piece.material_override as StandardMaterial3D
			if material != null:
				material.emission_enabled = precise
				material.emission = Color("ef2646")
				material.emission_energy_multiplier = 2.0
	if thing.network_replica: clock += delta
	if domain_until > clock and thing.is_active and not thing.is_dead and not thing.is_captured:
		if not is_instance_valid(domain_visual):
			domain_visual = load("res://scripts/fx/domain_environment.gd").new()
			Forge.fx_root(thing).add_child(domain_visual)
			domain_visual.setup(self)
	if outline != null:
		outline.visible = enabled("infinity") or enabled("simple_domain") or enabled("amplification")
		outline.global_position = center()
		outline.rotate_y(delta * .5)
	if wheel != null:
		var turns := 0
		for value in exposure.values(): turns += int(value)
		wheel_angle = lerpf(wheel_angle, turns * PI * .25, 1.0 - exp(-8.0 * delta))
		# Spatial parenting keeps movement, gravity and capture visibility on the body.
		var above := thing.bounds.get_center() + Vector3.UP * (thing.bounds.size.y * .5 + .45)
		wheel.position = above
		wheel.rotation.y = wheel_angle
		wheel.visible = thing.visible and not thing.is_captured

func _physics_process(delta: float) -> void:
	if not is_instance_valid(thing) or thing.is_dead or thing.is_building or not thing.is_active or not thing.has_simulation_authority(): return
	if thing.is_captured: return
	clock += delta
	_continue_adaptation()
	var personal := thing.get_node_or_null("PersonalPowers")
	if personal != null and not personal.equipped():
		cancel_pending()
		if domain_until > clock: cancel_domain("lost")
		return
	if not pending_attack.is_empty() and clock >= float(pending_attack.at): _resolve_attack()
	fx_left -= delta
	tick_left -= delta
	if tick_left > 0.0: return
	tick_left = .15
	if enabled("infinity"): _infinity()
	if domain_until > clock: _domain()
	if enabled("reverse") and clock >= next_attack:
		next_attack = clock + 1.5
		_heal()
	if thing._def.get("jj_character", "") != "" and thing.can_act() and not thing.get_meta("ridden",false):
		var opponent := Combat.nearest_target(thing, center(), get_tree())
		if opponent != null and domain_until <= clock and clock >= character_domain_ready:
			var other = JujutsuRules.of(opponent) if opponent is Thing else null
			var counter: bool = other != null and other.domain_until > other.clock
			var range_m := 16.0 if counter else 12.0
			if center().distance_to(Combat.center_of(opponent)) < range_m: expand_domain()
	if thing.category == "creature" and not thing.get_meta("ridden",false) and thing.get_node_or_null("CoopBoss") == null and thing.can_act() and clock >= next_cast:
		var target := Combat.nearest_target(thing, center(), get_tree())
		if target != null and center().distance_to(Combat.center_of(target)) < 24.0:
			cast(ActionContext.make(center(), Combat.center_of(target) - center(), target))

func _infinity() -> void:
	for target in JujutsuRules.candidates(get_tree()):
		if not is_instance_valid(target) or not target is Thing or target == thing or target.is_dead or target.is_held or not Combat.affects(thing, target): continue
		var offset: Vector3 = target.center() - center()
		if offset.length() > 2.6 or JujutsuRules.bypasses(target, "contact"): continue
		var attacker = JujutsuRules.of(target)
		if attacker != null: attacker.observe("infinity")
		# Move the incoming body back outside the boundary; no growing collision meshes.
		if offset.length_squared() > .001:
			target.global_position += offset.normalized() * minf(2.6 - offset.length(), .4)
			target.velocity = Vector3.ZERO
		feedback("infinity", Color("b2e9ff"))

func _heal() -> void:
	if not enabled("reverse") or thing.is_captured or not thing.has_simulation_authority(): return
	var target: Node3D = thing.owner_player if thing.is_held and is_instance_valid(thing.owner_player) else thing
	if target is Thing:
		if target.is_dead or target.hp <= 0.0 or target.hp >= target.max_hp: return
		target.hp = minf(target.max_hp, target.hp + (4.0 if fighter_profile() else 6.0))
	elif target is Player:
		if not target.is_alive() or target.health >= target.max_health: return
		target.health = minf(target.max_health, target.health + (4.0 if fighter_profile() else 6.0))
		target.health_changed.emit(target.health, target.max_health)
	feedback("reverse", Color("a4ffbf"))

func expand_domain() -> bool:
	var character: bool = thing._def.get("jj_character", "") != ""
	if not thing.can_act() or enabled("amplification") or domain_until > clock: return false
	if (character and clock < character_domain_ready) or (not character and clock < next_cast): return false
	if not powers.has("shrine") and not powers.has("void"): return false
	domain_mode = "shrine" if powers.has("shrine") else "void"
	domain_peer = null
	domain_outcome = ""
	clash_elapsed = 0.0
	clash_pressure = 0.0
	domain_caster = weakref(thing.owner_player if thing.is_held and is_instance_valid(thing.owner_player) else thing)
	domain_start_health = load("res://scripts/things/domain_clash.gd").health(self)
	domain_until = clock + domain_duration()
	domain_origin = center()
	domain_up = thing.up()
	if domain_mode in ["void", "shrine"]:
		# Center a nearby duel inside the sphere; never teleport a distant opponent into it.
		var best := 16.0
		var preferred := preferred_rival()
		for target in get_tree().get_nodes_in_group(Combat.COMBATANTS_GROUP):
			if preferred != null and target != preferred: continue
			if not _enemy(target) or (target.has_method("is_alive") and not target.is_alive()): continue
			var distance := center().distance_to(Combat.center_of(target))
			if distance < best:
				best = distance
				domain_origin = (center() + Combat.center_of(target)) * .5
	void_scan_cursor = 0
	domain_clashing = false
	domain_next_pulse = clock + .65
	domain_members.clear()
	if domain_mode in ["void", "shrine"]:
		var candidates := JujutsuRules.candidates(get_tree())
		if is_instance_valid(thing.owner_player) and thing.is_held: candidates.append(thing.owner_player)
		for member in candidates:
			if not is_instance_valid(member) or not member is Node3D: continue
			if member is Thing and (member.is_dead or member.is_captured or member.is_held): continue
			if not member.has_method("take_damage"): continue
			if Combat.center_of(member).distance_to(domain_origin) < 8.5: domain_members.append(weakref(member))
	if character:
		character_domain_ready = clock + (32.0 if fighter_profile() else 24.0)
		next_cast = maxf(next_cast, clock + .8)
	else: next_cast = clock + cooldown_for(domain_mode)
	remember_cooldown(domain_mode)
	load("res://scripts/things/domain_clash.gd").update(self)
	DomainCallout.announce(Forge.fx_root(thing), center(), domain_mode)
	feedback(domain_mode, Color("ef6e7d") if domain_mode == "shrine" else Color("7489ff"))
	return true

func cancel_domain(outcome: String = "") -> void:
	if domain_until > clock and not outcome.is_empty():
		ExpansionFx.burst(Forge.fx_root(thing), domain_origin, 8.5, Color("d3bedf"), "domain_break")
	domain_outcome = outcome
	domain_until = 0.0
	domain_clashing = false
	domain_peer = null
	domain_members.clear()
	if is_instance_valid(domain_visual): domain_visual.close()

func _exit_tree() -> void:
	if is_instance_valid(domain_visual): domain_visual.close()

func cast(ctx: ActionContext) -> void:
	if clock < next_cast or not pending_attack.is_empty() or not thing.can_act() or thing.is_captured: return
	var origin := center()
	var direction := ctx.direction
	if thing.is_held and thing.owner_player is Player:
		origin = thing.owner_player.head.global_position
		direction = -thing.owner_player.camera.global_basis.z
	if enabled("amplification"): return # Neutralizing aura cannot cast other techniques simultaneously.
	if thing._def.get("jj_character", "") != "":
		_character_cast(ctx, origin, direction.normalized())
		return
	for key in ["purple", "red", "blue"]:
		if powers.has(key):
			var id := "hollow_purple" if key == "purple" else "reversal_red" if key == "red" else "cursed_blue"
			var shot := Forge.spawn_child(Recipe.new_node(id), "projectile", origin + direction * 1.5, direction, thing, 20.0 if key == "purple" else 12.0, Vector3.ZERO, true)
			if shot != null:
				if fighter_profile(): shot.power *= fighter_damage()
				next_cast = clock + cooldown_for(key)
				remember_cooldown(key)
			return
	for key in ["ryu_beam", "yuta_beam"]:
		if powers.has(key):
			if get_tree().get_nodes_in_group("cursed_beams").size() >= 24: return
			var beam := Forge.spawn_child(Recipe.new_node(key + "_stream"), "projectile", origin + direction.normalized() * 1.1, direction, thing, 0.0, Vector3.ZERO, true)
			if beam != null:
				beam.power = clampf(thing.power, .5, 2.0)
				next_cast = clock + cooldown_for(key)
				remember_cooldown(key)
			return
	if powers.has("shrine") or powers.has("void"):
		expand_domain()
		return
	var mode := "world_cut" if powers.has("world_cut") else "cleave" if powers.has("cleave") else "contact_cleave" if powers.has("contact_cleave") else "fuga" if powers.has("fuga") else "black_flash" if powers.has("black_flash") else "adaptation"
	if mode == "adaptation" and not powers.has("adaptation"): return
	var delay := .55 if mode == "world_cut" else .45 if mode == "fuga" else .12
	pending_attack = {"mode": mode, "at": clock + delay, "origin": origin, "direction": direction.normalized(), "held": thing.is_held, "charge": ctx.charge}
	next_cast = clock + cooldown_for(mode)
	remember_cooldown(mode)
	var fx = load("res://scripts/fx/jujutsu_impact.gd")
	if mode in ["world_cut", "fuga"]: fx.play(Forge.fx_root(thing), origin + direction * .8, direction, "world_charge" if mode == "world_cut" else "fuga_charge")

func _character_cast(ctx: ActionContext, origin: Vector3, direction: Vector3) -> void:
	if domain_clashing: return
	var identity := String(thing._def.jj_character)
	var sequence := ["blue", "red", "purple", "black_flash"] if identity == "gojo" else ["cleave", "contact_cleave", "world_cut", "fuga"]
	var mode: String = sequence[character_cast_index % sequence.size()]
	var target := Combat.nearest_target(thing, origin, get_tree())
	var distance := origin.distance_to(Combat.center_of(target)) if target != null else INF
	# Use contact techniques only at punching distance; keep ranged variety otherwise.
	if mode in ["black_flash", "contact_cleave"] and distance > 3.2: mode = "blue" if identity == "gojo" else "cleave"
	if mode in ["blue", "red", "purple"]:
		if get_tree().get_nodes_in_group("spatial_orbs").size() >= 24: return
		var id := "hollow_purple" if mode == "purple" else "reversal_red" if mode == "red" else "cursed_blue"
		var shot := Forge.spawn_child(Recipe.new_node(id), "projectile", origin + direction * 1.5, direction, thing, 20.0 if mode == "purple" else 12.0, Vector3.ZERO, true)
		if shot == null: next_cast = clock + .5; return
		shot.power *= fighter_damage()
		next_cast = clock + (10.0 if mode == "purple" else 5.0)
	else:
		var delay := .55 if mode == "world_cut" else .45 if mode == "fuga" else .12
		pending_attack = {"mode": mode, "at": clock + delay, "origin": origin, "direction": direction, "held": thing.is_held, "charge": ctx.charge}
		next_cast = clock + (8.0 if mode == "world_cut" else 12.0 if mode == "fuga" else 3.0)
		if mode in ["world_cut", "fuga"]:
			load("res://scripts/fx/jujutsu_impact.gd").play(Forge.fx_root(thing), origin + direction * .8, direction, "world_charge" if mode == "world_cut" else "fuga_charge")
	last_character_technique = mode
	character_cast_index += 1

func cancel_pending() -> void: pending_attack.clear()

func _resolve_attack() -> void:
	var attack := pending_attack.duplicate()
	pending_attack.clear()
	if not thing.can_act() or thing.is_captured or bool(attack.held) != thing.is_held or enabled("amplification"): return
	var origin: Vector3 = center()
	var direction: Vector3 = attack.direction
	if thing.is_held and thing.owner_player is Player:
		origin = thing.owner_player.head.global_position
		direction = -thing.owner_player.camera.global_basis.z
	var mode := String(attack.mode)
	if thing._def.get("jj_character", "")=="sukuna" and not thing.is_held:
		var rival:=Combat.nearest_target(thing,origin,get_tree())
		if rival!=null:direction=(Combat.center_of(rival)-origin).normalized()
	thing.set_meta("last_copyable_skill",{"kind":"jujutsu","key":mode,"damage_kind":mode,"recorded_at":Time.get_ticks_msec()})
	if mode in ["cleave", "fuga"]:
		if get_tree().get_nodes_in_group("cursed_projectiles").size() >= 48: return
		var id := "sukuna_fire_arrow" if mode == "fuga" else "sukuna_dismantle_wave"
		var shot := Forge.spawn_child(Recipe.new_node(id), "projectile", origin + direction * .7, direction, thing, -1.0, Vector3.ZERO, true)
		if shot != null: shot.power = clampf(thing.power, .5, 2.0) * fighter_damage()
		return
	if mode == "world_cut":
		ExpansionFx.rift(Forge.fx_root(thing), origin, direction, 24.0, Color("d4dcf1"))
		var hits := 0
		for target in JujutsuRules.candidates(get_tree()):
			if not _enemy(target): continue
			var offset: Vector3 = Combat.center_of(target) - origin
			var along := offset.dot(direction)
			var radius: float = minf(2.0, target.bounds.size.length() * .25) if target is Thing else .6
			if along < 0 or along > 24.0 or (offset - direction * along).length() > 1.1 + radius: continue
			_queue(target, 100.0 * fighter_damage(), "world_cut")
			hits += 1
			if hits >= 16: break
		_cut(origin, origin + direction * 24.0, 1.0, -1.0)
		return
	_melee(mode, origin, direction, float(attack.charge))

func _melee(mode: String, origin: Vector3, direction: Vector3, charge: float) -> void:
	var reach := clampf(thing.bounds.size.length() * .3 + 1.0, 2.0, 3.2) if not thing.is_held else 2.2
	if mode == "adaptation": reach = maxf(reach, 3.2)
	var best := INF
	var chosen: Node3D
	var chosen_contact:=Vector3.ZERO
	for target in JujutsuRules.candidates(get_tree()):
		if not _enemy(target): continue
		var at := Combat.center_of(target)
		var offset := at - origin
		if offset.normalized().dot(direction) < .55: continue
		var contact := at
		if target is Thing:
			var bounds: AABB = target.global_transform * target.bounds
			contact = origin.clamp(bounds.position, bounds.end)
		var distance := origin.distance_to(contact)
		if distance > reach or distance >= best: continue
		var query := PhysicsRayQueryParameters3D.create(origin, at, PhysicsLayers.WORLD)
		if not thing.get_world_3d().direct_space_state.intersect_ray(query).is_empty(): continue
		chosen = target
		chosen_contact=contact
		best = distance
	if chosen == null: return # No ranged lightning and no Black Flash on a missed punch.
	var critical := false
	if mode == "black_flash":
		critical = randf() < (.45 if zone_until > clock else .25) if thing.category == "creature" else charge >= (.35 if zone_until > clock else .45) and charge <= .65
	var amount := 45.0 if critical else 18.0 if mode == "black_flash" else maxf(14.0, thing.impact_damage * 2.0)
	if mode == "contact_cleave":
		var health: float = chosen.max_hp if chosen is Thing else chosen.max_health
		amount = clampf(32.0 + health * .12, 32.0, 70.0)
	var before: float = chosen.hp if chosen is Thing else chosen.health
	thing.set_meta("last_copyable_skill",{"kind":"jujutsu","key":mode,"damage_kind":"slash" if mode=="contact_cleave" else "melee","recorded_at":Time.get_ticks_msec()})
	Combat.apply_damage(chosen, amount * clampf(thing.power, .5, 2.0) * fighter_damage(), "slash" if mode == "contact_cleave" else "melee", thing)
	if not is_instance_valid(chosen): return
	var after: float = chosen.hp if chosen is Thing else chosen.health
	if after >= before: return
	var fx = load("res://scripts/fx/jujutsu_impact.gd")
	fx.play(Forge.fx_root(thing), chosen_contact, direction, "black_flash" if critical else "cleave" if mode == "contact_cleave" else "punch")
	if critical:
		black_flashes += 1
		zone_until = clock + 6.0
	if chosen.has_method("apply_knockback"): chosen.apply_knockback(direction * (5.0 if critical else 2.0))
	elif chosen is Thing: chosen.nudge(direction * (5.0 if critical else 2.0))

func _enemy(target: Object) -> bool:
	if not is_instance_valid(target) or target == thing or target == thing.owner_player or not target.has_method("take_damage"): return false
	if target is Thing and (target.is_dead or target.is_captured or target.is_held): return false
	return Combat.affects(thing, target)

func _domain_target(target: Object) -> bool:
	var preferred := preferred_rival()
	if preferred != null: return target == preferred
	# Area domains also affect the caster's creatures, but never the caster itself.
	if target is Thing and is_instance_valid(target) and target != thing and target.category == "creature":
		return not target.is_dead and not target.is_captured and not target.is_held
	return _enemy(target)

func _queue(target: Node3D, amount: float, kind: String) -> void:
	if not is_instance_valid(jobs) or jobs.is_queued_for_deletion():
		jobs = load("res://scripts/things/blast_work.gd").new()
		jobs.setup(thing, [])
		get_tree().root.add_child(jobs)
	jobs.rows.append({"target": weakref(target), "damage": amount, "push": Vector3.ZERO, "type": kind})

func _domain() -> void:
	load("res://scripts/things/domain_clash.gd").update(self)
	if domain_until <= clock: return
	if clock < domain_until - domain_duration() + .65: return # The barrier forms before sure-hit begins.
	if domain_mode in ["void", "shrine"]:
		for reference in domain_members:
			var member = reference.get_ref()
			if not is_instance_valid(member) or (member is Thing and (member.is_dead or member.is_captured)): continue
			if member.has_method("is_alive") and not member.is_alive(): continue
			var offset: Vector3 = Combat.center_of(member) - domain_origin
			if offset.length() > 8.4:
				member.global_position -= offset.normalized() * (offset.length() - 8.4)
		if domain_mode == "void":
			_void_paralysis()
			return
	if clock < domain_next_pulse: return
	domain_next_pulse = clock + .75
	var applied := 0
	var candidates := JujutsuRules.candidates(get_tree())
	if candidates.is_empty(): return
	var scanned := 0
	for step in candidates.size():
		var target = candidates[(void_scan_cursor + step) % candidates.size()]
		scanned += 1
		if not _domain_target(target) or domain_origin.distance_to(Combat.center_of(target)) > 9.0: continue
		if domain_clashing and load("res://scripts/things/domain_clash.gd").contested(self, Combat.center_of(target)): continue
		if domain_mode == "shrine": _queue(target, 9.0, "domain_slash")
		applied += 1
		if applied >= 16: break
	void_scan_cursor = (void_scan_cursor + scanned) % candidates.size()
	if domain_mode == "shrine" and not (domain_clashing and load("res://scripts/things/domain_clash.gd").contested(self, domain_origin)):
		_cut(domain_origin, domain_origin, 2.5, 35.0)

func void_affects(target: Node3D) -> bool:
	if not is_instance_valid(thing) or thing.is_dead or thing.is_captured or not thing.is_active or domain_mode != "void" or domain_until <= clock: return false
	if domain_clashing and load("res://scripts/things/domain_clash.gd").contested(self, Combat.center_of(target)): return false
	if clock < domain_until - domain_duration() + .65 or not _domain_target(target) or domain_origin.distance_to(Combat.center_of(target)) > 9.0: return false
	if JujutsuRules.field(target, "simple_domain") != null: return false
	var adaptation = JujutsuRules.field(target, "adaptation")
	return adaptation == null or not adaptation.adapted("domain_void")

func _void_lock(target: Node3D) -> void:
	if not void_affects(target): return
	var adaptation = JujutsuRules.field(target, "adaptation")
	if adaptation != null:
		adaptation.observe("domain_void")
		if adaptation.adapted("domain_void"): return
	Status.apply_void(target, thing)

func _void_paralysis() -> void:
	# Players are always processed first; crowds are admitted in bounded batches.
	for target in get_tree().get_nodes_in_group(Combat.COMBATANTS_GROUP):
		if is_instance_valid(target): _void_lock(target)
	if Forge.world == null: return
	var creatures := Forge.world.get_node("Things").get_children()
	if creatures.is_empty(): return
	for step in mini(16, creatures.size()):
		var target = creatures[(void_scan_cursor + step) % creatures.size()]
		if is_instance_valid(target) and target is Thing and target.category in ["creature", "vehicle"]: _void_lock(target)
	void_scan_cursor = (void_scan_cursor + 16) % creatures.size()

func _cut(from: Vector3, to: Vector3, radius: float, amount: float) -> void:
	if not is_instance_valid(terrain_jobs) or terrain_jobs.is_queued_for_deletion():
		terrain_jobs = load("res://scripts/things/spatial_cut_work.gd").new()
		terrain_jobs.setup(thing)
		get_tree().root.add_child(terrain_jobs)
	terrain_jobs.add_segment(from, to, radius, amount)

extends Node3D

var thing: Thing
var config := {}
var remaining := 1.0
var scan_left := 0.0
var casts := 0

func setup(body: Thing, settings: Dictionary) -> void:
	thing = body
	config = settings

func combat_allowed() -> bool:
	if not thing.is_active or thing.is_dead or thing.is_building or thing.is_captured or thing.is_held or not thing.can_act(): return false
	var orders = thing.get_node_or_null("AnimalOrders")
	if orders != null and orders.active(): return orders.combat_target() != null
	return true

func _physics_process(delta: float) -> void:
	if not thing.has_simulation_authority() or thing.is_captured: return
	remaining = maxf(0.0, remaining - delta)
	scan_left -= delta
	if remaining > 0.0 or scan_left > 0.0 or thing.get_meta("ridden",false) or not combat_allowed(): return
	scan_left = .25
	var target := Combat.nearest_target(thing, thing.center(), get_tree())
	if target == null: return
	cast_at(target)

func mouth(index: int = 0) -> Vector3:
	var muzzles: Array = config.muzzles
	return thing.global_transform * (ModelBuilder._vec(muzzles[clampi(index,0,muzzles.size()-1)]) * thing.scale_factor)

func cast_at(target: Node3D) -> bool:
	if not thing.has_simulation_authority() or not combat_allowed() or remaining > 0.0 or not is_instance_valid(target) or not Combat.affects(thing,target): return false
	if target is Thing and (target.is_dead or target.is_captured or target.is_held): return false
	var at := Combat.center_of(target)
	var origin := mouth()
	var contact := at
	if target is Thing:
		var box: AABB = target.global_transform * target.bounds
		contact = origin.clamp(box.position,box.end)
	if origin.distance_to(contact) > float(config.range) * thing.scale_factor: return false
	var ray := PhysicsRayQueryParameters3D.create(origin, contact, PhysicsLayers.WORLD, [thing.get_rid()])
	if not thing.get_world_3d().direct_space_state.intersect_ray(ray).is_empty(): return false
	if config.attack == "smash":
		# A real contact strike, never a remote map-wide earthquake.
		var victims: Array = [target]
		for other in Combat.in_radius(thing,contact,8.0):
			if other not in victims and Combat.affects(thing,other): victims.append(other)
		for victim in victims.slice(0,8): Combat.apply_damage(victim,180.0*clampf(thing.power,.5,2.0),"kaiju_melee",thing)
		Fx.explosion(Forge.fx_root(thing),contact,8.0,Color("bc976e"))
		if Session.is_online(): Session.creations.notify_fx("explosion",[contact,8.0,Color("bc976e")])
		Combat._crater(thing,contact,4.0,180.0)
		load("res://scripts/fx/jujutsu_impact.gd").play(Forge.fx_root(thing),contact,(contact-origin).normalized(),"punch")
	else:
		var sockets: Array = config.muzzles
		if get_tree().get_nodes_in_group("cursed_beams").size() + sockets.size() > 24: return false
		var made := 0
		for index in sockets.size():
			var node := Recipe.new_node("kaiju_" + String(config.attack) + "_beam")
			node.mods["kaiju_muzzle"] = index
			var from := mouth(index)
			var beam := Forge.spawn_child(node,"projectile",from,(at-from).normalized(),thing,0.0,Vector3.ZERO,true)
			if beam != null:
				beam.power = clampf(thing.power,.5,2.0)
				made += 1
		if made == 0: return false
	remaining = float(config.cooldown)
	casts += 1
	return true

func snapshot() -> Dictionary: return {"remaining":remaining,"casts":casts}
func apply_snapshot(state: Dictionary) -> void:
	remaining = maxf(0.0,float(state.get("remaining",0)))
	casts = maxi(0,int(state.get("casts",0)))

extends RefCounted

# Adapt the Lab silhouettes to the upstream CreatureAnimator without replacing their art.
static func build(original: Array, aerial: bool) -> Dictionary:
 var pieces: Array = original.duplicate(true)
 for piece: Dictionary in pieces: piece.erase("bone")
 var full := ModelBuilder._piece_box(pieces[0])
 for piece: Dictionary in pieces: full=full.merge(ModelBuilder._piece_box(piece))
 var center:=full.get_center()
 var joints: Dictionary={"body":{"pivot":[center.x,center.y,center.z],"parent":""}}
 var legs: Array=[]
 for piece: Dictionary in pieces:
  var tag=String(piece.get("tag",""))
  if not tag.begins_with("leg"):continue
  var point=ModelBuilder._vec(piece.get("pos",[0,0,0]))
  var side=-1 if point.x<center.x else 1
  var group: Dictionary={}
  for candidate: Dictionary in legs:
   if candidate.side==side and absf(float(candidate.z)-point.z)<maxf(.035,full.size.z*.055):group=candidate;break
  if group.is_empty():
   group={"side":side,"z":point.z,"pieces":[],"box":ModelBuilder._piece_box(piece)}
   legs.append(group)
  group.pieces.append(piece)
  group.box=group.box.merge(ModelBuilder._piece_box(piece))
 var kind="flier" if aerial else "biped" if legs.size()==2 else "quadruped" if legs.size()==4 else "arthropod" if legs.size()>0 else "generic"
 legs.sort_custom(func(a,b):return a.z<b.z)
 var serial={-1:0,1:0}
 for index in legs.size():
  var group: Dictionary=legs[index]
  var box: AABB=group.box
  var foot=Vector3(box.get_center().x,box.position.y,box.get_center().z)
  var hip=Vector3(foot.x,box.end.y,foot.z)
  var knee=hip.lerp(foot,.5)
  var side="l" if group.side<0 else "r"
  var suffix=side
  if kind=="quadruped":
   suffix=("f" if serial[group.side]==0 else "h")+side;serial[group.side]+=1
  elif legs.size()!=2:
   suffix=side+"_"+str(serial[group.side]);serial[group.side]+=1
  group.hip="hip_"+suffix;group.knee="knee_"+suffix
  var phase=float(index%2)*.5
  if kind=="quadruped":phase=.5 if suffix in ["fl","hr"] else 0.0
  joints[group.hip]={"pivot":[hip.x,hip.y,hip.z],"parent":"body","phase":phase,"foot":[foot.x,foot.y,foot.z]}
  joints[group.knee]={"pivot":[knee.x,knee.y,knee.z],"parent":group.hip,"foot":[foot.x,foot.y,foot.z]}
  # Single block legs become two linked blocks, preserving the rest silhouette.
  if group.pieces.size()==1:
   var piece: Dictionary=group.pieces[0]
   if String(piece.get("shape",""))=="box" and piece.get("rot",[0,0,0])==[0,0,0] and piece.has("size"):
    var lower=piece.duplicate(true)
    var size=ModelBuilder._vec(piece.size)
    var point=ModelBuilder._vec(piece.pos)
    piece.size=[size.x,size.y*.5,size.z];piece.pos=[point.x,point.y+size.y*.25,point.z];piece.bone=group.hip
    lower.size=[size.x,size.y*.5,size.z];lower.pos=[point.x,point.y-size.y*.25,point.z];lower.bone=group.knee
    pieces.append(lower)
  for piece: Dictionary in group.pieces:
   if not piece.has("bone"):piece.bone=group.hip if ModelBuilder._vec(piece.get("pos",[0,0,0])).y>=knee.y else group.knee
 # Head details share a pivot, so eyes, horns and mouth stay attached when looking around.
 var head_box:=AABB()
 var head_seen=false
 for piece: Dictionary in pieces:
  if ModelBuilder._anatomy_group(piece)=="head":
   head_box=head_box.merge(ModelBuilder._piece_box(piece)) if head_seen else ModelBuilder._piece_box(piece);head_seen=true
 if head_seen:
  var at=Vector3(head_box.get_center().x,head_box.position.y,head_box.get_center().z)
  joints.head={"pivot":[at.x,at.y,at.z],"parent":"body"}
 for piece: Dictionary in pieces:
  if piece.has("bone"):continue
  var tag=String(piece.get("tag",""))
  var point=ModelBuilder._vec(piece.get("pos",[0,0,0]))
  var group=ModelBuilder._anatomy_group(piece)
  if group=="head" and head_seen:piece.bone="head"
  elif group=="legs" and not legs.is_empty():
   var nearest: Dictionary=legs[0]
   for leg: Dictionary in legs:
    if (leg.box as AABB).get_center().distance_to(point)<(nearest.box as AABB).get_center().distance_to(point):nearest=leg
   piece.bone=nearest.knee
  elif group=="wings" or tag=="arm":
   var side="l" if point.x<center.x else "r"
   var bone=("wing_" if group=="wings" else "arm_")+side
   if not joints.has(bone):
    var at=Vector3(center.x+(-1 if side=="l" else 1)*full.size.x*.12,point.y,point.z)
    joints[bone]={"pivot":[at.x,at.y,at.z],"parent":"body"}
   piece.bone=bone
  elif group=="tail":
   if not joints.has("tail_1"):joints.tail_1={"pivot":[center.x,point.y,center.z+full.size.z*.2],"parent":"body"}
   piece.bone="tail_1"
  else:piece.bone="body"
 return {"pieces":pieces,"rig":{"type":kind,"height_m":maxf(full.size.y,.1),"joints":joints,"lab_adapted":true}}

