extends Node

const LABELS := {"blue":"Azul", "red":"Vermelho", "purple":"Vazio Roxo", "black_flash":"Black Flash", "void":"Vazio Infinito", "shrine":"Santuário Malevolente", "cleave":"Dismantle", "contact_cleave":"Cleave", "world_cut":"Corte espacial", "fuga":"Fuga", "adaptation":"Golpe adaptativo", "ryu_beam":"Raio do Ryu", "yuta_beam":"Raio do Yuta"}
var thing: Thing
var profile := {}
var skills: Array[Dictionary] = []
var selected := 0
var remaining := 0.0
var feedback_left := 0.0
var last_warning := ""
var last_cooldown := 0.0
var last_skill_name := ""
var actions: Array[Node] = []

func setup(body: Thing, settings: Dictionary, lex: LexiconData) -> void:
	thing = body; profile = settings
	for key: String in LABELS:
		if body._def.get("jujutsu", {}).get(key, false): skills.append({"kind":"jujutsu", "key":key, "name":LABELS[key]})
	for key: String in body._def.get("pokemon", {}).get("moves", {}):
		skills.append({"kind":"pokemon", "key":key, "name":body._def.pokemon.moves[key].name})
	if profile.get("projectile", "") != "": skills.append({"kind":"projectile", "key":profile.projectile, "name":lex.thing_name(profile.projectile)})
	for spec: Dictionary in profile.get("actions", []):
		if not Assembler.ACTIONS.has(String(spec.type)): continue
		var action: Node = Assembler.ACTIONS[String(spec.type)].new()
		action.setup(thing, spec); add_child(action); actions.append(action)
		skills.append({"kind":"action", "index":actions.size()-1, "name":String(spec.get("name","Habilidade de "+lex.thing_name(profile.donor)))})
	if body._def.has("builder"): skills.append({"kind":"builder", "name":"Construir / escavar"})
	if body._def.has("ecology"): skills.append({"kind":"ecology", "name":"Criar ninho"})
	if profile.get("verity", false): skills.append({"kind":"verity", "name":"Cura da Verity"})
	if profile.get("flight", false): skills.append({"kind":"flight", "name":"Voo por 8 segundos"})
	if skills.is_empty(): skills.append({"kind":"passive", "name":"Proteção passiva"})

func equipped() -> bool:
	return is_instance_valid(thing) and thing.is_active and not thing.is_dead and not thing.is_building and thing.is_held and not thing.is_captured and is_instance_valid(thing.owner_player) and thing.owner_player.hands.current_item() == thing

func label() -> String: return String(skills[selected % skills.size()].name) + " · R: trocar"
func cycle() -> void:
	if not equipped() or not thing.has_simulation_authority(): return
	selected = (selected + 1) % skills.size()
	thing.ammo_changed.emit()

func _physics_process(delta: float) -> void:
	if not thing.has_simulation_authority(): return
	remaining = maxf(0.0, remaining-delta)
	feedback_left=maxf(0.0,feedback_left-delta)
	var builder := thing.get_node_or_null("CreatureBuilder")
	if not equipped() and builder != null and builder.running: builder.cancel()

func _fire(ctx: ActionContext) -> void: use(ctx)
func use(ctx: ActionContext, skill_key: String = "") -> Dictionary:
	var result: Dictionary = _use(ctx,skill_key)
	if result.get("blocked",false):
		var warnings: Array=result.get("warnings",[])
		last_warning=String(warnings[0]) if not warnings.is_empty() else "A criação está ocupada; tente novamente."
		feedback_left=2.0
	else:
		last_warning="";feedback_left=0
		var used: Dictionary=skills[selected%skills.size()]
		if not skill_key.is_empty():
			for entry:Dictionary in skills:
				if entry.get("key", "")==skill_key:used=entry;break
		last_skill_name=String(used.name)
		last_cooldown=maxf(remaining,float(presentation().get("remaining",0)))
	return result

func _use(ctx: ActionContext, skill_key: String = "") -> Dictionary:
	if not equipped() or not thing.has_simulation_authority() or not thing.owner_player.can_act() or not thing.can_act(): return {"blocked":true,"warnings":["Equipe seus poderes para usá-los."]}
	if remaining > 0.0: return {"blocked":true,"warnings":["Aguarde a recarga dos poderes."]}
	var skill := skills[selected % skills.size()]
	if not skill_key.is_empty():
		var found := false
		for entry: Dictionary in skills:
			if entry.get("key", "") == skill_key: skill = entry; found = true; break
		if not found: return {"blocked":true,"warnings":["Esse poder não possui esse golpe."]}
	var owner := thing.owner_player as Player
	ctx.point = owner.head.global_position
	ctx.direction = owner.look_ray().direction
	match String(skill.kind):
		"jujutsu":
			var user := thing.get_node("Jujutsu")
			if user.clock < user.next_cast: return {"blocked":true,"warnings":["Aguarde a recarga da técnica."]}
			var previous: Dictionary = user.powers
			user.powers = {String(skill.key):true}
			var before:float=user.next_cast
			user.cast(ctx)
			user.powers = previous
			if user.next_cast<=before: return {"blocked":true,"warnings":["Técnica indisponível: aguarde a produção ou o fim do efeito atual."]}
		"pokemon": return thing.get_node("PokemonCompanion").cast(String(skill.key))
		"projectile":
			if get_tree().get_nodes_in_group("spatial_orbs").size() >= 24 or get_tree().get_nodes_in_group("cursed_beams").size() >= 24: return {"blocked":true}
			if Forge.spawn_child(Recipe.new_node(String(skill.key)), "projectile", ctx.point+ctx.direction*1.2, ctx.direction, thing, -1.0, Vector3.ZERO, true) == null: return {"blocked":true}
			remaining = 6.0
		"action":
			var action=actions[int(skill.index)]
			if action.spec.get("type","")=="crossover":
				var kit=thing.get_node_or_null("Crossover")
				if kit.remaining>0: return {"blocked":true,"warnings":["Aguarde %.1f s: recarga compartilhada do Sans."%kit.remaining]}
				if not kit.use(ctx,String(action.spec.get("mode",""))):return {"blocked":true,"warnings":["Nenhum alvo válido ou limite de criação atingido."]}
			else:action.run(ctx)
			remaining = maxf(1.5, float(profile.get("action_cooldown", 2.5)))
		"builder":
			var ray := owner.look_ray()
			return thing.get_node("CreatureBuilder").begin(ray.origin+ray.direction*2.0, ray.direction)
		"ecology":
			var id := String(thing._def.ecology.get("produces", ""))
			var at := Forge.ground_point(owner.global_position+ctx.direction*2.0)
			if Forge.spawn_child(Recipe.new_node(id), "spawned", at, ctx.direction, thing, 0.0, Vector3.ZERO, true) == null: return {"blocked":true}
			remaining = maxf(4.0, float(thing._def.ecology.get("interval", 8)))
		"verity":
			if owner.health >= owner.max_health*.6: return {"blocked":true,"warnings":["A cura da Verity só funciona abaixo de 60% da vida."]}
			owner.health = minf(owner.max_health*.6, owner.health+4.0); owner.health_changed.emit(owner.health,owner.max_health); remaining = 4.0
		"flight":
			var price := Lexicon.balf("abilities.fly.cost")
			if not owner.try_spend(price): return {"blocked":true,"warnings":["Matéria insuficiente para voar."]}
			if not owner.apply_ability("fly", 8.0): owner.add_matter(price); return {"blocked":true}
			remaining = 10.0
		"passive": return {"warnings":["Proteção ativa enquanto estes poderes estão selecionados."]}
	last_skill_name=String(skill.name)
	last_cooldown=maxf(remaining,float(presentation().get("remaining",0)))
	return {"personal_power":profile.donor,"personal_skill":skill.get("key",skill.kind)}

func snapshot() -> Dictionary: return {"selected":selected,"remaining":remaining,"label":label(),"last_warning":last_warning,"feedback_left":feedback_left,"last_cooldown":last_cooldown,"last_skill_name":last_skill_name}
func apply_snapshot(state: Dictionary) -> void:
	selected = clampi(int(state.get("selected",0)), 0, maxi(0,skills.size()-1))
	remaining = maxf(0.0,float(state.get("remaining",0)))
	last_warning=String(state.get("last_warning",""));feedback_left=maxf(0,float(state.get("feedback_left",0)));last_cooldown=maxf(0,float(state.get("last_cooldown",0)));last_skill_name=String(state.get("last_skill_name",""))


func presentation() -> Dictionary:
	var skill:Dictionary=skills[selected%skills.size()]
	var kind:=String(skill.kind);var key:=String(skill.get("key",""))
	var base:=0.0;var wait:=remaining;var price:=0.0;var cost_text:="Uso: 0 de matéria"
	var total:=last_cooldown;var shared:=false;var source:=last_skill_name;var phase:="";var reason:=""
	var owner=thing.owner_player
	var user=thing.get_node_or_null("Jujutsu")
	if kind=="jujutsu" and user!=null:
		base=user.cooldown_for(key);wait=maxf(wait,user.next_cast-user.clock);total=maxf(total,user.last_cast_cooldown);shared=true
		source=String(LABELS.get(user.last_cast_key,user.last_cast_key))
		if not user.pending_attack.is_empty():reason="Preparando a técnica: %.1f s"%maxf(0,float(user.pending_attack.at)-user.clock)
		elif user.enabled("amplification"):reason="Amplificação ativa: outras técnicas suspensas"
	elif kind=="pokemon":
		var companion=thing.get_node("PokemonCompanion");base=float(companion.moves.get(key,{}).get("cooldown",0));wait=maxf(wait,companion.remaining);shared=true
	elif kind=="projectile":base=6.0
	elif kind=="action":
		base=maxf(1.5,float(profile.get("action_cooldown",2.5)))
		var spec:Dictionary=actions[int(skill.index)].spec
		if spec.get("type","")=="crossover":
			var kit=thing.get_node("Crossover");wait=maxf(wait,kit.remaining);shared=true
			base=float({"bones":2.8,"blue_bones":2.8,"blaster":5.0,"gravity":6.0}.get(String(spec.get("mode","")),base))
	elif kind=="flight":base=10;price=Lexicon.balf("abilities.fly.cost");cost_text="Uso: %s de matéria"%Lexicon.data.format_number(price)
	elif kind=="ecology":base=maxf(4,float(thing._def.ecology.get("interval",8)))
	elif kind=="verity":
		base=4
		if is_instance_valid(owner) and owner.health>=owner.max_health*.6:reason="Cura disponível abaixo de 60% da vida"
	elif kind=="builder":
		var builder=thing.get_node("CreatureBuilder");cost_text=builder.requirements();wait=maxf(wait,(builder.cooldown_until-Time.get_ticks_msec())/1000.0)
		if builder.running:reason="Construção em andamento"
	if user!=null:
		if user.powers.has("infinity"):
			var active:=8.0 if user.gojo_profile() else 16.0;var position:float=fmod(user.clock,24.0)
			phase="Infinito ativo: %.1f s"%(active-position) if user.enabled("infinity") else "Infinito indisponível: %.1f s"%(24.0-position)
		if user.domain_until>user.clock:
			phase+=("\n" if not phase.is_empty() else "")+"Domínio ativo: %.1f s"%(user.domain_until-user.clock)
	if not equipped():reason="Equipe estes poderes para usar"
	elif is_instance_valid(owner):
		if Status.paralyzed(owner):reason="Paralisado: você não pode usar poderes"
		elif not thing.can_act():reason="Estes poderes estão bloqueados"
		elif not owner.can_act():reason="Você não pode agir agora"
		elif not Forge.production_available(thing):reason="Aguarde a produção em andamento"
		elif Forge.is_assembling(owner.player_id):reason="Aguarde a montagem em andamento"
		elif owner.move!=null and not owner.move.weapon_ready():reason="Pare de correr para usar os poderes"
		elif price>owner.matter+owner.matter_credit+.001:reason="Matéria insuficiente: precisa de %s"%Lexicon.data.format_number(price)
	wait=maxf(0.0,wait)
	if reason.is_empty() and wait>.001:reason="Recarga compartilhada" if shared else "Recarregando"
	if source.is_empty():source="uma técnica"
	var ready:=reason.is_empty()
	var warning:=last_warning if feedback_left>0 else ""
	return {"name":String(skill.name),"cost":price,"cost_text":cost_text,"base_cooldown":base,"remaining":wait,"total":maxf(maxf(base,total),wait),"shared":shared,"source":source,"ready":ready,"reason":reason,"warning":warning,"phase":phase,"passive":kind=="passive"}

extends Node

var thing: Thing
var pokemon_id := ""
var element := ""
var moves := {}
var remaining := 0.0
var last_move := ""
var casts := 0
var dash_left := 0.0
var dash_direction := Vector3.ZERO
var experience := 0.0
var evolution := {}

func setup(owner_thing: Thing, settings: Dictionary) -> void:
	thing = owner_thing
	pokemon_id = settings.id
	element = settings.element
	moves = settings.moves
	evolution = settings.get("evolution", {})

func _ready() -> void: add_to_group("pokemon_companions")

func _physics_process(delta: float) -> void:
	if thing.is_active and not thing.is_captured: remaining = maxf(0.0, remaining - delta)
	if dash_left > 0.0 and available():
		dash_left = maxf(0.0, dash_left - delta)
		if not thing._def.has("personal_power"): thing.move.travel(dash_direction * minf(delta, .05) * 14.0)

func available() -> bool:
	if not is_instance_valid(thing): return false
	var personal := thing.get_node_or_null("PersonalPowers")
	if personal==null:
		personal=thing.get_node_or_null("SkillEcho")
		if personal!=null and (not personal.executing or personal.clip.is_empty() or personal.left<=0 or personal.uses<=0):return false
	return thing.is_active and not thing.is_building and (not thing.is_held or (personal != null and personal.equipped() and thing.owner_player.can_act())) and not thing.is_captured and not thing.is_dead and thing.can_act()

func _visible_target(target: Node3D) -> bool:
	var query := PhysicsRayQueryParameters3D.create(thing.center(), Combat.center_of(target), PhysicsLayers.WORLD, [thing.get_rid()])
	return thing.get_world_3d().direct_space_state.intersect_ray(query).is_empty()

func _target(reach: float) -> Node3D:
	var best: Node3D
	var score := INF
	var ray: Dictionary = thing.owner_player.look_ray() if is_instance_valid(thing.owner_player) and thing.owner_player.has_method("look_ray") else {}
	for target in Combat.in_radius(thing, thing.center(), reach):
		if not is_instance_valid(target) or not target.has_method("take_damage") or not Combat.affects(thing, target): continue
		if target.has_method("is_alive") and not target.is_alive(): continue
		if target is Thing and (target.is_dead or target.is_captured or target.category not in ["creature", "vehicle"]): continue
		var at := Combat.center_of(target)
		var distance := thing.center().distance_to(at)
		if distance > reach or not _visible_target(target): continue
		var value := distance
		if not ray.is_empty():
			var alignment := (at - (ray.origin as Vector3)).normalized().dot(ray.direction)
			value += (1.0 - alignment) * 8.0
		if value < score:
			score = value
			best = target
	return best

func cast(move: String) -> Dictionary:
	if not available() or not moves.has(move): return {"blocked": true, "warnings": ["Pokémon indisponível para atacar."]}
	if remaining > 0.0: return {"blocked": true, "warnings": ["Aguarde %.1f s para outro golpe." % remaining]}
	var fusion = thing.get_node_or_null("FusionPowers")
	if fusion != null and fusion.companions.is_empty(): fusion = null
	if fusion != null and fusion.remaining > 0.0: return {"blocked":true,"warnings":["A fusão está recarregando seus poderes."]}
	var skill: Dictionary = moves[move]
	var target := _target(float(skill.range) * clampf(thing.scale_factor, .6, 1.5))
	if target == null: return {"blocked": true, "warnings": ["Nenhum alvo válido à vista e ao alcance de " + String(skill.name) + "."]}
	remaining = float(skill.cooldown)
	if fusion != null: fusion.remaining = maxf(2.5,remaining)
	last_move = move
	casts += 1
	thing.set_meta("last_copyable_skill",{"kind":"pokemon","donor":pokemon_id,"key":move,"damage_kind":String(skill.element),"recorded_at":Time.get_ticks_msec()})
	var at := Combat.center_of(target)
	var origin := thing.center()
	if skill.style == "quick":
		dash_direction = Gravity.flat(at - origin, thing.up()).normalized()
		dash_left = minf(.18, maxf(0.0, origin.distance_to(at) - 1.0) / 14.0)
		if thing._def.has("personal_power"): thing.owner_player.apply_knockback(dash_direction*8.0)
	var target_power := target.get_node_or_null("PokemonCompanion")
	var multiplier := 1.0
	if target_power != null:
		var advantage := {"electric": "water", "fire": "grass", "water": "fire", "grass": "water"}
		if advantage.get(skill.element, "") == target_power.element: multiplier = 1.5
		elif skill.element == target_power.element and skill.element != "normal": multiplier = .65
		elif advantage.get(target_power.element, "") == skill.element: multiplier = .7
	var previous: Variant = target.get("health")
	if previous == null: previous = target.get("hp")
	Combat.apply_damage(target, float(skill.damage) * clampf(thing.power, .25, 2.0) * multiplier, String(skill.element), thing, String(skill.style))
	if is_instance_valid(target):
		var current: Variant = target.get("health")
		if current == null: current = target.get("hp")
		if previous != null and current != null and float(current) < float(previous) and skill.element == "fire": Status.apply(target, "burning", thing, .35)
	load("res://scripts/fx/pokemon_fx.gd").play(Forge.fx_root(thing), origin, at, String(skill.style), String(skill.name))
	return {"pokemon_order": pokemon_id, "pokemon_move": move, "pokemon_network_id": thing.network_id}

static func order(player: Node3D, settings: Dictionary) -> Dictionary:
	if not player.can_act(): return {"blocked": true, "warnings": ["Você não pode comandar agora."]}
	var held = player.hands.current_item()
	if held != null and held._def.has("personal_power") and not settings.has("pokemon_action"):
		var personal = held.get_node_or_null("PokemonCompanion")
		if personal != null and personal.pokemon_id == settings.pokemon: return personal.cast(String(settings.move))
	var selected: Node
	var distance := INF
	for companion in player.get_tree().get_nodes_in_group("pokemon_companions"):
		if not companion.available() or companion.pokemon_id != settings.pokemon or companion.thing.owner_id != player.player_id or companion.thing.team != player.team: continue
		var d: float = companion.thing.global_position.distance_to(player.global_position)
		if d > 60.0: continue
		# Prefer a ready companion, then the nearest one; a single order never fires a whole swarm.
		var rank: float = d + (1000.0 if not settings.has("pokemon_action") and companion.remaining > 0.0 else 0.0)
		if rank < distance:
			distance = rank
			selected = companion
	if selected == null: return {"blocked": true, "warnings": ["Invoque ou solte da Pokébola um " + String(settings.pokemon).capitalize() + " seu por perto antes de comandar."]}
	if settings.get("pokemon_action") == "progress": return {"warnings": [selected.progress_text()]}
	if settings.get("pokemon_action") == "evolve": return selected.evolve(player)
	return selected.cast(String(settings.move))

func progress_text() -> String:
	var title := Lexicon.data.thing_name(pokemon_id)
	if String(evolution.get("next", "")).is_empty(): return "%s: forma final · %.0f XP." % [title, experience]
	return "%s: %.0f/%.0f XP · evolução para %s custa %.0f de matéria. Diga: %s, evolua." % [title, experience, float(evolution.xp), Lexicon.data.thing_name(evolution.next), float(evolution.cost), title]

func evolve(player: Node3D) -> Dictionary:
	var temporary = thing.get_node_or_null("CreativeEffects")
	if temporary != null and (temporary.head_time > 0.0 or temporary.team_time > 0.0): return {"blocked":true,"warnings":["Aguarde o fim da troca temporária antes de evoluir."]}
	if not available() or not thing.has_simulation_authority() or player.player_id != thing.owner_id or player.team != thing.team:
		return {"blocked": true, "warnings": ["Pokémon indisponível para evoluir."]}
	var next := String(evolution.get("next", ""))
	if next.is_empty() or experience < float(evolution.xp): return {"blocked": true, "warnings": [progress_text()]}
	var price := float(evolution.cost)
	if not player.try_spend(price): return {"blocked": true, "warnings": [progress_text() + " Matéria insuficiente."]}
	experience -= float(evolution.xp)
	change_form(next)
	# Paid matter stays with this same individual; no free healing or duplicate creature.
	thing.matter += price
	ExpansionFx.burst(Forge.fx_root(thing), thing.center(), 1.8, Color("f5e2a0"), "evolution")
	return {"pokemon_evolved": next, "evolution_cost": price, "warnings": ["Evoluiu para " + Lexicon.data.thing_name(next) + ". " + progress_text()]}

func change_form(next: String) -> void:
	var settings: Dictionary = Lexicon.data.thing_def(next).get("pokemon", {})
	if settings.is_empty() or next == pokemon_id: return
	var ratio := clampf(thing.hp / maxf(thing.max_hp, .001), 0.0, 1.0)
	var original := thing.thing_id
	var mods: Dictionary = thing.node_data.get_or_add("mods", {})
	var anatomy: Dictionary = mods.get("anatomy", {})
	if anatomy.get("head") == pokemon_id:
		anatomy.head = next
	elif original == pokemon_id:
		thing.node_data.thing = next
		thing._def = Lexicon.data.thing_def(next)
	else: return
	var was_automatic := thing.automatic
	thing.rebuild_equipment_model()
	thing.hp = thing.max_hp * ratio
	thing.automatic = was_automatic
	if anatomy.has("legs"): thing.speed = Lexicon.data.thing_statf(String(anatomy.legs), "speed") * float(mods.get("speed", 1.0))
	# Existing grafts and gameplay components remain the same objects, keeping their timers.
	var motion = thing.get_node_or_null("VoxelCreatureMotion")
	if motion != null:
		motion.parts.clear()
		motion.setup(thing, bool(thing._def.get("aerial", false)) or anatomy.has("wings"))
	var role_def: Dictionary = thing._def.get("roles", {}).get(thing.role, {})
	var movement := Assembler.movement_id(thing.node_data, thing._def, role_def, thing.role, Lexicon.data)
	if original == pokemon_id and movement == "fly" and not thing.move.hovers():
		var old_move := thing.move
		thing.remove_child(old_move)
		old_move.queue_free()
		var new_move: ThingMove = Assembler.MOVES.fly.new()
		new_move.name = "Move"
		new_move.setup(thing, Lexicon.data)
		thing.attach_move(new_move)
		if thing.network_replica: new_move.set_physics_process(false)
	setup(thing, settings)

func snapshot() -> Dictionary:
	return {"id": pokemon_id, "xp": experience, "remaining": remaining, "last_move": last_move, "casts": casts}

func apply_snapshot(values: Dictionary) -> void:
	var next := String(values.get("id", pokemon_id))
	# Only forward steps in this family are accepted, including a skipped intermediate snapshot.
	var cursor := pokemon_id
	for step in 3:
		if cursor == next: break
		cursor = String(Lexicon.data.thing_def(cursor).get("pokemon", {}).get("evolution", {}).get("next", ""))
	if cursor != next: return
	change_form(next)
	experience = clampf(float(values.get("xp", 0.0)), 0.0, 1000.0)
	remaining = maxf(0.0, float(values.get("remaining", 0.0)))
	last_move = String(values.get("last_move", ""))
	casts = int(values.get("casts", 0))

static func record_damage(source: Thing, target: Object, damage: float) -> void:
	if not is_instance_valid(source) or not is_instance_valid(target) or damage <= 0.0 or not (target is Thing or target is Player): return
	if target is Thing and (target.category != "creature" or target.is_held or target.is_captured): return
	var cursor := source
	var seen := {}
	for step in 8:
		if not is_instance_valid(cursor) or seen.has(cursor.get_instance_id()): return
		seen[cursor.get_instance_id()] = true
		var companion = cursor.get_node_or_null("PokemonCompanion")
		if companion != null:
			if cursor.is_dead or cursor.is_captured or cursor.is_building or not cursor.is_active or cursor.owner_id <= 0: return
			if target == cursor or target.get("team") == cursor.team or target.get("owner_id") == cursor.owner_id or target == cursor.owner_player: return
			var paid: Dictionary = target.get_meta("pokemon_xp_paid", {})
			var key := cursor.get_instance_id()
			if not paid.has(key) and paid.size() >= 64: return
			var earned := minf(damage * .25, maxf(0.0, 60.0 - float(paid.get(key, 0.0))))
			paid[key] = float(paid.get(key, 0.0)) + earned
			target.set_meta("pokemon_xp_paid", paid)
			companion.experience = minf(1000.0, companion.experience + earned)
			return
		cursor = cursor.mount_host if is_instance_valid(cursor.mount_host) else cursor.spawner as Thing

