extends Node
const JUJUTSU := ["blue","red","purple","black_flash","cleave","contact_cleave","world_cut","fuga","ryu_beam","yuta_beam"]
var thing: Thing
var clip:Dictionary={}
var left:=0.0
var uses:=0
var executing:=false
func setup(body: Thing) -> void:
	thing=body;thing.fired.connect(_fire)
func equipped() -> bool:return thing.can_act() and thing.is_held and is_instance_valid(thing.owner_player) and thing.owner_player.hands.current_item()==thing
func _physics_process(delta: float) -> void:
	if not thing.has_simulation_authority():return
	left=maxf(0.0,left-delta)
	if left<=0 or uses<=0:
		clip.clear()
		var cursed=thing.get_node_or_null("Jujutsu")
		if cursed!=null and cursed.pending_attack.is_empty():cursed.powers.clear()
static func record(target: Object, source: Thing, kind: String) -> void:
	if not target is Player or not is_instance_valid(source) or source.team==target.team:return
	var record:Dictionary={};var cursor:=source;var seen:Dictionary={}
	var ids:Dictionary={"cursed_blue":"blue","reversal_red":"red","hollow_purple":"purple","sukuna_fire_arrow":"fuga","sukuna_dismantle_wave":"cleave","ryu_beam_stream":"ryu_beam","yuta_beam_stream":"yuta_beam"}
	for step in 8:
		if not is_instance_valid(cursor) or seen.has(cursor.get_instance_id()):break
		seen[cursor.get_instance_id()]=true
		if ids.has(cursor.thing_id):record={"kind":"jujutsu","key":ids[cursor.thing_id]};break
		if cursor==source and cursor.has_meta("last_copyable_skill"):
			var candidate:Dictionary=cursor.get_meta("last_copyable_skill")
			if candidate.get("damage_kind")==kind and Time.get_ticks_msec()-int(candidate.get("recorded_at",0))<500:record=candidate.duplicate();break
		cursor=cursor.mount_host if is_instance_valid(cursor.mount_host) else cursor.spawner as Thing
	if record.is_empty() or (record.get("kind")=="jujutsu" and record.get("key") not in JUJUTSU):target.remove_meta("last_copyable_hit");return
	record["at"]=Time.get_ticks_msec();target.set_meta("last_copyable_hit",record)
func copy_skill() -> Dictionary:
	if not equipped():return {"blocked":true,"warnings":["Equipe o mimetizador."]}
	var owner=thing.owner_player;var now:=Time.get_ticks_msec()
	if int(owner.get_meta("echo_cooldown",0))>now:return {"blocked":true,"warnings":["A cópia de poderes recarrega por 15 s, mesmo trocando de arma."]}
	var incoming:Dictionary=owner.get_meta("last_copyable_hit",{})
	if incoming.is_empty() or now-int(incoming.get("at",0))>8000:return {"blocked":true,"warnings":["Nenhum poder inimigo compatível acertou você nos últimos 8 s."]}
	if incoming.get("kind")=="jujutsu" and incoming.get("key") not in JUJUTSU:return {"blocked":true}
	if not owner.try_spend(25):return {"blocked":true,"warnings":["Copiar custa 25 de matéria."]}
	clip=incoming.duplicate();left=8.0;uses=3;owner.set_meta("echo_cooldown",now+15000)
	if clip.kind=="jujutsu":
		var user=thing.get_node_or_null("Jujutsu")
		if user==null:user=load("res://scripts/things/jujutsu_user.gd").new();user.name="Jujutsu";user.setup(thing,{});thing.add_child(user)
		user.powers={String(clip.key):true}
	else:
		var settings:Dictionary=Lexicon.data.thing_def(String(clip.get("donor",""))).get("pokemon",{}).duplicate(true)
		if settings.is_empty() or not settings.get("moves",{}).has(clip.key):clip.clear();owner.add_matter(25);return {"blocked":true}
		settings.evolution={}
		var companion=thing.get_node_or_null("PokemonCompanion")
		if companion==null:companion=load("res://scripts/things/pokemon_companion.gd").new();companion.name="PokemonCompanion";companion.setup(thing,settings);thing.add_child(companion)
		else:companion.setup(thing,settings)
	return {"warnings":["Copiado: "+String(clip.key)+" · 8 s, até três usos, com recargas originais. Clique para usar."]}
func _fire(ctx: ActionContext) -> void:use(ctx)
func use(ctx: ActionContext) -> Dictionary:
	if not equipped():return {"blocked":true}
	if clip.is_empty():return copy_skill()
	ctx.point=thing.owner_player.head.global_position;ctx.direction=thing.owner_player.look_ray().direction
	if clip.kind=="jujutsu":
		var user=thing.get_node("Jujutsu")
		if user.clock<user.next_cast:return {"blocked":true}
		var before:float=user.next_cast
		user.powers={String(clip.key):true};user.cast(ctx)
		if user.next_cast<=before:return {"blocked":true}
	else:
		executing=true
		var reply:Dictionary=thing.get_node("PokemonCompanion").cast(String(clip.key))
		executing=false
		if reply.get("blocked",false):return reply
	uses-=1;return {"warnings":["Poder copiado usado · restam %d usos."%uses]}
func snapshot() -> Dictionary:return {"clip":clip,"left":left,"uses":uses}
func apply_snapshot(data: Dictionary) -> void:clip=data.get("clip",{});left=float(data.get("left",0));uses=int(data.get("uses",0))

extends Node

static var frame := -1
static var processed := 0
var source: Thing
var rows := []
var cursor := 0

func setup(owner_thing: Thing) -> void:
	source = owner_thing
	source.hold_effect_job()

func add_segment(from: Vector3, to: Vector3, radius: float, damage: float = -1.0) -> void:
	var steps := clampi(ceili(from.distance_to(to) / maxf(radius * .65, .4)), 1, 32)
	for i in steps:
		var at := from.lerp(to, float(i + 1) / steps)
		for node in get_tree().get_nodes_in_group(BlockVolume.GROUP):
			var volume := node as BlockVolume
			var box := volume.global_transform * AABB(volume.origin, Vector3(volume.dims) * volume.size_m)
			if at.distance_to(at.clamp(box.position, box.end)) <= radius:
				rows.append({"volume": weakref(volume), "at": at, "radius": radius, "damage": damage})

func _process(_delta: float) -> void:
	if frame != Engine.get_process_frames():
		frame = Engine.get_process_frames()
		processed = 0
	var until := Time.get_ticks_usec() + 2500
	while cursor < rows.size() and processed < 2:
		var row: Dictionary = rows[cursor]
		cursor += 1
		processed += 1
		var volume = row.volume.get_ref()
		if is_instance_valid(volume):
			if row.damage < 0.0: volume.erase_sphere(row.at, row.radius)
			else: volume.explode(row.at, row.radius, row.damage)
		if Time.get_ticks_usec() >= until: break
	if cursor >= rows.size():
		if is_instance_valid(source): source.release_effect_job()
		queue_free()

extends Node

const GROUP := "spatial_orbs"
static var annihilations := 0
static var purple_fusions := 0

var thing: Thing
var config: Dictionary
var mode := ""
var resolved := false
var previous := Vector3.ZERO
var elapsed := 0.0
var pulse_left := 0.0
var fx_left := 0.0
var terrain_left := 0.0
var scan_cursor := 0
var struck := {}
var damage_work: Node
var terrain_work: Node
var terrain_from := Vector3.ZERO
var aura: Node3D

func _ready() -> void:
	add_to_group(GROUP)
	if mode == "purple":
		aura = Node3D.new()
		thing.model.add_child(aura)
		var cube := BoxMesh.new()
		cube.size = Vector3.ONE
		var material := StandardMaterial3D.new()
		material.albedo_color = Color("bc6bff")
		material.emission_enabled = true
		material.emission = Color("923bff")
		material.emission_energy_multiplier = 3.0
		for i in 36:
			var bit := MeshInstance3D.new()
			bit.mesh = cube
			bit.material_override = material
			var angle := TAU * (i % 12) / 12.0
			var point := Vector3(cos(angle), sin(angle), 0) * 1.25
			if i >= 24: point = Vector3(point.x, 0, point.y)
			elif i >= 12: point = Vector3(0, point.x, point.y)
			bit.position = point
			bit.scale = Vector3.ONE * (.24 if i % 3 == 0 else .13)
			aura.add_child(bit)

func setup(owner_thing: Thing, settings: Dictionary) -> void:
	thing = owner_thing
	config = settings
	mode = String(config.mode)
	process_physics_priority = -30

func activate() -> void:
	previous = thing.center()
	terrain_from = previous
	thing.lifetime = float(config.get("life", 6.0))
	thing.collision_mask = 0

func _process(delta: float) -> void:
	if is_instance_valid(thing) and not thing.is_dead and thing.model != null:
		thing.model.rotate_y(delta * 2.0)
		thing.model.rotate_z(delta * 0.7)
		if aura != null:
			aura.rotation.y -= delta * 3.5
			aura.scale = Vector3.ONE * (1.0 + sin(Time.get_ticks_msec() * .012) * .1)

func _physics_process(delta: float) -> void:
	if not is_instance_valid(thing) or thing.is_dead or not thing.is_active or thing.is_held or resolved or not thing.has_simulation_authority(): return
	elapsed += delta
	var point := thing.center()
	if _collide(point): return
	if mode == "red":
		_red(point)
		previous = point
		return
	fx_left -= delta
	if fx_left <= 0.0:
		fx_left = 0.18 if mode == "purple" else .45
		ExpansionFx.burst(Forge.fx_root(thing), point, 2.4 if mode == "purple" else 1.5, _color(), mode)
	if mode == "purple":
		_purple(previous, point)
		terrain_left -= delta
		if terrain_left <= 0.0:
			terrain_left = 0.10
			if not is_instance_valid(terrain_work) or terrain_work.is_queued_for_deletion():
				terrain_work = load("res://scripts/things/spatial_cut_work.gd").new()
				terrain_work.setup(thing)
				get_tree().root.add_child(terrain_work)
			terrain_work.add_segment(terrain_from, point, clampf(2.2 * thing.scale_factor, 1.0, 4.0))
			terrain_from = point
	else:
		pulse_left -= delta
		if pulse_left <= 0.0:
			pulse_left = 0.20
			_field(point)
	previous = point
	if elapsed >= float(config.get("life", 6.0)) - delta:
		resolved = true
		if mode != "purple": Combat.explode(thing, point, 3.0 if _pulls() else 4.0, 50.0 if _pulls() else 100.0)
		thing.remove()

func _pulls() -> bool:
	return mode in ["black", "blue"]

func _color() -> Color:
	return Color(String(config.get("color", "#a879ff")))

func _opposite(other: String) -> bool:
	return (mode == "black" and other == "white") or (mode == "white" and other == "black") or (mode == "blue" and other == "red") or (mode == "red" and other == "blue")

func _collide(point: Vector3) -> bool:
	if mode == "white":
		for hole in get_tree().get_nodes_in_group("singularities"):
			if not is_instance_valid(hole) or hole.replica or hole._burst: continue
			var near := Geometry3D.get_closest_point_to_segment(hole.global_position,previous,point)
			if near.distance_to(hole.global_position) > hole.horizon + .6 * thing.scale_factor: continue
			resolved = true
			annihilations += 1
			if Session.is_online(): Session.creations.notify_fx("lab_singularity_cancel",[hole.network_id])
			ExpansionFx.burst(Forge.fx_root(thing),hole.global_position,6.0,Color("fff1d1"),"annihilation")
			hole._collapse()
			thing.remove()
			return true
	for other in get_tree().get_nodes_in_group(GROUP):
		if other == self or not is_instance_valid(other) or other.resolved or not _opposite(other.mode): continue
		var peer: Thing = other.thing
		if not is_instance_valid(peer) or peer.is_dead or peer.is_held or not peer.is_active: continue
		var start: Vector3 = previous - other.previous
		var finish := point - peer.center()
		var travel := finish - start
		var t := clampf(-start.dot(travel) / travel.length_squared(), 0.0, 1.0) if travel.length_squared() > 0.00001 else 0.0
		if (start + travel * t).length() > 0.60 * (thing.scale_factor + peer.scale_factor): continue
		resolved = true
		other.resolved = true
		var at := (point + peer.center()) * 0.5
		if mode in ["black", "white"]:
			annihilations += 1
			ExpansionFx.burst(Forge.fx_root(thing), at, 6.0, Color("fff1d1"), "annihilation")
			Combat.explode(thing, at, 8.0, 160.0)
		else:
			purple_fusions += 1
			var red: Thing = thing if mode == "red" else peer
			var heading := red.velocity.normalized() if red.velocity.length_squared() > 0.01 else -red.global_basis.z
			# The two claimed orbs are replaced with one; this cannot multiply actors.
			Forge.spawn_child(Recipe.new_node("hollow_purple"), "projectile", at, heading, red, 20.0, Vector3.ZERO, true, 1.0, true)
			ExpansionFx.burst(Forge.fx_root(thing), at, 3.0, Color("ba7dff"), "purple")
		peer.remove()
		thing.remove()
		return true
	return false

func _candidates() -> Array:
	var out := get_tree().get_nodes_in_group(Combat.COMBATANTS_GROUP)
	if Forge.world != null: out.append_array(Forge.world.get_node("Things").get_children())
	return out

func _allowed(target: Node) -> bool:
	if not is_instance_valid(target) or target == thing or target == thing.spawner or target == thing.owner_player: return false
	if not target.has_method("take_damage"): return false
	if target is Thing and (target.is_dead or target.is_held or target.get_node_or_null("SpatialOrb") != null): return false
	var rival := JujutsuRules.rival_target(thing)
	if rival != null: return target == rival
	return InnovationRules.allows_target(thing, target)

func _red(point: Vector3) -> void:
	var query := PhysicsRayQueryParameters3D.create(previous, point, PhysicsLayers.WORLD)
	var hit := thing.get_world_3d().direct_space_state.intersect_ray(query) if previous.distance_squared_to(point) > .00001 else {}
	var detonates := not hit.is_empty() or elapsed >= 1.8
	if not hit.is_empty(): point = hit.position
	for target in _candidates():
		if not _allowed(target): continue
		var at := Combat.center_of(target)
		var near := Geometry3D.get_closest_point_to_segment(at, previous, point)
		var radius: float = minf(1.5, target.bounds.size.length() * .25) if target is Thing else .6
		if at.distance_to(near) <= .5 + radius: detonates = true; break
	if not detonates: return
	resolved = true
	_field(point)
	var rows := []
	for target in _candidates():
		if not _allowed(target) or Combat.center_of(target).distance_to(point) > 4.0: continue
		rows.append({"target": weakref(target), "damage": 80.0 * clampf(thing.power, .5, 2.0) * (1.0 - .7 * Combat.center_of(target).distance_to(point) / 4.0), "push": Vector3.ZERO, "type": "gravity"})
	if not rows.is_empty():
		var work = load("res://scripts/things/blast_work.gd").new()
		work.setup(thing, rows)
		get_tree().root.add_child(work)
	Combat._crater(thing, point, 4.0, 80.0)
	load("res://scripts/fx/jujutsu_impact.gd").play(Forge.fx_root(thing), point, thing.travel_direction(), "red_burst")
	thing.remove()

func _field(at: Vector3) -> void:
