		for mesh in actor.model_pieces:
			if mesh.get_meta("tag","")=="paw":paws.append(mesh)
		check(paws.size()==4,"Elephant should keep four paws: "+phrase)
		var previous:Array=[]
		for paw in paws:previous.append(paw.global_position)
		for sample in 360:
			animator.distance+=.025;animator._pose(1.0/60.0,3.0,0.0 if sample<240 else .8)
			for paw in paws:
