				max_tilt=maxf(max_tilt,tilt)
				max_lift=maxf(max_lift,absf(paw.global_position.y-(previous[paws.find(paw)] as Vector3).y))
		check(animator.bones.has("foot_fl") and animator.bones.has("foot_hr"),"Elephant lacks independent foot support: "+phrase)
		check(actor.collisions.size()<=int(lex.bal("caps.creature_collision_bones",12))+actor.grafts.size(),"Foot support exceeded collision budget")
		actor.rebuild_equipment_model();actor.creature_animator.set_process(false);actor.creature_animator._pose(.1,3,0)
		check(actor.creature_animator.level_feet.size()==4,"Rebuilding equipment lost foot support")
		actor.remove()
	check(max_tilt<.1,"Elephant paws tilt onto their tips during gait: %.2f degrees"%max_tilt)
	check(max_lift>.05,"Feet were frozen instead of stepping")
	check(JSON.stringify(lex.models.elephant)==original_model,"Foot adaptation mutated the shared original model")
	print("ELEPHANT_GAIT ",JSON.stringify({"failures":failures,"max_paw_tilt_deg":max_tilt,"max_lift_m":max_lift,"variants":4}))
	quit(0 if failures.is_empty() else 1)

